INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('0011452e-b306-49d7-92a2-4044cf1ca5ec'::uuid, 'card_description', 'The zoomorphic motifs are scratched into the side of a large solitary rock and depict two animals, possibly goats.', 'In a Galician pine forest, two animals, possibly goats, are scratched into a large solitary rock: the Pedra das Cabras. Each has six legs, perhaps a deliberate way to show movement.', 'teaser-card-s027:0011452e-b306-49d7-92a2-4044cf1ca5ec:card_description', 'teaser-card-s027 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '7947cc9f7344f1d0f584b97d126f38b3ce2271fdff73e7f26fdb67f72efadd8c|ce5b4f6e7c5594b94810b83681a4d32ac6bf50ad6a983e2b5ad70539d5130812|ce5b4f6e7c5594b94810b83681a4d32ac6bf50ad6a983e2b5ad70539d5130812', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In a Galician pine forest, two animals, possibly goats, are scratched into a large solitary rock: the Pedra das Cabras. Each has six legs, perhaps a deliberate way to show movement."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies in a pine forest [S1]; the site is in Galicia [S1]; two animals are depicted [S2]; the animals are possibly goats [S2]; the animals are scratched into a large solitary rock [S2]; the site is called the Pedra das Cabras [S1]; each animal has six legs [S3]; the six legs were perhaps a deliberate way to show movement [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Pedra das Cabras (Stone of the Goats) is a petroglyph (rock engraving) [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_das_Cabras]; The Pedra das Cabras lies in a pine forest [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_das_Cabras]; The pine forest of the Pedra das Cabras is in Galicia [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_das_Cabras]; Galicia, where the Pedra das Cabras lies, is in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Galicia_(Spain)]; The motifs are scratched into a large solitary rock [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_das_Cabras]; The engraving shows two animals [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_das_Cabras]; The two animals are possibly goats [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_das_Cabras]; Each of the two animals has six legs [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_das_Cabras]; The six legs were perhaps a deliberate way to show movement [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_das_Cabras]"}]'::jsonb),
    ('0020c4e1-21fd-4174-94ae-912703cb7ec6'::uuid, 'card_description', 'The promontory slopes away steeply to the sea on three sides, and on the landward side there are widely spaced defensive earthworks.', 'Treryn Dinas, a Cornish headland, falls steeply to the sea on three sides. On the landward side rise the ramparts of an Iron Age fort, the massive outer one up to 6.1 metres high.', 'teaser-card-s027:0020c4e1-21fd-4174-94ae-912703cb7ec6:card_description', 'teaser-card-s027 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '9daee6ee33db090029f05f6b4dac47b18b620624a7633e2cf5318aa70594ec7d|5d2537381a897966b6234dd6741909d1b737e6137b52fe4eccc66e5ea7ff2fa9|5d2537381a897966b6234dd6741909d1b737e6137b52fe4eccc66e5ea7ff2fa9', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Treryn Dinas, a Cornish headland, falls steeply to the sea on three sides. On the landward side rise the ramparts of an Iron Age fort, the massive outer one up to 6.1 metres high."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Treryn Dinas is a headland [S1]; it is in Cornwall (Cornish) [S1]; the headland falls steeply to the sea on three sides [S4]; on the landward side there are ramparts [S4, S5, S6]; the ramparts belong to an Iron Age fort [S3]; the outer rampart is massive [S6]; the outer rampart is up to 6.1 metres high [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Treryn Dinas is a headland in Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Treryn_Dinas]; Treryn Dinas is the site of a fort (a promontory fort) [SUPPORTED: https://en.wikipedia.org/wiki/Treryn_Dinas]; The fort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Treryn_Dinas]; The headland falls steeply to the sea on three sides [SUPPORTED: https://en.wikipedia.org/wiki/Treryn_Dinas]; The fort''s defences (ramparts) are on the landward side [SUPPORTED: https://en.wikipedia.org/wiki/Treryn_Dinas]; The fort has several ramparts, the outermost one massive [SUPPORTED: https://en.wikipedia.org/wiki/Treryn_Dinas]; The massive outer rampart is up to 6.1 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Treryn_Dinas]"}]'::jsonb),
    ('0057a907-515b-4bdf-9ca2-72c9004796b3'::uuid, 'card_description', 'Iron Age hillfort near Bigbury in Devon, at ~80 m above the Avon Estuary. A compact 1st-millennium BC defensive site commanding river approaches along a long-used inland route.', 'On a hilltop north east of Bigbury in Devon, approximately 80 metres above sea level, the Iron Age hill fort of Yarrowbury overlooks the waters of the Avon Estuary.', 'teaser-card-s027:0057a907-515b-4bdf-9ca2-72c9004796b3:card_description', 'teaser-card-s027 (teaser-card): teaser card, 164 characters, checked PASS, web-verified VERIFIED', '3d1b8c2b8e2ce6fcd4853ac6f8a4bf1fd812234dd8cf02fe2fed8bdd0a19feb7|479a86723ca17b91255428fc4befb2bdcd2de242aa61a5417c4dfc54498d1a24|479a86723ca17b91255428fc4befb2bdcd2de242aa61a5417c4dfc54498d1a24', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a hilltop north east of Bigbury in Devon, approximately 80 metres above sea level, the Iron Age hill fort of Yarrowbury overlooks the waters of the Avon Estuary."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site stands on a hilltop north east of Bigbury [S1, S2]; Bigbury is in Devon [S1]; the site is approximately 80 metres above sea level [S2]; Yarrowbury is an Iron Age hill fort [S1]; the fort overlooks the Avon Estuary [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Yarrowbury is a hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Yarrowbury]; Yarrowbury dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Yarrowbury]; Yarrowbury lies near Bigbury in Devon [SUPPORTED: https://en.wikipedia.org/wiki/Yarrowbury]; The fort stands on a hilltop north east of Bigbury [SUPPORTED: https://en.wikipedia.org/wiki/Yarrowbury]; The hilltop is approximately 80 metres above sea level [SUPPORTED: https://www.visitsouthdevon.co.uk/blog/read/2022/08/forts-in-south-devon-b570]; The fort overlooks the Avon Estuary [SUPPORTED: https://www.visitsouthdevon.co.uk/blog/read/2022/08/forts-in-south-devon-b570]"}]'::jsonb),
    ('007eaa85-a68d-4310-8cc5-23fcfe7407c6'::uuid, 'card_description', 'A 30-metre Roman column from 250 AD crowned with Jupiter and Ganymede. This cloth-merchant family''s burial monument is the tallest surviving Roman pillar tomb.', 'Once painted, the 23-metre Igel Column is the burial monument of the Secundinii cloth merchants, crowned by Jupiter and Ganymede. Its reliefs show coloni bringing a hare and a rooster.', 'teaser-card-s027:007eaa85-a68d-4310-8cc5-23fcfe7407c6:card_description', 'teaser-card-s027 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'a8dca98d68b85b3d7c980726bb72b6d7487dd12e21180a2a73a4380785466733|77628b9f0370aaca0d1f4d2e83ea229fb531dee0e5238e4cef4a3cf625536a2b|77628b9f0370aaca0d1f4d2e83ea229fb531dee0e5238e4cef4a3cf625536a2b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Once painted, the 23-metre Igel Column is the burial monument of the Secundinii cloth merchants, crowned by Jupiter and Ganymede. Its reliefs show coloni bringing a hare and a rooster."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the column was originally painted [S7]; the Igel Column is 23 metres high [S3]; it is the burial monument of the Secundinii [S2]; the Secundinii were a family of cloth merchants [S2]; the column is crowned by a sculptural group of Jupiter and Ganymede [S3]; its reliefs show coloni bringing donations [S4]; the donations include a hare and a rooster [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Igel Column is a burial monument [SUPPORTED: https://en.wikipedia.org/wiki/Igel_Column]; The burial monument belongs to the Secundinii, a family of cloth merchants [SUPPORTED: https://en.wikipedia.org/wiki/Igel_Column]; The Igel Column is a Roman column standing in Igel near Trier, Germany [SUPPORTED: https://en.wikipedia.org/wiki/Igel_Column]; The column is 23 metres high [SUPPORTED: https://www.trier-info.de/en/places-of-interest/the-igel-column]; The column is crowned by Jupiter and Ganymede [SUPPORTED: https://en.wikipedia.org/wiki/Igel_Column]; The column was once painted [SUPPORTED: https://en.wikipedia.org/wiki/Igel_Column]; The reliefs show coloni (tenant farmers) bringing donations [SUPPORTED: https://en.wikipedia.org/wiki/Igel_Column]; Among the donations the coloni bring are a hare and a rooster [SUPPORTED: https://en.wikipedia.org/wiki/Igel_Column]"}]'::jsonb),
    ('00a511c2-7790-4b06-aa1b-0b3e1e55cbf4'::uuid, 'card_description', 'During the Roman Imperial era, Alba was the capital of the Celtic-speaking polity of Helvii, which had territory covering the area of lower Vivarais.', 'Wine amphora handles and imported ceramics revealed Roman-style houses of the first century BC at the Archaeological Site of Alba-la-Romaine, once the capital of the Helvii.', 'teaser-card-s027:00a511c2-7790-4b06-aa1b-0b3e1e55cbf4:card_description', 'teaser-card-s027 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', 'e4a79b67a0248acc2adef76fbb81a47a348519bc855d0ee35ea2ecee66081175|db50aa9e8dcefcf4a9e247396926060c3a3740e0480c72a8af9eaeacba0f6b41|db50aa9e8dcefcf4a9e247396926060c3a3740e0480c72a8af9eaeacba0f6b41', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Wine amphora handles and imported ceramics revealed Roman-style houses of the first century BC at the Archaeological Site of Alba-la-Romaine, once the capital of the Helvii."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "wine amphora handles were found [S4]; imported ceramics were found [S4]; the finds revealed Roman-style houses [S4]; the houses were inhabited in the first century BC [S4]; the houses lie at the archaeological site of Alba-la-Romaine [S1, S4]; Alba was once the capital of the Helvii [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Archaeological Site of Alba-la-Romaine is the archaeological site of the Gallo-Roman city Alba Helviorum [SUPPORTED: https://en.wikipedia.org/wiki/Archeological_site_of_Alba-la-Romaine]; Alba was once the capital of the Helvii [SUPPORTED: https://en.wikipedia.org/wiki/Archeological_site_of_Alba-la-Romaine]; Imported ceramics were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Archeological_site_of_Alba-la-Romaine]; Wine amphora fragments (collars, handles, lips) were found at the site [SUPPORTED: https://fr.wikipedia.org/wiki/Site_arch%C3%A9ologique_d%27Alba-la-Romaine]; The imported ceramics revealed a habitat of the first century BC (La Tène III) at the site of two domus south-east of the site [SUPPORTED: https://fr.wikipedia.org/wiki/Site_arch%C3%A9ologique_d%27Alba-la-Romaine]; The finds (amphora handles and imported ceramics) revealed Roman-style houses (domus) of the first century BC [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('01ef71b0-4942-486e-bb0e-f13fffd9ebda'::uuid, 'card_description', 'A Neolithic burial cairn 45 metres long with a single chamber of upright slabs capped by lintels. The chamber inside measured 4.5 metres long but less than a metre wide and high.', 'On a ridge of Anglezarke moor lie five large gritstone slabs, remains of the burial chamber of Pikestones, a Neolithic cairn once covered by a huge mound of stones and turves.', 'teaser-card-s027:01ef71b0-4942-486e-bb0e-f13fffd9ebda:card_description', 'teaser-card-s027 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '174a7ebd201dffba7e163141635a0bef8ecc868fd4ee48efde9226575862963a|cffd4eb41a7de6fbcbba8c9835d6f653d6ddc9185cd30a9d5360c5def6808d35|cffd4eb41a7de6fbcbba8c9835d6f653d6ddc9185cd30a9d5360c5def6808d35', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a ridge of Anglezarke moor lie five large gritstone slabs, remains of the burial chamber of Pikestones, a Neolithic cairn once covered by a huge mound of stones and turves."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies on a ridge [S7]; the site is on Anglezarke moor [S1]; five large gritstone slabs remain [S5]; the slabs are remains of the burial chamber [S5]; the site is called Pikestones [S1]; Pikestones is a Neolithic cairn [S1]; the cairn was once covered by a huge mound of stones and turves [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Pikestones is a burial cairn (tomb) on Anglezarke moor, England (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Pikestones]; Pikestones is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Pikestones]; It lies on Anglezarke moor [SUPPORTED: https://en.wikipedia.org/wiki/Pikestones]; Five slabs remain of the site [SUPPORTED: https://en.wikipedia.org/wiki/Pikestones]; The slabs are large [SUPPORTED: https://en.wikipedia.org/wiki/Pikestones]; The slabs are gritstone [SUPPORTED: https://en.wikipedia.org/wiki/Pikestones]; The slabs are the remains of the burial chamber [SUPPORTED: https://en.wikipedia.org/wiki/Pikestones]; The site lies on a ridge [SUPPORTED: https://en.wikipedia.org/wiki/Pikestones]; The cairn was once covered by a huge mound [SUPPORTED: https://en.wikipedia.org/wiki/Pikestones]; The mound was of stones and turves [SUPPORTED: https://en.wikipedia.org/wiki/Pikestones]"}]'::jsonb),
    ('01f368c9-e567-4557-b5ce-21c6d182305d'::uuid, 'card_description', 'Tombs and rock paintings at 4,000 m on a peak called Qucha Quyllur — Quechua for ''lake star''. The dead were laid here among the stars, in a valley the living named Wakan Wayq''u.', 'At about 4,000 metres, on the slope of Llamayuq Q''asa in a valley called Wakan Wayq''u, lies Llamayuq, a site of tombs and rock paintings in Peru''s Cusco Region.', 'teaser-card-s027:01f368c9-e567-4557-b5ce-21c6d182305d:card_description', 'teaser-card-s027 (teaser-card): teaser card, 160 characters, checked PASS, web-verified VERIFIED', '1851b1cfb0b45d6687985f7e3ecbbfc2efb7e0fbf2f1ed1c7e7093b2a1865a56|68063b8d675d1c1596aa600e6585ccbe7c383f62538829993f6aaaeb608f9e11|68063b8d675d1c1596aa600e6585ccbe7c383f62538829993f6aaaeb608f9e11', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At about 4,000 metres, on the slope of Llamayuq Q''asa in a valley called Wakan Wayq''u, lies Llamayuq, a site of tombs and rock paintings in Peru''s Cusco Region."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies at about 4,000 metres [S3]; it lies on the slope of Llamayuq Q''asa [S3]; it lies in a valley called Wakan Wayq''u [S3]; the site is called Llamayuq [S1]; the site has tombs [S1]; the site has rock paintings [S1]; the site is in Peru [S1]; the site is in the Cusco Region [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Llamayuq is a site of tombs and rock paintings in Peru''s Cusco Region (central claim: archaeological site with tombs and paintings) [SUPPORTED: https://en.wikipedia.org/wiki/Llamayuq]; The site has tombs [SUPPORTED: https://en.wikipedia.org/wiki/Llamayuq]; The site has rock paintings [SUPPORTED: https://en.wikipedia.org/wiki/Llamayuq]; The site is in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Llamayuq]; The site is in Peru''s Cusco Region [SUPPORTED: https://en.wikipedia.org/wiki/Llamayuq]; The site lies at about 4,000 metres [SUPPORTED: https://en.wikipedia.org/wiki/Llamayuq]; The site lies on the slope of a mountain pass or ridge (a slope) [SUPPORTED: https://en.wikipedia.org/wiki/Llamayuq]; The slope is that of Llamayuq Q''asa [SUPPORTED: https://en.wikipedia.org/wiki/Llamayuq]; The place lies in a valley called Wakan Wayq''u [SUPPORTED: https://en.wikipedia.org/wiki/Llamayuq]"}]'::jsonb),
    ('0349db41-4fca-4804-b614-e075164512b3'::uuid, 'card_description', 'An ancient Red Sea port active from the 2nd millennium BC to the 7th century AD. Egyptian texts called the region the "Land of the Gods" for its exotic trade goods.', 'Beneath the Red Sea city of Adulis lies a late prehistoric settlement. Excavating from 1906, Richard Sundström exposed a large structure he dubbed its palace and found Axumite coins.', 'teaser-card-s027:0349db41-4fca-4804-b614-e075164512b3:card_description', 'teaser-card-s027 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '615f951e784accfe0ec16c7fe192e4afd6ac4dd261683567829b4f3c0789dea5|f736debd71ac76072b294b2363788f3e96a0f037c59010855d9793ab44a49861|f736debd71ac76072b294b2363788f3e96a0f037c59010855d9793ab44a49861', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Beneath the Red Sea city of Adulis lies a late prehistoric settlement. Excavating from 1906, Richard Sundström exposed a large structure he dubbed its palace and found Axumite coins."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Adulis is a city on the Red Sea [S1]; a late prehistoric settlement lies beneath the town [S2]; Richard Sundstrom excavated at Adulis starting in 1906 [S6]; Sundstrom exposed a large structure [S7]; he dubbed the structure the palace of Adulis [S7]; he found Axumite coins [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Adulis is a city on the Red Sea (an ancient city, central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Adulis]; Adulis is in Eritrea [SUPPORTED: https://en.wikipedia.org/wiki/Adulis]; A late prehistoric settlement lies beneath Adulis [SUPPORTED: https://en.wikipedia.org/wiki/Adulis]; Excavation at Adulis began in 1906 [SUPPORTED: https://en.wikipedia.org/wiki/Adulis]; Richard Sundstrom carried out the excavation [SUPPORTED: https://en.wikipedia.org/wiki/Adulis]; Sundstrom exposed a large structure [SUPPORTED: https://en.wikipedia.org/wiki/Adulis]; Sundstrom dubbed the structure a palace (the palace of Adulis) [SUPPORTED: https://en.wikipedia.org/wiki/Adulis]; Sundstrom found Axumite coins [SUPPORTED: https://en.wikipedia.org/wiki/Adulis]"}]'::jsonb),
    ('037e3715-f5f7-4345-8216-8aa26f404009'::uuid, 'card_description', 'An island with ancient carved stone figures -- Janus-faced anthropomorphic sculptures unique in style. One figure has two faces looking in opposite directions.', 'In the Caldragh graveyard of Boa Island, on Lower Lough Erne, wait two stone figures, badly damaged when found and generally accepted to be the likenesses of pagan deities.', 'teaser-card-s027:037e3715-f5f7-4345-8216-8aa26f404009:card_description', 'teaser-card-s027 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', 'ef8a9dc992901a8fa2b8d18af5fed20d83c90866856cb078284a130f0a07fb26|a32419fc7b9f15faa3aab2c73a8711c15332fbac00d83d2eb0ceca8cf417b952|a32419fc7b9f15faa3aab2c73a8711c15332fbac00d83d2eb0ceca8cf417b952', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the Caldragh graveyard of Boa Island, on Lower Lough Erne, wait two stone figures, badly damaged when found and generally accepted to be the likenesses of pagan deities."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Caldragh graveyard is on Boa Island [S4]; Boa Island is on Lower Lough Erne [S1]; there are two stone figures in the graveyard [S4]; the figures were badly damaged when found [S5]; the figures are generally accepted to be likenesses of pagan deities [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Boa Island''s Caldragh graveyard holds stone figures (two stone statues) - central claim [SUPPORTED: https://en.wikipedia.org/wiki/Boa_Island]; The graveyard is on Boa Island [SUPPORTED: https://en.wikipedia.org/wiki/Boa_Island]; Boa Island is on Lower Lough Erne [SUPPORTED: https://en.wikipedia.org/wiki/Boa_Island]; Boa Island is in Northern Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Boa_Island]; There are two figures [SUPPORTED: https://en.wikipedia.org/wiki/Boa_Island]; The figures were badly damaged when found [SUPPORTED: https://en.wikipedia.org/wiki/Boa_Island]; The figures are generally accepted to be the likenesses of pagan deities [SUPPORTED: https://en.wikipedia.org/wiki/Boa_Island]"}]'::jsonb),
    ('0415d29e-5239-40c6-ab1d-5b19e443336b'::uuid, 'card_description', 'Odigitria is the archaeological site of an ancient Minoan religious complex, which includes two tholos tombs located near the modern Odigitria Monastery in the Asterousia mountains of southern Crete.', 'In the Asterousia mountains of southern Crete, the two Minoan tholos tombs of Odigitria were used for more than 1,000 years, and gave up seals, amulets, gold diadems and a gold bracelet.', 'teaser-card-s027:0415d29e-5239-40c6-ab1d-5b19e443336b:card_description', 'teaser-card-s027 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '03498f358189d4a2ba7801ed30a9759ca85ed1f4c45bba7f114506d0b45b507f|42a00ef487e5a1c742171c1be128678b112cf60830f7a1d14ba9635ba20a3f9a|42a00ef487e5a1c742171c1be128678b112cf60830f7a1d14ba9635ba20a3f9a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the Asterousia mountains of southern Crete, the two Minoan tholos tombs of Odigitria were used for more than 1,000 years, and gave up seals, amulets, gold diadems and a gold bracelet."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is in the Asterousia mountains [S1]; the site is in southern Crete [S1]; there are two tholos tombs at Odigitria [S1]; the tombs are Minoan [S1, S2]; the tombs were in use for more than 1,000 years [S3]; seals were found [S4]; amulets were found [S4]; gold diadems were found [S4]; a gold bracelet was found [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Odigitria is a Minoan site with two tholos tombs in the Asterousia mountains of southern Crete (central claim: tombs) [SUPPORTED: https://en.wikipedia.org/wiki/Odigitria]; The tombs are two tholos tombs [SUPPORTED: https://en.wikipedia.org/wiki/Odigitria]; The tombs are Minoan [SUPPORTED: https://en.wikipedia.org/wiki/Odigitria]; The site lies in the Asterousia mountains [SUPPORTED: https://en.wikipedia.org/wiki/Odigitria]; The site is in southern Crete [SUPPORTED: https://en.wikipedia.org/wiki/Odigitria]; The tombs were used for more than 1,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Odigitria]; The tombs gave up seals [SUPPORTED: https://en.wikipedia.org/wiki/Odigitria]; The tombs gave up amulets [SUPPORTED: https://en.wikipedia.org/wiki/Odigitria]; The tombs gave up gold diadems [SUPPORTED: https://en.wikipedia.org/wiki/Odigitria]; The tombs gave up a gold bracelet [SUPPORTED: https://en.wikipedia.org/wiki/Odigitria]"}]'::jsonb),
    ('045e2515-7952-4245-9cc3-e335f0341484'::uuid, 'card_description', 'A late Neolithic barrow cemetery on the heath, with the largest barrow reconstructed from its original excavation. Six closely packed burial mounds survive.', 'On the Lüneburg Heath rise the six Bonstorf Barrows. Under the largest, a man lay in a wooden chamber with a sword and a bronze dagger; at its northern edge, a woman lay on a stone bed.', 'teaser-card-s027:045e2515-7952-4245-9cc3-e335f0341484:card_description', 'teaser-card-s027 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '0e9a63628e5cc78a42ff840d613e49875c9821282d5c5c51337c6bbdf743e439|b2db69c511dd3aaab79a9c308b04cb0498883165180200ad976794edf9db2d89|b2db69c511dd3aaab79a9c308b04cb0498883165180200ad976794edf9db2d89', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the Lüneburg Heath rise the six Bonstorf Barrows. Under the largest, a man lay in a wooden chamber with a sword and a bronze dagger; at its northern edge, a woman lay on a stone bed."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the barrows are on the Lüneburg Heath [S1]; the site comprises six barrows [S3]; the site is called the Bonstorf Barrows [S1]; a man lay in a wooden chamber under the largest barrow''s earth mound [S4, S5]; the grave items with the man included a sword and a bronze dagger [S5, S6]; a woman lay at the northern edge of the mound [S7]; the woman lay on a stone bed [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "CENTRAL: the Bonstorf Barrows are a barrow cemetery (burial mounds) in north Germany [SUPPORTED: https://en.wikipedia.org/wiki/Bonstorf_Barrows]; The barrows lie on the Lüneburg Heath [SUPPORTED: https://en.wikipedia.org/wiki/Bonstorf_Barrows]; The site consists of six barrows (note: German Wikipedia counts five preserved mounds plus the largest one reconstructed nearby; the Lower Saxony monument register lists 6 preserved mounds plus the largest one excavated in 1973) [SUPPORTED: https://en.wikipedia.org/wiki/Bonstorf_Barrows]; One of the barrows is the largest of the site [SUPPORTED: https://en.wikipedia.org/wiki/Bonstorf_Barrows]; Under the largest barrow (the one dug out in 1973, described in the article''s paragraphs that precede this sentence) lay a wooden chamber in which a man was buried [SUPPORTED: https://en.wikipedia.org/wiki/Bonstorf_Barrows]; The man''s grave goods included a sword [SUPPORTED: https://en.wikipedia.org/wiki/Bonstorf_Barrows]; The man''s grave goods included a bronze dagger [SUPPORTED: https://en.wikipedia.org/wiki/Bonstorf_Barrows]; At the northern edge of that barrow a woman was buried [SUPPORTED: https://en.wikipedia.org/wiki/Bonstorf_Barrows]; The woman lay on a stone bed [SUPPORTED: https://en.wikipedia.org/wiki/Bonstorf_Barrows]; IMPLICATION: the largest barrow, with the man''s chamber, is itself one of the six barrows that ''rise'' on the heath. Not settled: the same article says the largest barrow ''was dug out in 1973 and reconstructed nearby'', and the Lower Saxony monument register (Denkmalatlas Niedersachsen) counts it as a further mound besides the 6 preserved ones in the wood (only a reconstruction of its stone setting stands about 60 m west), while German Wikipedia counts 5 preserved mounds plus the reconstructed one; the sources disagree on whether the largest belongs to the six [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('04d51608-e9d4-4e0b-89db-0ce9ecf6f171'::uuid, 'card_description', 'A 7th-century BC city with temples, workshops, and cemeteries. It produced fine pottery but was eventually abandoned as larger nearby cities absorbed its population.', 'About 70 km southwest of Rhodes city, the extended ruins of Ancient Kymissala lie scattered in various places: one of the most important archaeological sites in the countryside of Rhodes.', 'teaser-card-s027:04d51608-e9d4-4e0b-89db-0ce9ecf6f171:card_description', 'teaser-card-s027 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '745778d2e83e4595460352cb0d6f218df79234cca20759ac93bbc747fa433634|e43710d4280792b1ee8ee111cd48f1628c7341b06750cad442079096494128d8|e43710d4280792b1ee8ee111cd48f1628c7341b06750cad442079096494128d8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "About 70 km southwest of Rhodes city, the extended ruins of Ancient Kymissala lie scattered in various places: one of the most important archaeological sites in the countryside of Rhodes."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies about 70 km southwest of Rhodes city [S1]; the site is called Ancient Kymissala [S1]; extended ruins lie scattered in various places [S2]; it is one of the most important archaeological sites in the countryside of Rhodes [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "CENTRAL: Ancient Kymissala is an archaeological site (ancient settlement district) on Rhodes, Greece [SUPPORTED: https://www.iamm.gr/en/work/archaeological-research-at-kymissala/]; The site lies about 70 km southwest of Rhodes city (note: other sources give other road/straight distances, e.g. the Martinos Foundation page says 85 km and a JSTOR book chapter around 80 km south-southwest; Wikipedia and a Springer chapter say about 70 km) [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Kymissala]; Its extended ruins lie scattered in various places [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Kymissala]; It is one of the most important archaeological sites in the countryside of Rhodes (an evaluative statement, worded this way only by Wikipedia; no independent page states the superlative) [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Kymissala]"}]'::jsonb),
    ('0546f6ab-8ef7-44db-8577-6627e15fd6a4'::uuid, 'card_description', 'The cairn was excavated in 1901 and the remains of several humans and dogs were found, including skulls.', 'A narrow passage, partly open to the sky, leads into Cuween Hill Chambered Cairn on Orkney, a tomb of around 3000 BC where remains of several humans and dogs were found, skulls among them.', 'teaser-card-s027:0546f6ab-8ef7-44db-8577-6627e15fd6a4:card_description', 'teaser-card-s027 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '419f3d29b9de8c8ccfac19503b1f56878ab762eea158afacc95b062053d46426|082d9079931c2c2de2997562f2b758802a6c058d4018bf3f0d97268dbbc60860|082d9079931c2c2de2997562f2b758802a6c058d4018bf3f0d97268dbbc60860', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "A narrow passage, partly open to the sky, leads into Cuween Hill Chambered Cairn on Orkney, a tomb of around 3000 BC where remains of several humans and dogs were found, skulls among them."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "a narrow passage leads into the cairn [S5]; the passage is partly open to the sky [S5]; the site is Cuween Hill Chambered Cairn [S1]; the cairn is on Orkney [S1]; it is a tomb [S3, S5]; it dates to around 3000 BC [S2]; remains of several humans and dogs were found [S4]; skulls were among the remains found [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "CENTRAL: Cuween Hill Chambered Cairn is a Neolithic chambered cairn [SUPPORTED: https://en.wikipedia.org/wiki/Cuween_Hill_Chambered_Cairn]; It is on Orkney (on Mainland, the main island of Orkney), Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Cuween_Hill_Chambered_Cairn]; The cairn is a tomb (a burial place) [SUPPORTED: https://en.wikipedia.org/wiki/Cuween_Hill_Chambered_Cairn]; A narrow passage leads into the cairn [SUPPORTED: https://en.wikipedia.org/wiki/Cuween_Hill_Chambered_Cairn]; The passage is partly open to the sky [SUPPORTED: https://en.wikipedia.org/wiki/Cuween_Hill_Chambered_Cairn]; The tomb dates to around 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Cuween_Hill_Chambered_Cairn]; Remains of several humans were found in it [SUPPORTED: https://www.historicenvironment.scot/visit-a-place/places/cuween-hill-chambered-cairn/history/]; Remains of dogs were found in it [SUPPORTED: https://www.historicenvironment.scot/visit-a-place/places/cuween-hill-chambered-cairn/history/]; Skulls were among the remains found [SUPPORTED: https://en.wikipedia.org/wiki/Cuween_Hill_Chambered_Cairn]"}]'::jsonb),
    ('057ed947-18f5-45f5-b4c6-6bc1e29264d7'::uuid, 'card_description', 'About 337 meters long and 160 meters wide, this Herefordshire fort overlooks the confluence of the Wye and Lugg rivers from a spur of Dinedor Hill. Its out-turned east entrance is still visible.', NULL, 'teaser-card-s027:057ed947-18f5-45f5-b4c6-6bc1e29264d7:card_description', 'teaser-card-s027 (card-clear-failed-after-verify-rewrite): card cleared (failed-after-verify-rewrite)', '||c11691d806bfc1a97a8dc882aa7c438bb89932ffa908d7d25c672b2a9479ac35', '[{"source": "lane WB run wb-ws-2026-09-27-02: failed-after-verify-rewrite", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The web check could not prove: It overlooks the confluence of the River Wye and the River Lugg; The web check could not prove: An excavation took place there in 1951; No sentence of the description supports the claim: the rampart rings the fort (all the way round); The card says the fort is ''ringed by a single rampart'', but S5 says the rampart runs only around the rest of the fort and the south side is a steep natural slope; say ''a single rampart about 3 metres high'' without ''ringed''."}]'::jsonb),
    ('05c89db6-7e37-495d-9859-544bc6cb60e0'::uuid, 'card_description', 'Rock art at 3,100 m on the slope of Kapillayuq mountain in the Urubamba valley. A companion site, T’uqu T’uquyuq, lies 800 m away — two galleries of Andean imagery sharing the same ridgeline.', 'At about 3,100 metres, on the southern side of the mountain Kapillayuq in the Cusco Region, lies Ayawayq''u, also known as Yukay: a site of rock paintings in Urubamba Province.', 'teaser-card-s027:05c89db6-7e37-495d-9859-544bc6cb60e0:card_description', 'teaser-card-s027 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '33cd7e2927f1dbf467357b0a5353803c4166cf1674be2d0e5d1d61c5ab8ef81a|11181da192410611f4a7866e407682833424610a84294dc894414423a3ec3404|11181da192410611f4a7866e407682833424610a84294dc894414423a3ec3404', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At about 3,100 metres, on the southern side of the mountain Kapillayuq in the Cusco Region, lies Ayawayq''u, also known as Yukay: a site of rock paintings in Urubamba Province."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies at about 3,100 metres [S3]; it lies on the southern side of the mountain Kapillayuq [S3]; it is in the Cusco Region [S2]; the site is called Ayawayq''u [S1]; it is also known as Yukay [S1]; it is a site of rock paintings [S1]; it is in Urubamba Province [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "CENTRAL: Ayawayq''u is an archaeological site with rock paintings [SUPPORTED: https://en.wikipedia.org/wiki/Ayawayq%27u]; The site is in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Ayawayq%27u]; It lies in the Cusco Region [SUPPORTED: https://en.wikipedia.org/wiki/Ayawayq%27u]; It lies in Urubamba Province [SUPPORTED: https://en.wikipedia.org/wiki/Ayawayq%27u]; It lies at a height of about 3,100 metres [SUPPORTED: https://en.wikipedia.org/wiki/Ayawayq%27u]; It lies on the southern side of the mountain [SUPPORTED: https://en.wikipedia.org/wiki/Ayawayq%27u]; The mountain is called Kapillayuq [SUPPORTED: https://en.wikipedia.org/wiki/Ayawayq%27u]; The site is also known as Yukay [SUPPORTED: https://en.wikipedia.org/wiki/Ayawayq%27u]"}]'::jsonb),
    ('05ca5b20-5645-4bc5-b922-6e0605c918e4'::uuid, 'card_description', 'A Sican complex with 50 identified pyramids built between the 8th and 12th centuries AD. The site sits inside a protected forest sanctuary that still covers the ruins.', 'Within the Historic Forest Sanctuary of Pómac lies Batán Grande, a complex of 50 identified pyramids once occupied by the Sicán culture, where the Lambayeque first appear.', 'teaser-card-s027:05ca5b20-5645-4bc5-b922-6e0605c918e4:card_description', 'teaser-card-s027 (teaser-card): teaser card, 171 characters, checked PASS, web-verified VERIFIED', 'd23397e140f8571012213b7b1b352b3f79a50b249437178504ef5754176b954d|a3f48d54eea9bbb7033074e5083b1457a0f75894c271953b829e06b3660049ae|a3f48d54eea9bbb7033074e5083b1457a0f75894c271953b829e06b3660049ae', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Within the Historic Forest Sanctuary of Pómac lies Batán Grande, a complex of 50 identified pyramids once occupied by the Sicán culture, where the Lambayeque first appear."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Batan Grande lies within the Historic Forest Sanctuary of Pomac [S3]; Batan Grande is a complex [S1]; the site has 50 identified pyramids [S2]; the site was once occupied by the Sican culture [S1]; the Lambayeque first appear in the Batan Grande area [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Batán Grande is an ancient archaeological site (an archaeological complex) in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Bat%C3%A1n_Grande]; The site lies within the Historic Forest Sanctuary of Pómac [SUPPORTED: https://en.wikipedia.org/wiki/Bat%C3%A1n_Grande]; The site has 50 identified pyramids [SUPPORTED: https://en.wikipedia.org/wiki/Bat%C3%A1n_Grande]; The site was once occupied by the Sicán culture [SUPPORTED: https://en.wikipedia.org/wiki/Bat%C3%A1n_Grande]; The Lambayeque first appear at Batán Grande [SUPPORTED: https://en.wikipedia.org/wiki/Bat%C3%A1n_Grande]"}]'::jsonb),
    ('064cbe9c-02bf-48cd-840e-ca29709e57a1'::uuid, 'card_description', 'Ruins of a settlement that served Berber, Carthaginian, and Roman civilizations in sequence. It sat at the confluence of two rivers on the border of Numidia.', 'On the Ouartane Plateau lie the ruins of Althiburos, a Numidian city where two rivers met, later Carthaginian and Roman, and from the 4th to 7th centuries the seat of a bishop.', 'teaser-card-s027:064cbe9c-02bf-48cd-840e-ca29709e57a1:card_description', 'teaser-card-s027 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '02f87c4cb58fbbeb6107b686ee73197430bfe366fa031f25bbddd8e0d6ee08a7|309c21b81fada515f2412d9734b86b29071b447f1f8840cf7a54eb677a035f1a|309c21b81fada515f2412d9734b86b29071b447f1f8840cf7a54eb677a035f1a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the Ouartane Plateau lie the ruins of Althiburos, a Numidian city where two rivers met, later Carthaginian and Roman, and from the 4th to 7th centuries the seat of a bishop."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the ruins of Althiburos lie on the Ouartane Plateau [S4]; Althiburos was a Numidian city [S5]; the city lay where two rivers met [S5]; it later passed under Carthaginian (Punic) control [S1, S5]; it was also a Roman settlement, listed after the Carthaginian [S1]; it was the seat of a bishop from the 4th to 7th centuries [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Althiburos is an ancient city (settlement) in Tunisia [SUPPORTED: https://en.wikipedia.org/wiki/Althiburos]; The ruins of Althiburos lie on the Ouartane Plateau [SUPPORTED: https://en.wikipedia.org/wiki/Althiburos]; Althiburos was a Numidian city at the meeting point (confluence) of two rivers [SUPPORTED: https://en.wikipedia.org/wiki/Althiburos]; The city later passed under Carthaginian (Punic) control [SUPPORTED: https://en.wikipedia.org/wiki/Althiburos]; The city was later Roman [SUPPORTED: https://en.wikipedia.org/wiki/Althiburos]; From the 4th to 7th centuries Althiburos was the seat of a bishop [SUPPORTED: https://en.wikipedia.org/wiki/Althiburos]"}]'::jsonb),
    ('068a88b3-505e-4998-add2-6b985b255371'::uuid, 'card_description', 'A Roman theatre from 15 BC in ancient Lugdunum (Lyon), the oldest in the Roman province of Gaul. A smaller odeon was built next to it for musical performances.', 'Built around 15 BC on a hill at the heart of Roman Lyon and enlarged in the 2nd century, the Ancient Theatre of Fourvière spans 108 m, with seats for 10,000 people.', 'teaser-card-s027:068a88b3-505e-4998-add2-6b985b255371:card_description', 'teaser-card-s027 (teaser-card): teaser card, 164 characters, checked PASS, web-verified VERIFIED', '4d736cb0fc90e52bf9f5c073c455a35bdc36901c7a11706b25de659b7eb9f8af|de2acfaaf414bc1c2cf8005ef8035abfd1ef0442e1de29d608b8ecc3a27047c2|de2acfaaf414bc1c2cf8005ef8035abfd1ef0442e1de29d608b8ecc3a27047c2', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Built around 15 BC on a hill at the heart of Roman Lyon and enlarged in the 2nd century, the Ancient Theatre of Fourvière spans 108 m, with seats for 10,000 people."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the theatre was built around 15 BC [S4]; it stands on a hill [S2]; the hill lies at the heart (center) of Roman Lyon [S1, S2]; it was enlarged in the 2nd century [S5]; the theatre spans 108 m (diameter) [S6]; it had seats for 10,000 people [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Ancient Theatre of Fourvière is a Roman theatre in Lyon, France [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Theatre_of_Fourvi%C3%A8re]; It stands on a hill at the heart of Roman Lyon [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Theatre_of_Fourvi%C3%A8re]; It was built around 15 BC [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Theatre_of_Fourvi%C3%A8re]; It was enlarged in the 2nd century [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Theatre_of_Fourvi%C3%A8re]; It spans 108 m [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Theatre_of_Fourvi%C3%A8re]; It has seats for 10,000 people [SUPPORTED: https://en.wikipedia.org/wiki/Ancient_Theatre_of_Fourvi%C3%A8re]"}]'::jsonb),
    ('06a1c527-b9cc-44f8-a8a2-7d9510d1c5b0'::uuid, 'card_description', 'A sacred Aboriginal tabletop mountain with evidence of human habitation dating to 38,000 BC. The Djungan people consider it a powerful Dreaming place.', 'Cliffs fall 200 to 400 m around Ngarrabullgan, a sacred Dreaming place of the Djungan peoples. On its tabletop lie the two oldest-known Aboriginal sites in Queensland.', 'teaser-card-s027:06a1c527-b9cc-44f8-a8a2-7d9510d1c5b0:card_description', 'teaser-card-s027 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', '8edcadba01532bda9c6b0d6d1670f9145febd5fd5c01805b214a94ebc2ea8e14|78f69c653336b6282dc3514d611783caa94890f7213386060d9fb0fbfcc3a939|78f69c653336b6282dc3514d611783caa94890f7213386060d9fb0fbfcc3a939', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cliffs fall 200 to 400 m around Ngarrabullgan, a sacred Dreaming place of the Djungan peoples. On its tabletop lie the two oldest-known Aboriginal sites in Queensland."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "cliffs fall 200 to 400 m around Ngarrabullgan [S2]; Ngarrabullgan is a sacred Dreaming place of the Djungan peoples [S2]; on its tabletop lie the two oldest-known Aboriginal sites in Queensland [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Ngarrabullgan is a large tabletop mountain in Queensland, Australia [SUPPORTED: https://en.wikipedia.org/wiki/Ngarrabullgan]; Cliffs fall 200 to 400 m around the mountain [SUPPORTED: https://en.wikipedia.org/wiki/Ngarrabullgan]; It is a sacred Dreaming place of the Djungan peoples [SUPPORTED: https://en.wikipedia.org/wiki/Ngarrabullgan]; On its tabletop lie the two oldest-known Aboriginal sites in Queensland [SUPPORTED: https://en.wikipedia.org/wiki/Ngarrabullgan]"}]'::jsonb),
    ('07947420-54ee-4cf5-ac06-47814ce7f56d'::uuid, 'card_description', 'A Roman villa built in phases from the 2nd to 5th century, among the largest in Roman Britain. Its elaborate 4th-century mosaics survive in vivid detail.', NULL, 'teaser-card-s027:07947420-54ee-4cf5-ac06-47814ce7f56d:card_description', 'teaser-card-s027 (card-clear-failed-after-verify-rewrite): card cleared (failed-after-verify-rewrite)', '||e614182c03b2b04143807fc6b4bd3221add4f8916c705a6293a04347d698f6db', '[{"source": "lane WB run wb-ws-2026-09-27-02: failed-after-verify-rewrite", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The web check could not prove: Chedworth Roman Villa is a Roman villa in England (near Chedworth, Gloucestershire); No sentence of the description supports the claim: the dining-room sits beside the bathing suites (adjacent); No sentence says the dining-room sits beside the bathing suites; S4 only says the 4th-century building included both. Say ''the 4th-century building held a dining-room ... as well as two bathing suites''."}]'::jsonb),
    ('07ae3cb5-efbc-4d97-b3bf-f6d1aeca168c'::uuid, 'card_description', 'Two Iron Age enclosures plus a deserted medieval settlement, all layered on one hillside. Each era built on the bones of the last.', 'On the north-facing slope of Dunkery Hill, Sweetworthy holds two Iron Age hill forts or enclosures. One has a rampart still visible; the ditch on its east side is now a trackway.', 'teaser-card-s027:07ae3cb5-efbc-4d97-b3bf-f6d1aeca168c:card_description', 'teaser-card-s027 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '14c173d7813b6bc736a9c5bfef0623ba99aa5fa78c27158033c4f87eb0c23f32|68c36aa938258b575253a73396639b0e47aa17010bfcdd016d6f5af5f31c348e|68c36aa938258b575253a73396639b0e47aa17010bfcdd016d6f5af5f31c348e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the north-facing slope of Dunkery Hill, Sweetworthy holds two Iron Age hill forts or enclosures. One has a rampart still visible; the ditch on its east side is now a trackway."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies on the north-facing slope of Dunkery Hill [S2]; Sweetworthy holds two Iron Age hill forts or enclosures [S1]; one of them has a rampart that is still visible [S3, S4]; the ditch on its east side is now used as a trackway [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Sweetworthy is the site of two Iron Age hill forts or enclosures (central claim: a hillfort site in England) [SUPPORTED: https://en.wikipedia.org/wiki/Sweetworthy]; The two forts or enclosures lie on the north-facing slope of Dunkery Hill [SUPPORTED: https://en.wikipedia.org/wiki/Sweetworthy]; One of them has a rampart that is still visible [SUPPORTED: https://en.wikipedia.org/wiki/Sweetworthy]; The ditch on its east side is now used as a trackway [SUPPORTED: https://en.wikipedia.org/wiki/Sweetworthy]"}]'::jsonb),
    ('0865287a-1a0b-497a-aabb-de0131b3da61'::uuid, 'card_description', 'The two original structures combined to form this palatial residence were originally built during the Samnite period around the 3rd century BC.', 'Preserved by Vesuvius in or after October 79 AD, the House of Loreius Tiburtinus is renowned for its wall-paintings and gardens, laced with two water channels and fountains.', 'teaser-card-s027:0865287a-1a0b-497a-aabb-de0131b3da61:card_description', 'teaser-card-s027 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '8028a4248be4ce10b5e9c2fbe1ce2037f6a7ae3f46b925cefd73e0413307ccfa|9c5c837e81c75e9323c688ebec000dde86d387d8419b03aa0818406ba4b88124|9c5c837e81c75e9323c688ebec000dde86d387d8419b03aa0818406ba4b88124', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Preserved by Vesuvius in or after October 79 AD, the House of Loreius Tiburtinus is renowned for its wall-paintings and gardens, laced with two water channels and fountains."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the house was preserved by Vesuvius [S2]; the eruption was in or after October 79 AD [S2]; the house is renowned for its wall-paintings [S1]; the house is renowned for its gardens [S1, S6]; the gardens have two water channels [S6]; the water channels have fountains [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The House of Loreius Tiburtinus is a house (a palatial Roman residence, domus) in the Roman city of Pompeii, Italy (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/House_of_Loreius_Tiburtinus]; The house is a residence (domus), not another kind of building [SUPPORTED: https://en.wikipedia.org/wiki/House_of_Loreius_Tiburtinus]; It was preserved by the eruption of Vesuvius in or after October 79 AD [SUPPORTED: https://en.wikipedia.org/wiki/House_of_Loreius_Tiburtinus]; It is renowned for its wall-paintings [SUPPORTED: https://en.wikipedia.org/wiki/House_of_Loreius_Tiburtinus]; It is renowned for its gardens [SUPPORTED: https://en.wikipedia.org/wiki/House_of_Loreius_Tiburtinus]; The gardens contain two water channels [SUPPORTED: https://en.wikipedia.org/wiki/House_of_Loreius_Tiburtinus]; The water channels have fountains [SUPPORTED: https://en.wikipedia.org/wiki/House_of_Loreius_Tiburtinus]"}]'::jsonb),
    ('08afcd57-156b-4ab2-b53a-8e274c7a0324'::uuid, 'card_description', 'The third-largest stone circle in its country, an oval of 59 stones measuring 106 metres across. Long Meg herself stands apart, her face carved with spirals and rings.', 'On a terrace above water lie Long Meg and Her Daughters, a circle of stones deliberately flattened to make way for a ditched enclosure that seems to be older than the circle itself.', 'teaser-card-s027:08afcd57-156b-4ab2-b53a-8e274c7a0324:card_description', 'teaser-card-s027 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'eb7a5344e14df4090981ec8938446de888198af176287c736dd2873a4ba50932|5270056880467708bebc2df8f6ad493a40f49f7e3e4325f5cef4e69aa8d05e73|5270056880467708bebc2df8f6ad493a40f49f7e3e4325f5cef4e69aa8d05e73', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a terrace above water lie Long Meg and Her Daughters, a circle of stones deliberately flattened to make way for a ditched enclosure that seems to be older than the circle itself."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Long Meg and Her Daughters lie on a terrace above water [S1]; it is a circle of stones [S2]; the circle is deliberately flattened to take account of (make way for) a ditched enclosure [S1, S2]; the ditched enclosure seems to be older than the circle [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Long Meg and Her Daughters is a stone circle (central claim: a stone circle in Cumbria, England) [SUPPORTED: https://en.wikipedia.org/wiki/Long_Meg_and_Her_Daughters]; The site lies on a terrace above water [SUPPORTED: https://en.wikipedia.org/wiki/Long_Meg_and_Her_Daughters]; There is a ditched enclosure beside the circle [SUPPORTED: https://en.wikipedia.org/wiki/Long_Meg_and_Her_Daughters]; The circle is deliberately flattened (its outline was shaped) to take the ditched enclosure into account [SUPPORTED: https://en.wikipedia.org/wiki/Long_Meg_and_Her_Daughters]; The ditched enclosure seems to be older than the stone circle [SUPPORTED: https://en.wikipedia.org/wiki/Long_Meg_and_Her_Daughters]"}]'::jsonb),
    ('0be2f25c-0545-4329-b65e-fcd3c29ff85d'::uuid, 'card_description', 'Occupied since the Early Neolithic ~4000 BC, Endebjerg on Samsø has yielded pithouses, longhouse post holes, and evidence of multiple cultural phases across thousands of years.', 'On a hill beside Stavns Fjord on Samsø, Endebjerg has yielded pithouses, posts of a Late Iron Age or Viking Age longhouse, Funnelbeaker flintknapping and evidence of trade.', 'teaser-card-s027:0be2f25c-0545-4329-b65e-fcd3c29ff85d:card_description', 'teaser-card-s027 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', '4b0a1fa627119284eda77f9f7abc18b5ea9bdcb28a3bad1cb411ac4e4fa81012|efadfadd52d7e2dfb6dcad81147b5980bc84c49be455c7faaa5a93065532502d|efadfadd52d7e2dfb6dcad81147b5980bc84c49be455c7faaa5a93065532502d', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a hill beside Stavns Fjord on Samsø, Endebjerg has yielded pithouses, posts of a Late Iron Age or Viking Age longhouse, Funnelbeaker flintknapping and evidence of trade."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Endebjerg lies on a hill beside Stavns Fjord [S4]; Endebjerg is on Samso [S1]; excavations yielded pithouses [S5]; excavations yielded posts of a longhouse dated to the Late Iron Age or Viking Age [S5]; excavations yielded evidence of Funnelbeaker flintknapping [S6]; excavations yielded evidence of trade [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Endebjerg is an excavated settlement site on the island of Samsø, Denmark (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Endebjerg]; Endebjerg is on a hill beside Stavns Fjord [SUPPORTED: https://en.wikipedia.org/wiki/Endebjerg]; The excavations yielded pithouses [SUPPORTED: https://en.wikipedia.org/wiki/Endebjerg]; The excavations yielded posts of a longhouse dated to the Late Iron Age or Viking Age [SUPPORTED: https://en.wikipedia.org/wiki/Endebjerg]; The site yielded Funnelbeaker flintknapping [SUPPORTED: https://en.wikipedia.org/wiki/Endebjerg]; The site yielded evidence of trade [SUPPORTED: https://en.wikipedia.org/wiki/Endebjerg]"}]'::jsonb),
    ('0c4851de-cccd-41fc-8cb1-223a83b2e67f'::uuid, 'card_description', 'During Roman times, the Arena of Nîmes functioned as an arena where gladiators battled each other and wild animals.', 'Built around 100 AD, the Arena of Nîmes could hold 24,000 spectators watching gladiators battle each other and wild animals. Later it became a fortress, then a walled town.', 'teaser-card-s027:0c4851de-cccd-41fc-8cb1-223a83b2e67f:card_description', 'teaser-card-s027 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', '3368aaa888f87bfd8508ae647a82a0c9353b74beacc2a24d49da56f005d14c96|aa2cdae0c305128034119d8d704627ece0394770a9574eda7afea863f3eb62b5|aa2cdae0c305128034119d8d704627ece0394770a9574eda7afea863f3eb62b5', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Built around 100 AD, the Arena of Nîmes could hold 24,000 spectators watching gladiators battle each other and wild animals. Later it became a fortress, then a walled town."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the arena was built around 100 AD [S2]; it could hold 24,000 spectators [S5]; gladiators battled each other and wild animals there [S6]; spectators watched these events [S5, S6]; it later became a fortress [S7]; the fortress later became a walled town [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Arena of Nîmes is a Roman amphitheatre in Nîmes, France (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Arena_of_N%C3%AEmes]; It was built around 100 AD [SUPPORTED: https://en.wikipedia.org/wiki/Arena_of_N%C3%AEmes]; It could hold 24,000 spectators [SUPPORTED: https://en.wikipedia.org/wiki/Arena_of_N%C3%AEmes]; Gladiators battled each other and wild animals there [SUPPORTED: https://en.wikipedia.org/wiki/Arena_of_N%C3%AEmes]; Later the amphitheatre became a fortress [SUPPORTED: https://en.wikipedia.org/wiki/Arena_of_N%C3%AEmes]; After the fortress it became a walled town [SUPPORTED: https://en.wikipedia.org/wiki/Arena_of_N%C3%AEmes]"}]'::jsonb),
    ('0da526f9-499d-4d15-a0ea-a45093fc4970'::uuid, 'card_description', 'The London Wall is a defensive wall first built by the Romans around the strategically important port town of Londinium in circa AD 200, as well as the name of a modern street in the City of London.', 'Built by the Romans around AD 200 of Kentish ragstone brought by barge from near Maidstone, London Wall ringed Londinium with gateways, towers and defensive ditches.', 'teaser-card-s027:0da526f9-499d-4d15-a0ea-a45093fc4970:card_description', 'teaser-card-s027 (teaser-card): teaser card, 165 characters, checked PASS, web-verified VERIFIED', '37a5877b774dd8c80d1a73954927006025bdf2d27288e7f5b6ffd2ffbaf633ea|51118f8215678754c28089064ac982319b66cb99c5de7a95195569db38878b25|51118f8215678754c28089064ac982319b66cb99c5de7a95195569db38878b25', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Built by the Romans around AD 200 of Kentish ragstone brought by barge from near Maidstone, London Wall ringed Londinium with gateways, towers and defensive ditches."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "London Wall was built by the Romans [S1]; it was built around AD 200 [S1]; it was built of Kentish ragstone [S5]; the ragstone was brought by barge from near Maidstone [S5]; the wall ringed Londinium [S1]; it had gateways, towers and defensive ditches [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "London Wall is a defensive wall (a city wall, not a fort or tomb) in the City of London, England [SUPPORTED: https://en.wikipedia.org/wiki/London_Wall]; London Wall was built by the Romans [SUPPORTED: https://en.wikipedia.org/wiki/London_Wall]; It was built around AD 200 [SUPPORTED: https://en.wikipedia.org/wiki/London_Wall]; It ringed (enclosed) Londinium [SUPPORTED: https://en.wikipedia.org/wiki/London_Wall]; It was built of Kentish ragstone [SUPPORTED: https://en.wikipedia.org/wiki/London_Wall]; The ragstone was brought by barge [SUPPORTED: https://en.wikipedia.org/wiki/London_Wall]; The ragstone came from near Maidstone [SUPPORTED: https://en.wikipedia.org/wiki/London_Wall]; The wall had gateways [SUPPORTED: https://en.wikipedia.org/wiki/London_Wall]; The wall had towers [SUPPORTED: https://en.wikipedia.org/wiki/London_Wall]; The wall had defensive ditches [SUPPORTED: https://en.wikipedia.org/wiki/London_Wall]"}]'::jsonb),
    ('0de3da9b-5aeb-45a2-8f72-31ac1ad74a13'::uuid, 'card_description', 'A prehistoric moorland landscape dense with cairns, burial mounds, and guidestones. The gritstone upland preserves monuments spanning the entire Bronze Age.', 'Rising to 371 metres in the Derbyshire Peak District, the gritstone upland of Beeley Moor is a prehistoric landscape whose monuments include cairns, burial mounds and guidestones.', 'teaser-card-s027:0de3da9b-5aeb-45a2-8f72-31ac1ad74a13:card_description', 'teaser-card-s027 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'f5cdb8412a0a3a3089635a37abf9fe9224c6aa170d52250abb816781f3a13823|9e9ccb9738b8e9819a1503982448257e2d3b8723f3811b34857a3eef1cfc6f8f|9e9ccb9738b8e9819a1503982448257e2d3b8723f3811b34857a3eef1cfc6f8f', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Rising to 371 metres in the Derbyshire Peak District, the gritstone upland of Beeley Moor is a prehistoric landscape whose monuments include cairns, burial mounds and guidestones."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Beeley Moor rises to 371 metres [S2]; it lies in the Derbyshire Peak District [S1]; it is a gritstone upland [S1]; it is a prehistoric landscape [S3]; its monuments include cairns [S3]; its monuments include burial mounds [S3]; its monuments include guidestones [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Beeley Moor is a prehistoric landscape (an upland moor with prehistoric monuments) [SUPPORTED: https://en.wikipedia.org/wiki/Beeley_Moor]; Beeley Moor lies in the Derbyshire Peak District (England) [SUPPORTED: https://en.wikipedia.org/wiki/Beeley_Moor]; Beeley Moor is a gritstone upland [SUPPORTED: https://en.wikipedia.org/wiki/Beeley_Moor]; It rises to 371 metres [SUPPORTED: https://en.wikipedia.org/wiki/Beeley_Moor]; Its monuments include cairns [SUPPORTED: https://en.wikipedia.org/wiki/Beeley_Moor]; Its monuments include burial mounds [SUPPORTED: https://en.wikipedia.org/wiki/Beeley_Moor]; Its monuments include guidestones [SUPPORTED: https://en.wikipedia.org/wiki/Beeley_Moor]"}]'::jsonb),
    ('0e7825f5-26f0-483e-8cd0-687a9228a894'::uuid, 'card_description', 'Buried under up to 5 m of tephra in the 79 AD eruption of Vesuvius, Stabiae held luxury resort villas 4.5 km southwest of Pompeii. Excavation of the villa frescoes continues today.', 'Largely buried by tephra ash from Vesuvius in 79 AD, Stabiae is most famous for the Roman villas found near it, sited on a 50 m high headland overlooking the Gulf of Naples.', 'teaser-card-s027:0e7825f5-26f0-483e-8cd0-687a9228a894:card_description', 'teaser-card-s027 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', 'db923e4afde6065d98530b2b76e63086828a861fc84b8199c3b9300f108e234c|8f64c0f5bfc91c7ece6c0e3de1078bc7511cbf3bb1110d97c803f6b75b55064a|8f64c0f5bfc91c7ece6c0e3de1078bc7511cbf3bb1110d97c803f6b75b55064a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Largely buried by tephra ash from Vesuvius in 79 AD, Stabiae is most famous for the Roman villas found near it, sited on a 50 m high headland overlooking the Gulf of Naples."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Stabiae was largely buried by tephra ash from Vesuvius [S2]; the burial was in 79 AD [S2]; Stabiae is most famous for the Roman villas found near it [S3]; the villas were sited on a 50 m high headland [S4]; the headland overlooks the Gulf of Naples [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Stabiae was an ancient city (a Roman town near modern Castellammare di Stabia, Italy) [SUPPORTED: https://en.wikipedia.org/wiki/Stabiae]; Stabiae was largely buried [SUPPORTED: https://en.wikipedia.org/wiki/Stabiae]; It was buried by tephra ash [SUPPORTED: https://en.wikipedia.org/wiki/Stabiae]; The burial was by Vesuvius in 79 AD [SUPPORTED: https://en.wikipedia.org/wiki/Stabiae]; Stabiae is most famous for the Roman villas found near it [SUPPORTED: https://en.wikipedia.org/wiki/Stabiae]; The villas were sited on a headland 50 m high [SUPPORTED: https://en.wikipedia.org/wiki/Stabiae]; The headland overlooks the Gulf of Naples [SUPPORTED: https://en.wikipedia.org/wiki/Stabiae]"}]'::jsonb),
    ('0e942695-743b-4144-bf9f-f5687fc61447'::uuid, 'card_description', '4th-millennium BC causewayed enclosure in West Sussex, built 3700-3300 BC. Identified 1951, excavated 1982 — whether it was a settlement, meeting place, or ritual site remains unknown.', 'On a wooded ridge near East Dean, Court Hill hides a causewayed enclosure about 175 metres across, dated to the fourth millennium BC. Its ditch is still visible among the trees.', 'teaser-card-s027:0e942695-743b-4144-bf9f-f5687fc61447:card_description', 'teaser-card-s027 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '609ff277c56bddb530fa8dcb9d71d6bc06b3e2488b2783828c4cd66180f7a996|6229ad3231e4650e7460883daf60f919d6794970d99d99d04311f35947a4a208|6229ad3231e4650e7460883daf60f919d6794970d99d99d04311f35947a4a208', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a wooded ridge near East Dean, Court Hill hides a causewayed enclosure about 175 metres across, dated to the fourth millennium BC. Its ditch is still visible among the trees."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Court Hill lies on a wooded ridge [S4]; the site is near East Dean [S4]; Court Hill is a causewayed enclosure [S1]; the enclosure is about 175 metres across [S5]; it is dated to the fourth millennium BC [S3]; its ditch is still visible among the trees [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Court Hill is a causewayed enclosure (in West Sussex, England) [SUPPORTED: https://en.wikipedia.org/wiki/Court_Hill_(West_Sussex)]; It lies on a wooded ridge [SUPPORTED: https://en.wikipedia.org/wiki/Court_Hill_(West_Sussex)]; It is near East Dean [SUPPORTED: https://en.wikipedia.org/wiki/Court_Hill_(West_Sussex)]; The enclosure is about 175 metres across [SUPPORTED: https://en.wikipedia.org/wiki/Court_Hill_(West_Sussex)]; It is dated to the fourth millennium BC [SUPPORTED: https://en.wikipedia.org/wiki/Court_Hill_(West_Sussex)]; Its ditch is still visible [SUPPORTED: https://en.wikipedia.org/wiki/Court_Hill_(West_Sussex)]; The ditch is visible among the trees (within the wooded area) [SUPPORTED: https://en.wikipedia.org/wiki/Court_Hill_(West_Sussex)]"}]'::jsonb),
    ('0f2cd00e-0248-4f81-8b23-7337420927a2'::uuid, 'card_description', 'A polygonal burial chamber formed from massive stone slabs, built somewhere between the late fourth and early third millennium BC — classified a national monument since 1910.', 'Southwest of Freixo lies the Anta da Vidigueira, a dolmen probably built between the Neolithic and the Chalcolithic, where two large flint blades were found in the chamber.', 'teaser-card-s027:0f2cd00e-0248-4f81-8b23-7337420927a2:card_description', 'teaser-card-s027 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', '3ae1691506ca8a249fe7de5cdc7b7eed34b9a0d0338596c686ab59feae082d74|e0701e2e7772f8a9dd2f6ddfb645feb8c7777333aa64e0096db5720b251398b9|e0701e2e7772f8a9dd2f6ddfb645feb8c7777333aa64e0096db5720b251398b9', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Southwest of Freixo lies the Anta da Vidigueira, a dolmen probably built between the Neolithic and the Chalcolithic, where two large flint blades were found in the chamber."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Anta da Vidigueira lies southwest of Freixo [S1]; it is a dolmen [S1]; it was probably built between the Neolithic and the Chalcolithic [S2]; two large flint blades were found in the chamber [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Anta da Vidigueira is a dolmen (megalithic burial chamber) in Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Anta_da_Vidigueira]; It lies southwest of Freixo [SUPPORTED: https://en.wikipedia.org/wiki/Anta_da_Vidigueira]; It was probably built between the Neolithic and the Chalcolithic [SUPPORTED: https://en.wikipedia.org/wiki/Anta_da_Vidigueira]; Two large flint blades were found [SUPPORTED: https://en.wikipedia.org/wiki/Anta_da_Vidigueira]; The blades were found in the chamber [SUPPORTED: https://en.wikipedia.org/wiki/Anta_da_Vidigueira]"}]'::jsonb),
    ('100ab5ea-fdf9-4d78-9f65-961ee8190b7b'::uuid, 'card_description', 'In 1884, Wilhelm Dörpfeld conducted a systematic excavation of the area surrounding the Temple of Poseidon.', 'On Cape Sounion stands the Temple of Poseidon, mainly of marble, built from 444 to 440 BCE in the ascendancy of Pericles. Beneath it lie the remnants of an earlier Archaic limestone temple.', 'teaser-card-s027:100ab5ea-fdf9-4d78-9f65-961ee8190b7b:card_description', 'teaser-card-s027 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '5daa1eccd4553ae87f51aa1c49cbf82f88f620ecea6f2c2f495e50a4b3d87485|c736cd2d3f99f95bfba0747b993e294b423c7edd1bc1b899a21111994f9c325d|c736cd2d3f99f95bfba0747b993e294b423c7edd1bc1b899a21111994f9c325d', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Cape Sounion stands the Temple of Poseidon, mainly of marble, built from 444 to 440 BCE in the ascendancy of Pericles. Beneath it lie the remnants of an earlier Archaic limestone temple."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is on Cape Sounion [S1]; the site is the Temple of Poseidon [S1]; the temple seen today is mainly made of marble [S4]; it was built from 444 to 440 BCE [S2]; it was built during the ascendancy of Pericles [S3]; beneath it lie the remnants of an earlier temple [S8]; the earlier temple was Archaic [S8]; the earlier temple was of limestone [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The site is an ancient Greek temple, the Temple of Poseidon (dedicated to Poseidon) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Poseidon,_Sounion]; The temple stands on Cape Sounion (Greece) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Poseidon,_Sounion]; The temple is mainly made of marble [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Poseidon,_Sounion]; The temple was built starting in 444 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Poseidon,_Sounion]; The temple was completed in 440 BCE (built from 444 to 440 BCE) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Poseidon,_Sounion]; It was built in the ascendancy of Pericles [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Poseidon,_Sounion]; Beneath the temple lie remnants of an earlier temple [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Poseidon,_Sounion]; The earlier temple was of the Archaic period [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Poseidon,_Sounion]; The earlier temple was of limestone [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Poseidon,_Sounion]"}]'::jsonb),
    ('1010b3bf-a7d5-4e2c-9f70-8212a2cd1699'::uuid, 'card_description', 'A 7th-century Maya court whose ancient name was Sak-Nikte'', ''White Flower.'' For decades, its stunning limestone reliefs appeared on the black market before anyone knew where they came from.', 'In the 1960s looted Maya reliefs from an unknown city surfaced on the art market. They came from La Corona in Petén, the long-sought Site Q, whose old name seems to have been White-Flower.', 'teaser-card-s027:1010b3bf-a7d5-4e2c-9f70-8212a2cd1699:card_description', 'teaser-card-s027 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'b4cd393a2e9522c2dbb3847635d3ae4ccb2949e05d8236a65af0a1a800066c3d|136607d361bd27c553b6cfa61c8208e83434f2dc28d3cb1ea1544d888e7c41a2|136607d361bd27c553b6cfa61c8208e83434f2dc28d3cb1ea1544d888e7c41a2', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the 1960s looted Maya reliefs from an unknown city surfaced on the art market. They came from La Corona in Petén, the long-sought Site Q, whose old name seems to have been White-Flower."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "in the 1960s looted Maya reliefs surfaced on the art market [S3]; the city they came from was unknown at that time [S3]; the reliefs came from La Corona [S1, S3]; La Corona is in Petén [S1]; La Corona is the long-sought Site Q [S1]; the site''s old (Classical) name seems to have been White-Flower [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "La Corona is an ancient Maya site (a court residence) [SUPPORTED: https://en.wikipedia.org/wiki/La_Corona]; La Corona is in Petén (Guatemala) [SUPPORTED: https://en.wikipedia.org/wiki/La_Corona]; In the 1960s looted Maya reliefs surfaced on the art market [SUPPORTED: https://en.wikipedia.org/wiki/La_Corona]; The city the reliefs came from was unknown at the time [SUPPORTED: https://en.wikipedia.org/wiki/La_Corona]; The reliefs came from La Corona, which is Site Q [SUPPORTED: https://en.wikipedia.org/wiki/La_Corona]; Site Q was long sought [SUPPORTED: https://en.wikipedia.org/wiki/La_Corona]; The site''s old name seems to have been White-Flower [SUPPORTED: https://en.wikipedia.org/wiki/La_Corona]"}]'::jsonb),
    ('1065be39-af74-4a22-8f95-ffc846068367'::uuid, 'card_description', 'At over 7.6 m, this is the tallest standing stone in the UK. It now stands in a churchyard — Christians built around it rather than topple it.', 'In a Yorkshire churchyard stands the Rudston Monolith, over 25 feet tall, its top seemingly broken off. Digging here, Stukeley found many skulls and suggested they might be sacrificial.', 'teaser-card-s027:1065be39-af74-4a22-8f95-ffc846068367:card_description', 'teaser-card-s027 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'aeede3dd74873f2de14feb4c7e50fa1ff2b74551f3e061ac38bea59bfcaa68ee|02761d520acf8c6a2da7d5430cf49e617d3beb512a24aa10a3527ef93d23091f|02761d520acf8c6a2da7d5430cf49e617d3beb512a24aa10a3527ef93d23091f', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In a Yorkshire churchyard stands the Rudston Monolith, over 25 feet tall, its top seemingly broken off. Digging here, Stukeley found many skulls and suggested they might be sacrificial."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the monolith stands in a Yorkshire churchyard [S1]; it is over 25 feet tall [S1, S3]; its top seemingly broke off [S4]; Stukeley dug at the monolith [S7, S8]; Stukeley found many skulls [S8]; Stukeley suggested the skulls might be sacrificial [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Rudston Monolith is a monolith (standing stone) [SUPPORTED: https://en.wikipedia.org/wiki/Rudston_Monolith]; It stands in a churchyard [SUPPORTED: https://en.wikipedia.org/wiki/Rudston_Monolith]; The churchyard is in Yorkshire [SUPPORTED: https://en.wikipedia.org/wiki/Rudston_Monolith]; The monolith is over 25 feet tall [SUPPORTED: https://en.wikipedia.org/wiki/Rudston_Monolith]; Its top seems to have broken off [SUPPORTED: https://en.wikipedia.org/wiki/Rudston_Monolith]; Stukeley dug at the monolith [SUPPORTED: https://en.wikipedia.org/wiki/Rudston_Monolith]; Stukeley found many skulls [SUPPORTED: https://en.wikipedia.org/wiki/Rudston_Monolith]; Stukeley suggested the skulls might be sacrificial [SUPPORTED: https://en.wikipedia.org/wiki/Rudston_Monolith]"}]'::jsonb),
    ('1130f0c2-f133-4699-b2ea-c93999faa564'::uuid, 'card_description', 'Mountain at ~3,600 m in the Cusco highlands where two summit rocks resemble toads - one faces Ausangate, the other Huaro. The lake Quyllur Urmana at its feet marks a site of Andean sacred geography.', 'On top of Wiraqucha, about 3,600 metres up in the Andes, two rocks resembling toads gaze out, one toward Ausangate, one toward Pachatusan, a pair the local people consider a wak''a.', 'teaser-card-s027:1130f0c2-f133-4699-b2ea-c93999faa564:card_description', 'teaser-card-s027 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '3dbc9259bf6673338b7f95f782981beb15887331e743964d142fac5e70e70f50|3be2c05383a55dd29ef068c9ca30b01770eb18d1c74f751b12eab46b1430f3ab|3be2c05383a55dd29ef068c9ca30b01770eb18d1c74f751b12eab46b1430f3ab', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On top of Wiraqucha, about 3,600 metres up in the Andes, two rocks resembling toads gaze out, one toward Ausangate, one toward Pachatusan, a pair the local people consider a wak''a."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the two rocks are on top of Wiraqucha [S5]; Wiraqucha is about 3,600 metres high [S1]; Wiraqucha is in the Andes [S1]; there are two rocks that resemble toads [S5]; one rock looks toward Ausangate and the other toward Pachatusan [S5]; the local people consider the pair a wak''a [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On top of Wiraqucha there is a pair of rocks (a wak''a site on a summit in the Cusco Region, Peru) [SUPPORTED: https://en.wikipedia.org/wiki/Wiraqucha_(Cusco)]; Wiraqucha is a mountain in the Andes of Peru [SUPPORTED: https://en.wikipedia.org/wiki/Wiraqucha_(Cusco)]; Wiraqucha is about 3,600 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Wiraqucha_(Cusco)]; The two rocks resemble toads [SUPPORTED: https://en.wikipedia.org/wiki/Wiraqucha_(Cusco)]; One rock looks toward Ausangate and the other toward Pachatusan [SUPPORTED: https://en.wikipedia.org/wiki/Wiraqucha_(Cusco)]; The local people consider the pair a wak''a [SUPPORTED: https://en.wikipedia.org/wiki/Wiraqucha_(Cusco)]"}]'::jsonb),
    ('1196cd92-ce30-4a47-97f4-51f7a3694ebc'::uuid, 'card_description', 'The first written source that makes reference to the city of Sanisera is the mention which Pliny the Elder makes in his book " Naturalis Historia" in the 1st century AD.', 'At the natural port of Sanitja lies Sanisera, a city Pliny the Elder mentioned. Amphorae of the 1st to 4th centuries AD were raised from its seabed, and 44 tombs lie in rows nearby.', 'teaser-card-s027:1196cd92-ce30-4a47-97f4-51f7a3694ebc:card_description', 'teaser-card-s027 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '04a11794d0500f6c240fe0d1430691cd6f2e3489bf5d9af74d0ef3a7e8c8c11a|04c6c0a1ae00afa4527feb8d00b5ec60a86a93372f99f7cc604f9a9fdafdbab6|04c6c0a1ae00afa4527feb8d00b5ec60a86a93372f99f7cc604f9a9fdafdbab6', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At the natural port of Sanitja lies Sanisera, a city Pliny the Elder mentioned. Amphorae of the 1st to 4th centuries AD were raised from its seabed, and 44 tombs lie in rows nearby."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Sanisera lies at the natural port of Sanitja [S1]; Sanisera was a city [S2]; Pliny the Elder mentioned Sanisera [S2]; amphorae of the 1st to 4th centuries AD were recovered from the seabed [S3]; there are 44 tombs [S7]; the tombs lie in rows [S7]; the tombs are near the site (surroundings of the port) [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Sanisera is a city (an archaeological site of a Roman city) on Menorca, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Sanisera]; Sanisera lies at the port of Sanitja [SUPPORTED: https://en.wikipedia.org/wiki/Sanisera]; The port of Sanitja is a natural port [SUPPORTED: https://en.wikipedia.org/wiki/Sanisera]; Pliny the Elder mentioned the city [SUPPORTED: https://en.wikipedia.org/wiki/Sanisera]; Amphorae were raised from the seabed [SUPPORTED: https://en.wikipedia.org/wiki/Sanisera]; The amphorae date to the 1st to 4th centuries AD [SUPPORTED: https://en.wikipedia.org/wiki/Sanisera]; There are 44 tombs [SUPPORTED: https://en.wikipedia.org/wiki/Sanisera]; The tombs lie in rows [SUPPORTED: https://en.wikipedia.org/wiki/Sanisera]; The 44 tombs lie near the port (nearby) [SUPPORTED: https://en.wikipedia.org/wiki/Sanisera]"}]'::jsonb),
    ('1212f6ee-6fdc-4b75-8277-5efe8f60086c'::uuid, 'card_description', 'An Aztec site centered on Three Cultures Square. Pre-Hispanic temples, a colonial church, and modern buildings share one plaza in three eras.', 'In Tlatelolco, amid famine and disease, hundreds of children were sacrificed to the god Tlaloque in the years 1454-1457. A pyramid more than 700 years old was found within its main temple.', 'teaser-card-s027:1212f6ee-6fdc-4b75-8277-5efe8f60086c:card_description', 'teaser-card-s027 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '32a59b329fac8250bef0b33d217bbed7f9979da8f635ee66229e9b4de052205a|00407cc68960c6401b070736a69e890075d8bd6e249c2e8656acc071a11c91d9|00407cc68960c6401b070736a69e890075d8bd6e249c2e8656acc071a11c91d9', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In Tlatelolco, amid famine and disease, hundreds of children were sacrificed to the god Tlaloque in the years 1454-1457. A pyramid more than 700 years old was found within its main temple."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is Tlatelolco [S1]; a famine struck (hundreds of children were sacrificed amid it) [S6]; a serious outbreak of disease struck (hundreds of children were sacrificed amid it) [S6]; hundreds of children were sacrificed at Tlatelolco [S6]; the children were sacrificed to the god Tlaloque [S6]; the sacrifices took place in the years 1454-1457 [S6]; a pyramid was found [S3]; the pyramid is more than 700 years old [S3]; the pyramid was found within the main temple of Tlatelolco [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Central claim: Tlatelolco is an archaeological site of a pre-Columbian city-state (with a main temple) in Mexico City, Mexico [SUPPORTED: https://en.wikipedia.org/wiki/Tlatelolco_(archaeological_site)]; There was a famine in Tlatelolco when the children were sacrificed [SUPPORTED: https://en.wikipedia.org/wiki/Tlatelolco_(archaeological_site)]; There was a disease outbreak in Tlatelolco when the children were sacrificed [SUPPORTED: https://en.wikipedia.org/wiki/Tlatelolco_(archaeological_site)]; Hundreds of children were sacrificed in Tlatelolco (number: hundreds) [SUPPORTED: https://en.wikipedia.org/wiki/Tlatelolco_(archaeological_site)]; The children were sacrificed to the god Tlaloque [SUPPORTED: https://en.wikipedia.org/wiki/Tlatelolco_(archaeological_site)]; The sacrifices took place in the years 1454-1457 [SUPPORTED: https://en.wikipedia.org/wiki/Tlatelolco_(archaeological_site)]; A pyramid was found within the main temple of Tlatelolco [SUPPORTED: https://en.wikipedia.org/wiki/Tlatelolco_(archaeological_site)]; The pyramid found is more than 700 years old [SUPPORTED: https://en.wikipedia.org/wiki/Tlatelolco_(archaeological_site)]; The temple in which the older pyramid was found is the main temple of Tlatelolco [SUPPORTED: https://en.wikipedia.org/wiki/Tlatelolco_(archaeological_site)]"}]'::jsonb),
    ('1268a0fc-ad34-46f1-878c-4cb4402d9cfa'::uuid, 'card_description', 'A well-preserved 7th-century BC hillfort where excavations revealed timber defensive structures and multiple phases of building. The fort evolved over centuries, rebuilt and expanded repeatedly.', 'Moel y Gaer, an Iron Age hillfort, looks out over the Dee Estuary. On its summit stood a timber long house of the third millennium BC, perhaps the earliest human occupation of the region.', 'teaser-card-s027:1268a0fc-ad34-46f1-878c-4cb4402d9cfa:card_description', 'teaser-card-s027 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '57bba7cb92cb658d924647a36515940fd063aa428307a57431e5f8c64d6170a3|58431a6ad590d23562f115dd9db02e85730ff450ccf878f7fe0acb61d3c509bc|58431a6ad590d23562f115dd9db02e85730ff450ccf878f7fe0acb61d3c509bc', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Moel y Gaer, an Iron Age hillfort, looks out over the Dee Estuary. On its summit stood a timber long house of the third millennium BC, perhaps the earliest human occupation of the region."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Moel y Gaer is an Iron Age hillfort [S1]; it overlooks the Dee Estuary [S2]; a timber long house stood on the summit [S5]; the long house is dated to the third millennium BC [S5]; it may (perhaps) be the earliest human occupation of the region [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Central claim: Moel y Gaer is a hillfort (at Rhosesmor, Flintshire, Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Rhosesmor]; Moel y Gaer is an Iron Age site [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Rhosesmor]; The hillfort looks out over the Dee Estuary [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Rhosesmor]; A timber long house stood on the summit of the hill [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Rhosesmor]; The timber long house dates to the third millennium BC [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Rhosesmor]; The long house may represent (perhaps) the earliest human occupation of the region [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Rhosesmor]; The site is in Wales (near the village of Rhosesmor) [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Rhosesmor]"}]'::jsonb),
    ('133ef307-1b56-4af3-9411-cd66947d8cc0'::uuid, 'card_description', 'Iron Age hillfort on a sandstone outcrop in Staffordshire, 320 metres long and defended by contour-following ramparts. Known variously as Bryth, Bruff, and Burgh Hill — identity still debated.', 'On a sandstone outcrop near Maer, the earth and stone rampart of Berth Hill follows the hill''s contours. Digs were read as showing long disuse, then a hurried rebuilding of the defences.', 'teaser-card-s027:133ef307-1b56-4af3-9411-cd66947d8cc0:card_description', 'teaser-card-s027 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '308caeb3410e49bf3913ecebdd8c99dcd60953de0a8ef2c85f43f1746553ba09|470e194eb3c993d9c4d73dcad1d298e524bd589967b8d8d6c4d29bb70effa8b8|470e194eb3c993d9c4d73dcad1d298e524bd589967b8d8d6c4d29bb70effa8b8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a sandstone outcrop near Maer, the earth and stone rampart of Berth Hill follows the hill''s contours. Digs were read as showing long disuse, then a hurried rebuilding of the defences."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Berth Hill is on a sandstone outcrop [S2]; it is near Maer [S1]; its rampart is of earth and stone [S5]; the defences, including the rampart, follow the contours of the hill [S3, S5]; excavations were interpreted (hedged) as showing a long interval of disuse [S8]; excavations were interpreted as showing a later hurried reconstruction of the defences [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Central claim: Berth Hill is a hillfort (a defended hilltop site with rampart) near Maer, Staffordshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Berth_Hill]; The site lies on a sandstone outcrop [SUPPORTED: https://en.wikipedia.org/wiki/Berth_Hill]; The site is near Maer [SUPPORTED: https://en.wikipedia.org/wiki/Berth_Hill]; The rampart of Berth Hill is of earth and stone [SUPPORTED: https://en.wikipedia.org/wiki/Berth_Hill]; The defences follow the contours of the hill [SUPPORTED: https://en.wikipedia.org/wiki/Berth_Hill]; Excavations were interpreted as showing a long interval of disuse [SUPPORTED: https://en.wikipedia.org/wiki/Berth_Hill]; Excavations were interpreted as showing a later, hurried rebuilding of the defences [SUPPORTED: https://en.wikipedia.org/wiki/Berth_Hill]"}]'::jsonb),
    ('13b836d4-2d0d-4295-90e4-57fa86d9e359'::uuid, 'card_description', 'The largest known Recuay settlement, perched above 4,000 meters in the Andes. Its stone constructions mark the most important evidence of this pre-Inca culture.', 'In Peru''s Ancash Region, Yaynu is the largest known Recuay site, best described as a fortified hilltop town; its central sector is bounded by perimeter walls and long trenches.', 'teaser-card-s027:13b836d4-2d0d-4295-90e4-57fa86d9e359:card_description', 'teaser-card-s027 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '6b131e0d87da65cfa1b39ffce10f4a988a5d400335ddd83f0e6921fabf47571d|ab21752b9559b4786291ce3c68bfa620369969cfc638038e182649508b882ce5|ab21752b9559b4786291ce3c68bfa620369969cfc638038e182649508b882ce5', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In Peru''s Ancash Region, Yaynu is the largest known Recuay site, best described as a fortified hilltop town; its central sector is bounded by perimeter walls and long trenches."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Yaynu is in Peru''s Ancash Region [S1, S2]; it is the largest known Recuay site [S5]; it is best described as a fortified hilltop town [S5]; its central sector is bounded by perimeter walls [S6]; its central sector is bounded by long trenches [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Yaynu is a fortified hilltop town (a settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Yaynu]; Yaynu is in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Yaynu]; Yaynu lies in the Ancash Region [SUPPORTED: https://en.wikipedia.org/wiki/Yaynu]; Yaynu is the largest known Recuay site [SUPPORTED: https://en.wikipedia.org/wiki/Yaynu]; Yaynu''s central sector is bounded by perimeter walls [SUPPORTED: https://en.wikipedia.org/wiki/Yaynu]; Yaynu''s central sector is bounded by long trenches [SUPPORTED: https://en.wikipedia.org/wiki/Yaynu]"}]'::jsonb),
    ('16edc297-75f0-471e-a82a-fc3dc46d6c8f'::uuid, 'card_description', 'Fort built in 79 AD, abandoned in the 90s, then replaced by a smaller fortlet around 105 AD. A civilian settlement grew alongside the second fortlet on the eastern side of Castleshaw Valley.', 'On Castle Hill above the Castleshaw Valley stood Castleshaw Roman Fort, built circa AD 79. A civilian settlement grew here, yet it lay undiscovered until the 1990s.', 'teaser-card-s027:16edc297-75f0-471e-a82a-fc3dc46d6c8f:card_description', 'teaser-card-s027 (teaser-card): teaser card, 164 characters, checked PASS, web-verified VERIFIED', '915b62a554fc3d87516cbd6672fa83e0e424800a84b80430ee3ec57ca43352cc|bda54d8851efec08fd3025b3f8955e9372e9a5daacb9abc013928d9f5048acf9|bda54d8851efec08fd3025b3f8955e9372e9a5daacb9abc013928d9f5048acf9', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Castle Hill above the Castleshaw Valley stood Castleshaw Roman Fort, built circa AD 79. A civilian settlement grew here, yet it lay undiscovered until the 1990s."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the fort is on Castle Hill [S2]; it is above the Castleshaw Valley [S2]; it was a Roman fort that is no longer standing [S1, S2]; it was built circa AD 79 [S3]; a civilian settlement grew at the site [S4]; the civilian settlement lay undiscovered until the 1990s [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Central claim: Castleshaw Roman Fort was a Roman fort (castellum) in England, at Castleshaw in Greater Manchester [SUPPORTED: https://en.wikipedia.org/wiki/Castleshaw_Roman_Fort]; The fort stood on Castle Hill above the Castleshaw Valley [SUPPORTED: https://en.wikipedia.org/wiki/Castleshaw_Roman_Fort]; The fort was built circa AD 79 [SUPPORTED: https://en.wikipedia.org/wiki/Castleshaw_Roman_Fort]; A civilian settlement grew at the site [SUPPORTED: https://en.wikipedia.org/wiki/Castleshaw_Roman_Fort]; The civilian settlement lay undiscovered until the 1990s [SUPPORTED: https://en.wikipedia.org/wiki/Castleshaw_Roman_Fort]; The site is in England (Castleshaw, Greater Manchester) [SUPPORTED: https://en.wikipedia.org/wiki/Castleshaw_Roman_Fort]"}]'::jsonb),
    ('16f08708-e9ab-4a7e-94b0-2620239d3e34'::uuid, 'card_description', 'The Arrephorion or House of the Arrephoroi is a building conjectured to have been on the Acropolis of Athens based on a passage in Pausanias.', 'On the north-west edge of the Acropolis rest the limestone foundations of a building 12.2 m square, identified as the Arrephorion, though the evidence is still circumstantial.', 'teaser-card-s027:16f08708-e9ab-4a7e-94b0-2620239d3e34:card_description', 'teaser-card-s027 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '224c6dd5c930d64afbe2d9b0f63c6a8ac3ff3b09ee4cdd62e7d0438dce6f2e60|9a90d741a0494ffff5d179c8c98b43598bc7e2f6d2e6873fa43f685ce2ce6cdc|9a90d741a0494ffff5d179c8c98b43598bc7e2f6d2e6873fa43f685ce2ce6cdc', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the north-west edge of the Acropolis rest the limestone foundations of a building 12.2 m square, identified as the Arrephorion, though the evidence is still circumstantial."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the remains are on the north-west edge of the Acropolis [S2]; the remains are limestone foundations [S5]; the building is 12.2 m square [S5]; the building is identified as the Arrephorion [S2]; the evidence for this identification is still circumstantial [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Arrephorion is a building on the Acropolis of Athens (Greece): the House of the Arrephoroi, a building known from a passage in Pausanias (what kind of place the site is, and where) [SUPPORTED: https://en.wikipedia.org/wiki/Arrephorion]; The foundations of a building lie on the north-west edge of the Acropolis and have been identified with the Arrephorion [SUPPORTED: https://en.wikipedia.org/wiki/Arrephorion]; The foundations are of limestone [SUPPORTED: https://en.wikipedia.org/wiki/Arrephorion]; The building is 12.2 m square [SUPPORTED: https://en.wikipedia.org/wiki/Arrephorion]; The identification as the Arrephorion is still based on circumstantial evidence [SUPPORTED: https://en.wikipedia.org/wiki/Arrephorion]"}]'::jsonb),
    ('1886172a-83a7-4dfb-b5e5-4c3978571e48'::uuid, 'card_description', 'Founded in 25 BC as a colony for retired legionaries, it quickly became capital of Lusitania. Its theatre, amphitheatre, circus, and bridge survive remarkably intact.', 'Founded in 25 BC for veterans of the Cantabrian Wars, Augusta Emerita had three aqueducts, two fora and a circus that could seat about 30,000, more or less the city''s entire population.', 'teaser-card-s027:1886172a-83a7-4dfb-b5e5-4c3978571e48:card_description', 'teaser-card-s027 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'c7a14c30ff5ed2bf3c7961398c46eed75bd09658c8908af1bdb7fcb7573d3b78|39fb76e2bf517bcde4e1db5caf542c68b2918236055d140bfc9f75216fe22788|39fb76e2bf517bcde4e1db5caf542c68b2918236055d140bfc9f75216fe22788', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Founded in 25 BC for veterans of the Cantabrian Wars, Augusta Emerita had three aqueducts, two fora and a circus that could seat about 30,000, more or less the city''s entire population."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Augusta Emerita was founded in 25 BC [S1]; it was founded for veterans of the Cantabrian Wars [S2]; it had three aqueducts [S4]; it had two fora [S4]; it had a circus [S7, S8]; the circus could seat about 30,000 [S8]; 30,000 was more or less the city''s entire population [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Augusta Emerita was a Roman colonia (city) in present-day Merida, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Augusta_Emerita]; It was founded in 25 BC [SUPPORTED: https://en.wikipedia.org/wiki/Augusta_Emerita]; It was founded for veterans of the Cantabrian Wars [SUPPORTED: https://en.wikipedia.org/wiki/Augusta_Emerita]; The city had three aqueducts [SUPPORTED: https://en.wikipedia.org/wiki/Augusta_Emerita]; The city had two fora [SUPPORTED: https://en.wikipedia.org/wiki/Augusta_Emerita]; It had a circus that could seat about 30,000 spectators [SUPPORTED: https://en.wikipedia.org/wiki/Augusta_Emerita]; That seating capacity was more or less the city''s entire population [SUPPORTED: https://en.wikipedia.org/wiki/Augusta_Emerita]"}]'::jsonb),
    ('18f993a6-2922-432f-b795-4ef914cffcd4'::uuid, 'card_description', 'A Maya city founded in 629 AD by Tikal''s dynasty to control trade routes. By 648 AD it betrayed Tikal and allied with the rival superpower Calakmul.', 'Founded in AD 629 by an offshoot of Tikal''s dynasty, Dos Pilas was a predator state from the start. In 761, after Tamarindito and other centres rebelled, the city was dramatically abandoned.', 'teaser-card-s027:18f993a6-2922-432f-b795-4ef914cffcd4:card_description', 'teaser-card-s027 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', 'e4f52d83ba37f73193b3060eedb4b3a27ed06c43a1644a9f75a574b58e263a02|9e51245a266ef257d9c195a7e02c25e7a0cee7aaa598437c1e292c737fe58bd1|9e51245a266ef257d9c195a7e02c25e7a0cee7aaa598437c1e292c737fe58bd1', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Founded in AD 629 by an offshoot of Tikal''s dynasty, Dos Pilas was a predator state from the start. In 761, after Tamarindito and other centres rebelled, the city was dramatically abandoned."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Dos Pilas was founded in AD 629 [S2]; it was founded by an offshoot of Tikal''s dynasty [S2]; it was a predator state from the start [S4]; in 761 the city was abandoned [S5]; the abandonment came after Tamarindito and other centres rebelled [S5]; the abandonment was dramatic [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Dos Pilas is a Pre-Columbian Maya site (a city) in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Dos_Pilas]; Dos Pilas was founded in AD 629 [SUPPORTED: https://en.wikipedia.org/wiki/Dos_Pilas]; It was founded by an offshoot of Tikal''s dynasty [SUPPORTED: https://en.wikipedia.org/wiki/Dos_Pilas]; Dos Pilas was a predator state from the start [SUPPORTED: https://en.wikipedia.org/wiki/Dos_Pilas]; In 761 the city was dramatically abandoned [SUPPORTED: https://en.wikipedia.org/wiki/Dos_Pilas]; Tamarindito and other centres rebelled against Dos Pilas before the abandonment [SUPPORTED: https://en.wikipedia.org/wiki/Dos_Pilas]"}]'::jsonb),
    ('190821d5-ac73-40cb-86cf-76a59a6cce72'::uuid, 'card_description', 'A portal tomb from 4200-2900 BC with three standing stones supporting a heavy capstone. It is the best known of the approximately 172 dolmens scattered across the island.', 'The Poulnabrone Dolmen has a trapezoidal capstone 3.9 m long, on a low mound. The spot would have been hard to reach when built, and was probably a center for ritual into the Bronze Age.', 'teaser-card-s027:190821d5-ac73-40cb-86cf-76a59a6cce72:card_description', 'teaser-card-s027 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'db830233184fd78eb7751f7a4f1501b204c90752394165d4ded97e58ec63df65|3cc95e16cfddfcc329ef371292be314dcab9a82a5f6e63c702a0827a32d6a01f|3cc95e16cfddfcc329ef371292be314dcab9a82a5f6e63c702a0827a32d6a01f', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Poulnabrone Dolmen has a trapezoidal capstone 3.9 m long, on a low mound. The spot would have been hard to reach when built, and was probably a center for ritual into the Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the dolmen has a capstone [S3]; the capstone is trapezoidal [S3]; the capstone is 3.9 m long [S3]; the dolmen stands on a low mound [S1]; the spot would have been hard to reach when the dolmen was built [S2]; the spot was probably a center for ritual [S2]; the ritual use continued into the Bronze Age [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Poulnabrone Dolmen is a dolmen (single-chamber portal tomb) in the Burren, County Clare, Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Poulnabrone_dolmen]; Its capstone is trapezoidal [SUPPORTED: https://en.wikipedia.org/wiki/Poulnabrone_dolmen]; The capstone is 3.9 m long [SUPPORTED: https://en.wikipedia.org/wiki/Poulnabrone_dolmen]; The dolmen stands on a low mound [SUPPORTED: https://en.wikipedia.org/wiki/Poulnabrone_dolmen]; The spot would have been hard to reach when the dolmen was built [SUPPORTED: https://en.wikipedia.org/wiki/Poulnabrone_dolmen]; The site was probably a center for ritual [SUPPORTED: https://en.wikipedia.org/wiki/Poulnabrone_dolmen]; The ritual use probably continued into the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Poulnabrone_dolmen]"}]'::jsonb),
    ('190fd91a-8c04-4665-9121-b89eff26130f'::uuid, 'card_description', 'A Neolithic dolmen with three uprights supporting a robust wedge-shaped capstone. A large flat stone nearby may be the collapsed remains of the original structure.', 'In a farmer''s field on Anglesey, three upright stones of Bodowyr Burial Chamber hold up a robust, wedge-shaped capstone. In 1833 four were said to hold it: one seems to have fallen since.', 'teaser-card-s027:190fd91a-8c04-4665-9121-b89eff26130f:card_description', 'teaser-card-s027 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'e21caf531be43a2b8fec37f0751ccb5973f667cfc70ef4d5a611ae853d4b1bf3|a681d648ccb56a845619f0adc3b3aad145c59a20d0824e5b6578a3e1afe436c6|a681d648ccb56a845619f0adc3b3aad145c59a20d0824e5b6578a3e1afe436c6', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In a farmer''s field on Anglesey, three upright stones of Bodowyr Burial Chamber hold up a robust, wedge-shaped capstone. In 1833 four were said to hold it: one seems to have fallen since."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the chamber is in a farmer''s field on Anglesey [S1]; three upright stones hold up the capstone [S7]; the capstone is robust and wedge-shaped [S7]; in 1833 the capstone was said to be supported by four upright stones [S5]; one of the four seems to have fallen since then [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Bodowyr Burial Chamber is a Neolithic burial chamber (dolmen / passage grave) on the island of Anglesey, north Wales [SUPPORTED: https://en.wikipedia.org/wiki/Bodowyr_Burial_Chamber]; It stands in a farmer''s field on Anglesey [SUPPORTED: https://en.wikipedia.org/wiki/Bodowyr_Burial_Chamber]; Three upright stones hold up a robust, wedge-shaped capstone [SUPPORTED: https://en.wikipedia.org/wiki/Bodowyr_Burial_Chamber]; In 1833 four upright stones were said to hold up the capstone [SUPPORTED: https://en.wikipedia.org/wiki/Bodowyr_Burial_Chamber]; One of the four upright stones seems to have fallen since 1833 [SUPPORTED: https://en.wikipedia.org/wiki/Bodowyr_Burial_Chamber]"}]'::jsonb),
    ('191e7642-eef6-476a-bdf1-4672f400a083'::uuid, 'card_description', 'The Mahakali Caves are a group of 19 rock-cut monuments built between 4th century BCE and 6th century CE.', 'Carved from solid black basalt in Andheri, Mumbai, the Mahakali Caves are a Buddhist monastery of 19 rock-cut monuments, with a chaitya in Cave 9 and rock-cut cisterns.', 'teaser-card-s027:191e7642-eef6-476a-bdf1-4672f400a083:card_description', 'teaser-card-s027 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '7c6754c0663435751849deac6415131c80b0fac30c6a064c0336f79481f2fb12|849cf2cb9cd8dc7e60eaaf06a37d681d78f6bd7f4d5db1b656d4107a91e5642e|849cf2cb9cd8dc7e60eaaf06a37d681d78f6bd7f4d5db1b656d4107a91e5642e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Carved from solid black basalt in Andheri, Mumbai, the Mahakali Caves are a Buddhist monastery of 19 rock-cut monuments, with a chaitya in Cave 9 and rock-cut cisterns."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the caves are carved from solid black basalt [S7]; the site is in Andheri [S2]; Andheri is in Mumbai [S2]; the Mahakali Caves are a Buddhist monastery [S2]; the site consists of 19 rock-cut monuments [S1]; there is a chaitya in Cave 9 [S4]; the site has rock-cut cisterns [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Mahakali Caves are a Buddhist monastery (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Mahakali_Caves]; The monastery is in Andheri [SUPPORTED: https://en.wikipedia.org/wiki/Mahakali_Caves]; Andheri is in Mumbai [SUPPORTED: https://en.wikipedia.org/wiki/Mahakali_Caves]; The caves are carved (rock-cut) from basalt rock [SUPPORTED: https://en.wikipedia.org/wiki/Mahakali_Caves]; The basalt is solid [SUPPORTED: https://en.wikipedia.org/wiki/Mahakali_Caves]; The basalt is black [SUPPORTED: https://en.wikipedia.org/wiki/Mahakali_Caves]; The monastery comprises 19 monuments [SUPPORTED: https://en.wikipedia.org/wiki/Mahakali_Caves]; The 19 monuments are rock-cut [SUPPORTED: https://en.wikipedia.org/wiki/Mahakali_Caves]; The site has a chaitya [SUPPORTED: https://en.wikipedia.org/wiki/Mahakali_Caves]; The chaitya is in Cave 9 [SUPPORTED: https://en.wikipedia.org/wiki/Mahakali_Caves]; The site has rock-cut cisterns [SUPPORTED: https://en.wikipedia.org/wiki/Mahakali_Caves]"}]'::jsonb),
    ('1949a2b8-9e93-4091-b404-915fb9bd8f52'::uuid, 'card_description', 'Well-preserved broch at Shapinsay with drystone walls up to 4 metres thick. A complete chamber survives off the entrance passage, and stone fittings remain visible inside.', 'Above the North Sea on Shapinsay, the Iron Age Burroughston Broch keeps drystone walls up to four metres thick, an intact chamber off its entrance and a deep well in its floor.', 'teaser-card-s027:1949a2b8-9e93-4091-b404-915fb9bd8f52:card_description', 'teaser-card-s027 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'b1ae90a6c30e461519865105de9e8a2cf98b5d02375f5b8c43a9fa7e50224dd7|2b3ca2fff2af5b93162d068ceace4bd7cb8ab25b24ace37e07ea0557946904e8|2b3ca2fff2af5b93162d068ceace4bd7cb8ab25b24ace37e07ea0557946904e8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Above the North Sea on Shapinsay, the Iron Age Burroughston Broch keeps drystone walls up to four metres thick, an intact chamber off its entrance and a deep well in its floor."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the broch overlooks the North Sea [S2]; it is on Shapinsay [S1, S2]; it is an Iron Age broch [S1]; its drystone walls are up to four metres thick [S4]; a complete chamber is intact off the entrance passage [S4]; a deep well is in the broch floor [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Burroughston Broch is a broch on Shapinsay (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Burroughston_Broch]; The broch dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Burroughston_Broch]; It is on the island of Shapinsay [SUPPORTED: https://en.wikipedia.org/wiki/Burroughston_Broch]; It stands above / overlooks the North Sea [SUPPORTED: https://en.wikipedia.org/wiki/Burroughston_Broch]; Its walls are of drystone [SUPPORTED: https://en.wikipedia.org/wiki/Burroughston_Broch]; Its walls are up to four metres thick [SUPPORTED: https://en.wikipedia.org/wiki/Burroughston_Broch]; A chamber off the entrance survives intact [SUPPORTED: https://en.wikipedia.org/wiki/Burroughston_Broch]; A deep well is in the broch floor [SUPPORTED: https://en.wikipedia.org/wiki/Burroughston_Broch]"}]'::jsonb),
    ('19bf50b2-2ed2-4f63-a9b5-c5932439c190'::uuid, 'card_description', 'A 1st-century AD Roman bridge on Via XIX, linking Lucus Augusti to Bracara Augusta. Eight stone arches span 104 m over the Minho — carried traffic for nearly 2,000 years, pedestrian-only since 2012.', 'Built mainly of stone and slate and rebuilt many times, the Roman Bridge of Lugo still crosses the Minho on the route linking Lucus Augusti with Bracara Augusta, a work of Roman Galicia.', 'teaser-card-s027:19bf50b2-2ed2-4f63-a9b5-c5932439c190:card_description', 'teaser-card-s027 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'e7710223e71bd8ba8b733fe45e29edb03a1e4282fa1e42ba1ab41e9db86d42fa|c1aa271a920a57b1334413bc6d8d1a6e1eca424c7f1d9bed6186f9476d2a6604|c1aa271a920a57b1334413bc6d8d1a6e1eca424c7f1d9bed6186f9476d2a6604', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Built mainly of stone and slate and rebuilt many times, the Roman Bridge of Lugo still crosses the Minho on the route linking Lucus Augusti with Bracara Augusta, a work of Roman Galicia."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the bridge is built mainly of stone and slate [S3]; the bridge has been rebuilt many times [S2]; the bridge crosses the Minho [S1]; it is on the route linking Lucus Augusti with Bracara Augusta [S5]; it is a work of Roman Galicia (built during the Romanization of Galicia, of Roman origin) [S2, S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Roman Bridge of Lugo is a bridge over the Minho (Miño) in Lugo, of Roman origin (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_bridge_of_Lugo]; The bridge still crosses the Minho (the river Miño) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_bridge_of_Lugo]; It is built mainly of stone and slate [SUPPORTED: https://en.wikipedia.org/wiki/Roman_bridge_of_Lugo]; It has been rebuilt many times [SUPPORTED: https://en.wikipedia.org/wiki/Roman_bridge_of_Lugo]; It lies on the route linking Lucus Augusti with Bracara Augusta [SUPPORTED: https://en.wikipedia.org/wiki/Roman_bridge_of_Lugo]; That route is a Roman road (route XIX of the Antonine Itinerary) which the bridge utilized [SUPPORTED: https://en.wikipedia.org/wiki/Roman_bridge_of_Lugo]; The bridge is a work of Roman Galicia [SUPPORTED: https://en.wikipedia.org/wiki/Roman_bridge_of_Lugo]"}]'::jsonb),
    ('1a01ebc7-570b-4f83-8b09-86ab7a57390f'::uuid, 'card_description', 'Capital of the Celto-Ligurian Salyes confederation, settled around 175 BC. Stone pillars with niches for displaying severed enemy heads were found in the sanctuary.', 'Entremont, capital of the Celtic-Ligurian Salyes, fell to the Romans in 123 B.C. Among its sculpture fragments sit men with legs folded, one hand resting on an enemy''s severed head.', 'teaser-card-s027:1a01ebc7-570b-4f83-8b09-86ab7a57390f:card_description', 'teaser-card-s027 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '3e0387c146e75f5c5a2ed67bf3110c3085797f008c5d8a6f9dcf7508259ebd35|144402639ed5fe1fe1997dc336856b0f4bb4cab2efc70f87d556e843759de9ae|144402639ed5fe1fe1997dc336856b0f4bb4cab2efc70f87d556e843759de9ae', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Entremont, capital of the Celtic-Ligurian Salyes, fell to the Romans in 123 B.C. Among its sculpture fragments sit men with legs folded, one hand resting on an enemy''s severed head."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Entremont was the capital of the Celtic-Ligurian Salyes [S2]; it fell to the Romans in 123 B.C. [S4]; its finds include sculpture fragments [S6]; the fragments include male figures depicted seated with legs folded [S7]; one hand of each figure rests on the severed head of an enemy [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Entremont is an oppidum (fortified Celtic-Ligurian settlement) near Aix-en-Provence (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Entremont_(oppidum)]; Entremont was the capital of the Salyes [SUPPORTED: https://en.wikipedia.org/wiki/Entremont_(oppidum)]; The Salyes were Celtic-Ligurian [SUPPORTED: https://en.wikipedia.org/wiki/Entremont_(oppidum)]; Entremont fell to the Romans in 123 B.C. [SUPPORTED: https://en.wikipedia.org/wiki/Entremont_(oppidum)]; Excavation produced fragments of sculpture at Entremont [SUPPORTED: https://en.wikipedia.org/wiki/Entremont_(oppidum)]; Among the fragments are male figures seated with their legs folded [SUPPORTED: https://en.wikipedia.org/wiki/Entremont_(oppidum)]; One hand of the figures rests on the severed head of an enemy [SUPPORTED: https://en.wikipedia.org/wiki/Entremont_(oppidum)]"}]'::jsonb),
    ('1aabb9f3-327b-48d5-9fee-045f7ebd4f1f'::uuid, 'card_description', 'Numantia is an ancient Celtiberian settlement, whose remains are located on a hill known as Cerro de la Muela in the current municipality of Garray.', 'In 137 BC, 20,000 Romans surrendered to the Celtiberians of Numantia, a hill fort guarding a crossing of the Duero. Later its exact location vanished from memory, until 1860.', 'teaser-card-s027:1aabb9f3-327b-48d5-9fee-045f7ebd4f1f:card_description', 'teaser-card-s027 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '890c2821d9675977fde9b9347372b1000917a42d744992cabe9e5f5e7cdbf2cb|b38ce4e5f8506a9f290015d405f9369bfe2db80466db786e30917a4807b9831c|b38ce4e5f8506a9f290015d405f9369bfe2db80466db786e30917a4807b9831c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In 137 BC, 20,000 Romans surrendered to the Celtiberians of Numantia, a hill fort guarding a crossing of the Duero. Later its exact location vanished from memory, until 1860."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "in 137 BC 20,000 Romans surrendered to the Celtiberians of Numantia [S5]; Numantia was a hill fort [S4]; the hill fort controlled (guarded) a crossing of the Duero [S4]; its exact location later vanished from memory [S6]; the location was lost until 1860 (when it was identified) [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Numantia is a hill fort (oppidum) (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Numantia]; The hill fort guarded (controlled) a crossing of the Duero [SUPPORTED: https://en.wikipedia.org/wiki/Numantia]; Numantia was inhabited by Celtiberians [SUPPORTED: https://en.wikipedia.org/wiki/Numantia]; In 137 BC Romans surrendered to the Celtiberians of Numantia [SUPPORTED: https://en.wikipedia.org/wiki/Numantia]; The number of surrendering Romans was 20,000 [SUPPORTED: https://en.wikipedia.org/wiki/Numantia]; The exact location of Numantia later vanished from memory [SUPPORTED: https://en.wikipedia.org/wiki/Numantia]; The location was lost until 1860, when it was identified [SUPPORTED: https://en.wikipedia.org/wiki/Numantia]"}]'::jsonb),
    ('1abe781b-81a3-4aff-af66-3a4359970d72'::uuid, 'card_description', 'Carved from tuff rock in the 2nd century AD, these catacombs span two underground levels. Wide corridors and vaulted ceilings make them feel more like a basilica than a tomb.', 'Carved out of porous tuff on the slope up to Capodimonte, the Catacombs of San Gennaro spread spacious passageways over two levels, where approximately 200 oil lamps have been found.', 'teaser-card-s027:1abe781b-81a3-4aff-af66-3a4359970d72:card_description', 'teaser-card-s027 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'b65f75bbf80a0e5c61d30423aa0661a8ef317b054c6d9b3cd40ded64e07a3ea1|495df223442f163670bbf63297596e00269d9f6e5494e72b8989fbb96f3575a7|495df223442f163670bbf63297596e00269d9f6e5494e72b8989fbb96f3575a7', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Carved out of porous tuff on the slope up to Capodimonte, the Catacombs of San Gennaro spread spacious passageways over two levels, where approximately 200 oil lamps have been found."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the catacombs are carved out of porous tuff [S1]; they lie on the slope up to Capodimonte [S2]; they have spacious passageways [S4]; the passageways run over two levels [S2, S4]; approximately 200 oil lamps have been found in the catacombs [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Catacombs of San Gennaro are an underground burial site (catacombs) in Naples, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_San_Gennaro]; The catacombs are carved out of porous tuff [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_San_Gennaro]; The catacombs lie on the slope up to Capodimonte [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Catacombs_of_San_Gennaro]; The catacombs have spacious passageways over two levels [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_San_Gennaro]; Approximately 200 oil lamps have been found in the catacombs [SUPPORTED: https://en.wikipedia.org/wiki/Catacombs_of_San_Gennaro]"}]'::jsonb),
    ('1b7b98d0-7d4e-4756-946b-f951a84f7016'::uuid, 'card_description', 'A vast karst cave inhabited for tens of thousands of years, now home to 30,000 bats. Paleolithic to Neolithic layers track human occupation across millennia.', 'By the river Osam, the karst mouth of Devetashka Cave opens 35 m wide and 30 m high. Paleo-humans occupied it for tens of thousands of years; today nearly 30,000 bats call it home.', 'teaser-card-s027:1b7b98d0-7d4e-4756-946b-f951a84f7016:card_description', 'teaser-card-s027 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '55e74fa0614550108ebe8b4c54e24748eb0666d7834b62f14602ef0cba8fba2d|3148e02fa4d9609745266967ab53283b2ad4ae3b10647e3e6ffbca087bcef95f|3148e02fa4d9609745266967ab53283b2ad4ae3b10647e3e6ffbca087bcef95f', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "By the river Osam, the karst mouth of Devetashka Cave opens 35 m wide and 30 m high. Paleo-humans occupied it for tens of thousands of years; today nearly 30,000 bats call it home."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the cave is by the river Osam [S1]; it is a karst cave [S1]; the entrance is 35 m wide [S4]; the entrance is 30 m high [S4]; paleo-humans occupied it for tens of thousands of years [S2]; today nearly 30,000 bats live in it [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Devetashka Cave is a large karst cave in Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Devetashka_cave]; The cave lies by the river Osam [SUPPORTED: https://en.wikipedia.org/wiki/Devetashka_cave]; The cave mouth is 35 m wide [SUPPORTED: https://en.wikipedia.org/wiki/Devetashka_cave]; The cave mouth is 30 m high [SUPPORTED: https://en.wikipedia.org/wiki/Devetashka_cave]; Paleo-humans occupied the cave [SUPPORTED: https://en.wikipedia.org/wiki/Devetashka_cave]; The occupation lasted tens of thousands of years [SUPPORTED: https://en.wikipedia.org/wiki/Devetashka_cave]; Nearly 30,000 bats live in the cave today [SUPPORTED: https://en.wikipedia.org/wiki/Devetashka_cave]"}]'::jsonb),
    ('1ce06cbc-5f4e-4114-82f8-3bae6bc40a16'::uuid, 'card_description', '3rd–4th century AD Roman villa found only in 2013 when a bypass survey was run. No prior evidence hinted at its existence — the county archaeologist called it a shock and a surprise.', 'Found by geophysical survey near Dere Street, Aiskew Roman Villa dates to the 3rd and 4th centuries AD. Among its finds lie a silver stylus and a stamped amphora rim from north Africa.', 'teaser-card-s027:1ce06cbc-5f4e-4114-82f8-3bae6bc40a16:card_description', 'teaser-card-s027 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '1c980dc0416a29aa7f831627a7ed5bfd165cff89edff5d736419daeee0ddc79c|8aa9da320c2e8557ed9c8b6c2090fd91484655ce9eee2c98a746babc451af397|8aa9da320c2e8557ed9c8b6c2090fd91484655ce9eee2c98a746babc451af397', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Found by geophysical survey near Dere Street, Aiskew Roman Villa dates to the 3rd and 4th centuries AD. Among its finds lie a silver stylus and a stamped amphora rim from north Africa."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the villa was found (identified) by geophysical survey [S2]; it is near Dere Street [S3]; it dates to the 3rd and 4th centuries AD [S5]; its finds include a silver stylus [S8]; its finds include a stamped amphora rim from north Africa [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Aiskew Roman Villa is a Roman villa in Aiskew, North Yorkshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Aiskew_Roman_villa]; The villa was found by geophysical survey [SUPPORTED: https://en.wikipedia.org/wiki/Aiskew_Roman_villa]; The villa lies near the Roman road Dere Street [SUPPORTED: https://en.wikipedia.org/wiki/Aiskew_Roman_villa]; The villa dates to the 3rd and 4th centuries AD [SUPPORTED: https://en.wikipedia.org/wiki/Aiskew_Roman_villa]; A silver stylus is among the finds [SUPPORTED: https://en.wikipedia.org/wiki/Aiskew_Roman_villa]; A stamped amphora rim from north Africa is among the finds [SUPPORTED: https://en.wikipedia.org/wiki/Aiskew_Roman_villa]"}]'::jsonb),
    ('1d7cca0c-fb61-4b09-8692-52781474ed3e'::uuid, 'card_description', '3rd-7th century AD rock-cut caves at Dhank village in calcareous sandstone. The Jain cave holds figures of Adinath, Shantinath, and Pārśva — earliest Jain sculptures in Kathiawad.', 'In the rock-cut Dhank Caves, Buddhist and Jain traditions meet. The Jain cave holds figures of Adinath, Shantinath and Pārśva, considered the earliest Jain sculptures in Kathiawad.', 'teaser-card-s027:1d7cca0c-fb61-4b09-8692-52781474ed3e:card_description', 'teaser-card-s027 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '4d8428618dad28da3abcb582d0dfa95fd19c376920bf2b8e65be2660ca7ce340|e1c6fc3bd007aec4b445453856bd8262955152ad248cf373f6b7f9b9fb7fc8b7|e1c6fc3bd007aec4b445453856bd8262955152ad248cf373f6b7f9b9fb7fc8b7', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the rock-cut Dhank Caves, Buddhist and Jain traditions meet. The Jain cave holds figures of Adinath, Shantinath and Pārśva, considered the earliest Jain sculptures in Kathiawad."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Dhank Caves are rock-cut [S5]; Buddhist and Jain traditions meet there [S2, S5]; the Jain cave holds figures of Adinath, Shantinath and Pārśva [S3]; the figures are considered the earliest Jain sculptures in Kathiawad [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Dhank Caves are rock-cut caves in Gujarat, India [SUPPORTED: https://en.wikipedia.org/wiki/Dhank_Caves]; Buddhist and Jain traditions meet at the caves [SUPPORTED: https://en.wikipedia.org/wiki/Dhank_Caves]; The Jain cave holds figures of Adinath, Shantinath and Parsva [SUPPORTED: https://en.wikipedia.org/wiki/Dhank_Caves]; These figures are considered the earliest Jain sculptures in Kathiawad [SUPPORTED: https://en.wikipedia.org/wiki/Dhank_Caves]"}]'::jsonb),
    ('1db1cb71-0431-46ec-ab93-39338844dbab'::uuid, 'card_description', 'This drystone broch on the Isle of Lewis still reaches 9 metres on its east side. Occupation raised the floor level so high over time that the building eventually fell out of use.', 'On a rock on a steep slope of Lewis stands Dun Carloway, the best preserved broch in the Outer Hebrides, its wall rising to 9.2 metres. It was probably built in the 1st century AD.', 'teaser-card-s027:1db1cb71-0431-46ec-ab93-39338844dbab:card_description', 'teaser-card-s027 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '986055f798af6d30ffc57a29c8447eaa926fde85afbda33696211ca2937803dc|bbd1776415baa13f3f2a6274beaea667e0ad510b7cdc289831f67dc3ce9b169f|bbd1776415baa13f3f2a6274beaea667e0ad510b7cdc289831f67dc3ce9b169f', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a rock on a steep slope of Lewis stands Dun Carloway, the best preserved broch in the Outer Hebrides, its wall rising to 9.2 metres. It was probably built in the 1st century AD."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Dun Carloway stands on a rock [S5]; on a steep slope [S5]; on Lewis [S1]; it is a broch [S1]; it is the best preserved broch in the Outer Hebrides [S6]; its wall rises to 9.2 metres [S7]; it was probably built in the 1st century AD [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Dun Carloway is a broch [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Carloway]; Dun Carloway stands on Lewis (Isle of Lewis, Outer Hebrides, Scotland) [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Carloway]; It stands on a rock [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Carloway]; The rock lies on a steep slope [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Carloway]; It is the best preserved broch in the Outer Hebrides [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Carloway]; Its wall rises to 9.2 metres [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Carloway]; It was probably built in the 1st century AD [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Carloway]"}]'::jsonb),
    ('1dd3934e-3083-4c17-b1b6-219e4ae18f15'::uuid, 'card_description', 'The stands had a capacity of approximately 15,000 spectators and had supporting stairs and hallways that connected the different parts internally.', 'Completed in 8 BC, the Amphitheatre of Mérida seated approximately 15,000 for gladiatorial fights, while beasts waited in a pit under wood and sand at the centre before their release.', 'teaser-card-s027:1dd3934e-3083-4c17-b1b6-219e4ae18f15:card_description', 'teaser-card-s027 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '5b50e927d27b1235fd90d9f5859517664490c67843518547ecd5f3cb5111ab63|cb647717a569517cdb6148f2a1c4c8b33b9567ab0734c89dd972f5e9fda2c01c|cb647717a569517cdb6148f2a1c4c8b33b9567ab0734c89dd972f5e9fda2c01c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Completed in 8 BC, the Amphitheatre of Mérida seated approximately 15,000 for gladiatorial fights, while beasts waited in a pit under wood and sand at the centre before their release."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the amphitheatre was completed in 8 BC [S2]; its stands held approximately 15,000 spectators [S7]; it was used for gladiatorial fights [S3]; animals waited in the fossa (pit) at the centre of the arena [S5, S6]; the fossa was covered with wood and sand [S5]; the animals were held there before being released into the arena [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Amphitheatre of Mérida is a Roman amphitheatre [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_M%C3%A9rida]; It is in Mérida, Spain (ancient Emerita Augusta) [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_M%C3%A9rida]; The amphitheatre was completed in 8 BC [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_M%C3%A9rida]; The amphitheatre seated approximately 15,000 spectators [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_M%C3%A9rida]; It was used for gladiatorial fights [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_M%C3%A9rida]; Beasts waited in a pit (fossa bestiaria) before their release into the arena [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_M%C3%A9rida]; The pit lay at the centre of the arena and was covered with wood and sand [SUPPORTED: https://en.wikipedia.org/wiki/Amphitheatre_of_M%C3%A9rida]"}]'::jsonb),
    ('1e934cb8-9f3a-4536-9c9c-4656e031b680'::uuid, 'card_description', 'Iron Age hillfort in Hampshire, excavated 1928. Ramparts so thoroughly levelled that 1960s houses now ring the site — original bank survives only in the eastern quadrant.', 'On a summit of 75 metres in the village of Chilworth, bordering Southampton, lies Chilworth Ring: the site of a small univallate Iron Age hillfort, partly excavated in 1928.', 'teaser-card-s027:1e934cb8-9f3a-4536-9c9c-4656e031b680:card_description', 'teaser-card-s027 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '1d15bb8e8d17801944800c5efe649ba8856585658479b65aaaa57b0aa4ece741|371cd76fd2d25ec955ab7067a1fc7495488e64d63d2f73d7664a9a5e26dd01b2|371cd76fd2d25ec955ab7067a1fc7495488e64d63d2f73d7664a9a5e26dd01b2', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a summit of 75 metres in the village of Chilworth, bordering Southampton, lies Chilworth Ring: the site of a small univallate Iron Age hillfort, partly excavated in 1928."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies on a summit of 75 metres [S4]; it is in the village of Chilworth [S3]; it borders Southampton [S3]; it is the site of a small univallate Iron Age hillfort [S1]; it was partly excavated in 1928 [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Chilworth Ring is the site of a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Chilworth_Ring]; The hillfort is small, univallate and of the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Chilworth_Ring]; The site lies in the village of Chilworth [SUPPORTED: https://en.wikipedia.org/wiki/Chilworth_Ring]; The village borders Southampton [SUPPORTED: https://en.wikipedia.org/wiki/Chilworth_Ring]; The site lies on a summit of 75 metres [SUPPORTED: https://en.wikipedia.org/wiki/Chilworth_Ring]; The hillfort was partly excavated in 1928 [SUPPORTED: https://en.wikipedia.org/wiki/Chilworth_Ring]"}]'::jsonb),
    ('210925a1-b043-4a19-80c5-7ec9ade6d940'::uuid, 'card_description', 'Caesar''s Camp is a multivallate hillfort, a fort with multiple defensive rings, occupying an irregular promontory, with an entrance on the south side.', 'Straddling Surrey and Hampshire, the Iron Age hill fort of Caesar''s Camp encloses 10.5 hectares within multiple defensive rings. Among its finds: an early rapier of the Middle Bronze Age.', 'teaser-card-s027:210925a1-b043-4a19-80c5-7ec9ade6d940:card_description', 'teaser-card-s027 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '3119b3614d434ac22e25c428e0904005dfe2bf5b7d1b2af6be2ab6d872dcc65b|599e647a3a252faa4e0f93a532335cf12502117494e878c36bf5973fd96f9586|599e647a3a252faa4e0f93a532335cf12502117494e878c36bf5973fd96f9586', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Straddling Surrey and Hampshire, the Iron Age hill fort of Caesar''s Camp encloses 10.5 hectares within multiple defensive rings. Among its finds: an early rapier of the Middle Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site straddles Surrey and Hampshire [S1]; it is an Iron Age hill fort [S1]; it encloses 10.5 hectares [S7]; it has multiple defensive rings [S3]; its finds include an early rapier of the Middle Bronze Age [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Caesar''s Camp is an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Caesar%27s_Camp,_Rushmoor_and_Waverley]; The hill fort straddles Surrey and Hampshire [SUPPORTED: https://en.wikipedia.org/wiki/Caesar%27s_Camp,_Rushmoor_and_Waverley]; The fort encloses 10.5 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Caesar%27s_Camp,_Rushmoor_and_Waverley]; The fort has multiple defensive rings [SUPPORTED: https://en.wikipedia.org/wiki/Caesar%27s_Camp,_Rushmoor_and_Waverley]; Among its finds is an early rapier of the Middle Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Caesar%27s_Camp,_Rushmoor_and_Waverley]"}]'::jsonb),
    ('234afaf4-4030-41f9-aac6-6378d375d157'::uuid, 'card_description', 'Late Neolithic burial chamber built between 4500 and 2000 BC. Its local name — anta — belongs to a tradition of roughly 5,000 megalithic tombs constructed across the region during the Neolithic.', 'The Late Neolithic Anta das Pedras Grandes is the only surviving dolmen in its immediate area. Around it lay many flint chippings, suggesting that flint items were once made here.', 'teaser-card-s027:234afaf4-4030-41f9-aac6-6378d375d157:card_description', 'teaser-card-s027 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '4ea437e15437f54c308f0565ac73fb74b50ddba8aa9ad8805d021016549467d0|c9f24248c200b46e76288446e7f5d5f65a8354c3bc8f446f6ae8da83368450be|c9f24248c200b46e76288446e7f5d5f65a8354c3bc8f446f6ae8da83368450be', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Late Neolithic Anta das Pedras Grandes is the only surviving dolmen in its immediate area. Around it lay many flint chippings, suggesting that flint items were once made here."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is Late Neolithic [S1]; it is the only surviving dolmen in its immediate area [S4]; many flint chippings were found around it [S2]; the chippings suggest flint items were made in the area [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Anta das Pedras Grandes is a dolmen, a single chamber megalithic tomb, in Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Anta_das_Pedras_Grandes]; The Anta das Pedras Grandes is Late Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Anta_das_Pedras_Grandes]; It is the only surviving dolmen in its immediate area [SUPPORTED: https://en.wikipedia.org/wiki/Anta_das_Pedras_Grandes]; Many flint chippings lay around it [SUPPORTED: https://en.wikipedia.org/wiki/Anta_das_Pedras_Grandes]; The flint chippings suggest that flint items were once made here [SUPPORTED: https://en.wikipedia.org/wiki/Anta_das_Pedras_Grandes]"}]'::jsonb),
    ('235d48e6-9c13-4de6-a0d1-96bde161338d'::uuid, 'card_description', 'Built on ancient Salona, capital of Roman Dalmatia and birthplace of Emperor Diocletian. When Avars destroyed it, refugees moved into his nearby palace.', 'Solin grew on the site of ancient Salona, capital of Roman Dalmatia and birthplace of Emperor Diocletian. When the town was destroyed, its refugees moved to his palace at Split.', 'teaser-card-s027:235d48e6-9c13-4de6-a0d1-96bde161338d:card_description', 'teaser-card-s027 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'ffc34d23eca2a4365dbf08e447b3342f619b14305c6adc1a2d0fe165d24fe69d|dd2a46cde6a14d5fb90e7a7beb7bb5a9e5fa2a2355da71ab20cba596e8c3c7e2|dd2a46cde6a14d5fb90e7a7beb7bb5a9e5fa2a2355da71ab20cba596e8c3c7e2', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Solin grew on the site of ancient Salona, capital of Roman Dalmatia and birthplace of Emperor Diocletian. When the town was destroyed, its refugees moved to his palace at Split."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Solin grew on the site of ancient Salona [S1]; Salona was the capital of the Roman province of Dalmatia [S1]; Salona was the birthplace of Emperor Diocletian [S1]; the town was destroyed [S2]; its refugees moved to Diocletian''s palace at Split [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Solin is a town in Croatia, a suburb of Split, that grew on the site of ancient Salona [SUPPORTED: https://en.wikipedia.org/wiki/Solin]; Salona was the capital of the Roman province of Dalmatia [SUPPORTED: https://en.wikipedia.org/wiki/Solin]; Salona was the birthplace of Emperor Diocletian (the Diocletian article hedges: probably at or near Salona) [SUPPORTED: https://en.wikipedia.org/wiki/Solin]; The town of Salona was destroyed (in the 7th century, by Avars and Slavs) [SUPPORTED: https://en.wikipedia.org/wiki/Salona]; After the destruction, refugees from the town moved to Diocletian''s palace at Split [SUPPORTED: https://en.wikipedia.org/wiki/Solin]"}]'::jsonb),
    ('241df2d5-69c9-47e0-9df3-105a26a4d141'::uuid, 'card_description', 'A rocky promontory defended by vertical cliffs on all sides but one, where a massive prehistoric embankment blocks the approach. Its exact date and purpose remain unknown.', 'On Hathersage Moor, cliffs guard Carl Wark on all but one side, and a prehistoric embankment closes the gap. Read as an Iron Age hill fort, its date and purpose remain unknown.', 'teaser-card-s027:241df2d5-69c9-47e0-9df3-105a26a4d141:card_description', 'teaser-card-s027 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'b2b6d928fd1fed7e37aa6f80e8474725a1a271c41e6bd723397a532d0861e9f8|7447847341f847b48505f442e11cb8b910715884347768f4f6686195fbbbe7eb|7447847341f847b48505f442e11cb8b910715884347768f4f6686195fbbbe7eb', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Hathersage Moor, cliffs guard Carl Wark on all but one side, and a prehistoric embankment closes the gap. Read as an Iron Age hill fort, its date and purpose remain unknown."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is on Hathersage Moor [S1]; cliffs guard Carl Wark on all but one side [S2]; a prehistoric embankment closes the one open side [S2]; the enclosure is read (interpreted) as an Iron Age hill fort [S3]; its date (of construction) is unknown [S3]; its purpose is unknown [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Carl Wark is a fortified rocky promontory (an enclosure read as a hill fort) on Hathersage Moor, England [SUPPORTED: https://en.wikipedia.org/wiki/Carl_Wark]; Cliffs guard Carl Wark on all but one side [SUPPORTED: https://en.wikipedia.org/wiki/Carl_Wark]; The one side without cliffs is protected (closed) by an embankment [SUPPORTED: https://en.wikipedia.org/wiki/Carl_Wark]; The embankment is prehistoric [SUPPORTED: https://en.wikipedia.org/wiki/Carl_Wark]; The site is read (interpreted) as an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Carl_Wark]; The date of construction remains unknown [SUPPORTED: https://en.wikipedia.org/wiki/Carl_Wark]; The purpose of the fortifications remains unknown [SUPPORTED: https://en.wikipedia.org/wiki/Carl_Wark]"}]'::jsonb),
    ('24695f34-5605-4cdd-965f-fd646c1ed044'::uuid, 'card_description', 'The ahu exhibits extraordinary stonemasonry consisting of large, carefully fitted slabs of basalt.', 'On Rapa Nui, Ahu Vinapu joins large, carefully fitted slabs of basalt into one of the island''s larger ahu, its stone wall turned towards sunrise at Winter Solstice.', 'teaser-card-s027:24695f34-5605-4cdd-965f-fd646c1ed044:card_description', 'teaser-card-s027 (teaser-card): teaser card, 164 characters, checked PASS, web-verified VERIFIED', 'ede136caa0585b07c01c6de2d6fb487072fd3d0004569006c70d8d30eec25182|b4117d60f3b089ca54e1d23e64746e2d3caf6f8db412c1852864f5a4b391676d|b4117d60f3b089ca54e1d23e64746e2d3caf6f8db412c1852864f5a4b391676d', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Rapa Nui, Ahu Vinapu joins large, carefully fitted slabs of basalt into one of the island''s larger ahu, its stone wall turned towards sunrise at Winter Solstice."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is on Rapa Nui [S1]; the ahu is built of large, carefully fitted slabs of basalt [S3]; it is one of the island''s larger ahu [S2]; its stone wall faces towards sunrise at Winter Solstice [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Ahu Vinapu is a ceremonial stone platform (ahu) site on Rapa Nui (Easter Island) [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Vinapu]; Ahu Vinapu is one of the island''s larger ahu [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Vinapu]; Its stonework joins large, carefully fitted slabs [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Vinapu]; The slabs are of basalt [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Vinapu]; Its stone wall is turned towards (faces) sunrise at Winter Solstice [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Vinapu]"}]'::jsonb),
    ('248951cd-2522-4a50-8cb4-aeeef742576e'::uuid, 'card_description', 'Founded around 3200 BC to track the Nile floods, rebuilt by dynasty after dynasty for 3,000 years. A living record of architectural evolution across the ancient world.', 'On Elephantine island, the Temple of Satet began around 3200 BC as a cultic niche lodged between three large natural granite boulders, then was enlarged and renovated for 3000 years.', 'teaser-card-s027:248951cd-2522-4a50-8cb4-aeeef742576e:card_description', 'teaser-card-s027 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'e8e9e075f10c23e260f632a4cc475be0a1301cba412215e8f10fbc0a3cd44f22|da8efbac59994822167374ad00e3f404508c32e1bf462ba54e9b0a26af834e0e|da8efbac59994822167374ad00e3f404508c32e1bf462ba54e9b0a26af834e0e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Elephantine island, the Temple of Satet began around 3200 BC as a cultic niche lodged between three large natural granite boulders, then was enlarged and renovated for 3000 years."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the temple stood on Elephantine island [S2]; it began around 3200 BC [S3, S4]; the earliest temple was a cultic niche [S4]; the niche was lodged between three large natural granite boulders [S4]; the temple was later enlarged and renovated [S3, S5]; the enlargements and renovations spanned 3000 years [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Temple of Satet was an ancient Egyptian temple, dedicated to the goddess Satet, on the island of Elephantine [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Satet]; The temple began (was founded) around 3200 BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Satet]; The earliest temple was a cultic niche lodged between natural boulders [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Satet]; The boulders were three in number [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Satet]; The boulders were large, natural and of granite [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Satet]; The temple was enlarged and renovated (several times) after its beginning [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Satet]; The enlargement and renovation went on for 3000 years [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Satet]"}]'::jsonb),
    ('255da98c-7cdf-46b3-878e-7eb55df2d8c2'::uuid, 'card_description', 'Paintings of bison, horses, and human hands dating to 36,000 years ago. The polychrome ceiling is sometimes called the "Sistine Chapel of prehistory."', 'Near Santillana del Mar, the twisting passages of the Cave of Altamira hold charcoal drawings and polychrome paintings of local fauna and human hands, made over up to 20,000 years.', 'teaser-card-s027:255da98c-7cdf-46b3-878e-7eb55df2d8c2:card_description', 'teaser-card-s027 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '56125c07e5559b6cabd2e99cc10065be8b72804943777786a7281ce59259e1d9|075a1a4a1a0c01bec8bddbdbb5271e8ff7c196e9098d4baae6c59927f04154cb|075a1a4a1a0c01bec8bddbdbb5271e8ff7c196e9098d4baae6c59927f04154cb', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near Santillana del Mar, the twisting passages of the Cave of Altamira hold charcoal drawings and polychrome paintings of local fauna and human hands, made over up to 20,000 years."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the cave is near Santillana del Mar [S1]; the cave has twisting passages [S6]; it holds charcoal drawings [S2]; it holds polychrome paintings [S2]; the art shows local fauna and human hands [S2]; the paintings were made over a period of up to 20,000 years [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Cave of Altamira is a cave complex near the town of Santillana del Mar (Cantabria, Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Altamira]; The cave consists of twisting passages [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Altamira]; The cave holds charcoal drawings [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Altamira]; The cave holds polychrome paintings [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Altamira]; The art depicts local fauna [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Altamira]; The art depicts human hands [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Altamira]; The art was made over a period of up to 20,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Altamira]"}]'::jsonb),
    ('255f657f-15e7-4eee-b9d9-7a30ce68d130'::uuid, 'card_description', 'This Dere Street fort in County Durham was garrisoned by the Twentieth Legion. An inscription slab naming them was later reused as building material — history recycled by soldiers.', 'On high ground by Dere Street, the Roman fort of Longovicium drew water from two aqueducts, one fed by a stone-faced dam that harnessed 21 springs and stood 20 feet high.', 'teaser-card-s027:255f657f-15e7-4eee-b9d9-7a30ce68d130:card_description', 'teaser-card-s027 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '114087d131dcb50fe51a6093dd394181f2eb807f71c71f01e57e6eef3aee1126|291efbc508a6744d559fdbaf8c3635ae6ea12e8973fa8acdb57b4c067cb46490|291efbc508a6744d559fdbaf8c3635ae6ea12e8973fa8acdb57b4c067cb46490', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On high ground by Dere Street, the Roman fort of Longovicium drew water from two aqueducts, one fed by a stone-faced dam that harnessed 21 springs and stood 20 feet high."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the fort stood on high ground [S4]; it stood by Dere Street [S1, S3]; Longovicium was a Roman fort [S1]; it drew water from two aqueducts [S6]; one aqueduct was fed by a dam (impounded source) [S6, S7]; the dam was stone-faced [S7]; the dam harnessed the water of 21 springs [S7]; the dam stood 20 feet high [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Longovicium was a Roman fort [SUPPORTED: https://en.wikipedia.org/wiki/Longovicium]; The fort lay by (on) Dere Street [SUPPORTED: https://en.wikipedia.org/wiki/Longovicium]; The fort stood on high ground [SUPPORTED: https://en.wikipedia.org/wiki/Longovicium]; The fort had a water supply from two aqueducts [SUPPORTED: https://en.wikipedia.org/wiki/Longovicium]; One aqueduct was fed by a dam (impounded source) [SUPPORTED: https://en.wikipedia.org/wiki/Longovicium]; The dam harnessed 21 springs [SUPPORTED: https://en.wikipedia.org/wiki/Longovicium]; The dam stood 20 feet high [SUPPORTED: https://en.wikipedia.org/wiki/Longovicium]; The dam was stone-faced [SUPPORTED: https://en.wikipedia.org/wiki/Longovicium]"}]'::jsonb),
    ('2590803d-1be8-4d57-abc5-2b10da46806d'::uuid, 'card_description', 'Built around 600 BC in ancient Korkyra, this cenotaph honors a warrior lost at sea — its circular stone tomb and guardian lion sculpture among the oldest funerary monuments on the island.', 'Found in 1843 as the British army tore down a fortress in Corfu, the Tomb of Menecrates is a limestone cylinder with a conical roof, its inscription one of the oldest extant in Greece.', 'teaser-card-s027:2590803d-1be8-4d57-abc5-2b10da46806d:card_description', 'teaser-card-s027 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '29086b22d8c3fed4fcba7f3dc2ad72f7c4bde16f16345320e2ad143d225a05c0|51807edfb42475b39b87395c96ee4eeaab2b8b0377c2ca968a3d501a29c24f7a|51807edfb42475b39b87395c96ee4eeaab2b8b0377c2ca968a3d501a29c24f7a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Found in 1843 as the British army tore down a fortress in Corfu, the Tomb of Menecrates is a limestone cylinder with a conical roof, its inscription one of the oldest extant in Greece."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the tomb was found in 1843 [S2]; it was found as the British army demolished a fortress in Corfu [S2]; the tomb is made of limestone [S4]; the tomb is cylindrical [S5]; the tomb has a conical roof [S5]; its inscription is one of the oldest extant in Greece [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Tomb of Menecrates is a tomb (Archaic-period cenotaph) in Corfu, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Menecrates]; The tomb was found in 1843 [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Menecrates]; It was found while the British army was tearing down a fortress in Corfu [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Menecrates]; The tomb is made of limestone [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Menecrates]; The tomb is a cylinder with a conical roof [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Menecrates]; Its inscription is one of the oldest extant in Greece [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Menecrates]"}]'::jsonb),
    ('25f7db49-7e78-4dc6-8f6c-392fa067820d'::uuid, 'card_description', 'A Roman fort and town on Dere Street where coins, tombstones, and even sandals have surfaced. The modern village church stands on the former Roman town center.', 'At Aldborough, Isurium Brigantum was the administrative centre of the Brigantes. A massive town wall and two mosaic pavements remain, and in 2011 scanning revealed an amphitheatre.', 'teaser-card-s027:25f7db49-7e78-4dc6-8f6c-392fa067820d:card_description', 'teaser-card-s027 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'fc4407b7b5e93858219fd99b054803d991a16029d5b7f790ca2f384c854cfea0|cbf3edfa1aedcdd24d34287a74dcda6d8d22c69171d4e713a1874d07a011e097|cbf3edfa1aedcdd24d34287a74dcda6d8d22c69171d4e713a1874d07a011e097', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At Aldborough, Isurium Brigantum was the administrative centre of the Brigantes. A massive town wall and two mosaic pavements remain, and in 2011 scanning revealed an amphitheatre."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is at Aldborough [S1]; Isurium Brigantum was the administrative centre of the Brigantes [S4]; a massive town wall remains [S6]; two mosaic pavements remain [S6]; in 2011 scanning revealed an amphitheatre [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Isurium Brigantum was a Roman fort and town at Aldborough, England [SUPPORTED: https://en.wikipedia.org/wiki/Isurium_Brigantum]; Isurium Brigantum was the administrative centre of the Brigantes [SUPPORTED: https://en.wikipedia.org/wiki/Isurium_Brigantum]; A massive town wall remains at the site [SUPPORTED: https://en.wikipedia.org/wiki/Isurium_Brigantum]; Two mosaic pavements remain at the site [SUPPORTED: https://en.wikipedia.org/wiki/Isurium_Brigantum]; In 2011 scanning revealed an amphitheatre [SUPPORTED: https://en.wikipedia.org/wiki/Isurium_Brigantum]"}]'::jsonb),
    ('265f7928-8587-4158-b02f-6e5b779ae7ab'::uuid, 'card_description', 'A 4th-century AD imperial bathhouse with pools heated to 40 degrees Celsius. An underground network of service passageways beneath the complex is still visible today.', 'Begun shortly before 300 CE, the Trier Imperial Baths were never finished: work ceased around 316 CE, and in the Middle Ages the large Roman bath complex became a castle.', 'teaser-card-s027:265f7928-8587-4158-b02f-6e5b779ae7ab:card_description', 'teaser-card-s027 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', 'e9484754abf8e2609b888c9707ebb0df0487c773431d4dcc7b9b46812f48fc5f|78eada82065ff9aa0af994b83eff59bd39110ef840355270c0a10f57576ff064|78eada82065ff9aa0af994b83eff59bd39110ef840355270c0a10f57576ff064', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Begun shortly before 300 CE, the Trier Imperial Baths were never finished: work ceased around 316 CE, and in the Middle Ages the large Roman bath complex became a castle."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "construction began shortly before 300 CE [S3]; the baths were never finished [S2, S3]; work ceased around 316 CE [S3]; the baths are a large Roman bath complex [S1]; in the Middle Ages the complex became a castle [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Trier Imperial Baths are a large Roman bath complex in Trier, Germany [SUPPORTED: https://en.wikipedia.org/wiki/Trier_Imperial_Baths]; Construction began shortly before 300 CE [SUPPORTED: https://en.wikipedia.org/wiki/Trier_Imperial_Baths]; The baths were never finished [SUPPORTED: https://en.wikipedia.org/wiki/Trier_Imperial_Baths]; Work ceased around 316 CE [SUPPORTED: https://en.wikipedia.org/wiki/Trier_Imperial_Baths]; In the Middle Ages the bath complex became a castle [SUPPORTED: https://en.wikipedia.org/wiki/Trier_Imperial_Baths]"}]'::jsonb),
    ('27190db9-7e95-4f0e-a757-a897fcf7c390'::uuid, 'card_description', 'Settled in the Bronze Age and formalised as the colony Apollonia in the 7th century BC, this Black Sea port had an ancient harbour whose ruins and amphorae lie visible on the seabed.', 'Greek colonists from Miletus founded Sozopol in the 7th century BC as Antheia. In the 5th century BC it raised a colossal statue of Apollo, 13 m tall, later carried off to Rome.', 'teaser-card-s027:27190db9-7e95-4f0e-a757-a897fcf7c390:card_description', 'teaser-card-s027 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '8bbd50d9cdf406fea1a401c5fa64d33d1d6cc3b6a14639ae77370964ed65ffba|1c233aa9ef8a0be653beba5f89ecfbd492f07d4985addfa2385b27dd888aa77c|1c233aa9ef8a0be653beba5f89ecfbd492f07d4985addfa2385b27dd888aa77c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Greek colonists from Miletus founded Sozopol in the 7th century BC as Antheia. In the 5th century BC it raised a colossal statue of Apollo, 13 m tall, later carried off to Rome."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Greek colonists founded the town [S5]; the colonists came from Miletus [S5]; the founding was in the 7th century BC [S5]; the town was first called Antheia [S5]; in the 5th century BC the city raised a colossal statue of Apollo [S7]; the statue was 13 m tall [S7]; the statue was later carried off to Rome [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Sozopol is an ancient seaside town on the Black Sea coast of Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Sozopol]; Sozopol was founded by Greek colonists from Miletus [SUPPORTED: https://en.wikipedia.org/wiki/Sozopol]; Sozopol was founded in the 7th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Sozopol]; Its original name was Antheia [SUPPORTED: https://en.wikipedia.org/wiki/Sozopol]; In the 5th century BC the city raised a colossal statue of Apollo [SUPPORTED: https://en.wikipedia.org/wiki/Sozopol]; The statue of Apollo was 13 m tall [SUPPORTED: https://en.wikipedia.org/wiki/Sozopol]; The statue was later carried off to Rome [SUPPORTED: https://en.wikipedia.org/wiki/Sozopol]"}]'::jsonb),
    ('27330a46-8900-4b3b-9094-1910364284bf'::uuid, 'card_description', 'Guyaju Caves are the ruins of a cave complex that may have served as dwellings for a fortified community situated in a valley near present-day Dongmenying, Yanqing District, Beijing.', 'Cut into a cliff face at different levels, the rooms of the Guyaju Caves rise like a multistory building, and at the bottom a Chieftain''s Palace of 8 rooms stands on rock-cut columns.', 'teaser-card-s027:27330a46-8900-4b3b-9094-1910364284bf:card_description', 'teaser-card-s027 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '7ad1a390e2e20f8901cab8ffbb7ea4bb990c91dd6eb365dbd445ef9256e49f26|820137127b95fef0fcbe540dc9e8afeda500fb8814fac7ad4cbba771b91324d4|820137127b95fef0fcbe540dc9e8afeda500fb8814fac7ad4cbba771b91324d4', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cut into a cliff face at different levels, the rooms of the Guyaju Caves rise like a multistory building, and at the bottom a Chieftain''s Palace of 8 rooms stands on rock-cut columns."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the rooms are cut into a cliff face at different levels [S2]; they give the appearance of a multistory building [S2]; a Chieftain''s Palace lies at the bottom of a rock face [S3]; the Chieftain''s Palace has 8 rooms [S4]; it is supported by columns cut from the rock [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Guyaju Caves are a cave-dwelling complex in Yanqing District, Beijing, China [SUPPORTED: https://en.wikipedia.org/wiki/Guyaju_Caves]; The rooms are cut into a cliff face at different levels [SUPPORTED: https://en.wikipedia.org/wiki/Guyaju_Caves]; The rooms rise like a multistory building [SUPPORTED: https://en.wikipedia.org/wiki/Guyaju_Caves]; A Chieftain''s Palace stands at the bottom of the complex [SUPPORTED: https://en.wikipedia.org/wiki/Guyaju_Caves]; The Chieftain''s Palace has 8 rooms [SUPPORTED: https://en.wikipedia.org/wiki/Guyaju_Caves]; The Chieftain''s Palace stands on rock-cut columns [SUPPORTED: https://en.wikipedia.org/wiki/Guyaju_Caves]"}]'::jsonb),
    ('27452e11-1d7b-44cd-85fe-d6893f11baa8'::uuid, 'card_description', 'The dolmen is of a Neolithic date and was built between the 4th and 3rd millennium BC. In the 17th-century, a small whitewashed chapel was constructed around the surviving stones of the dolmen.', 'In the 17th century, a small whitewashed chapel was built around the surviving stones of a Neolithic dolmen, which still forms its narthex: the Dolmen-Chapel of São Brissos.', 'teaser-card-s027:27452e11-1d7b-44cd-85fe-d6893f11baa8:card_description', 'teaser-card-s027 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '6ddfcaf2b8bd510f88e1d7cdfa1c55fc245d96af464dcea9d63e0f8b7519ff9b|70a8b250fda10b3e29443ee4815aa0b13b29367165693ad915893e8a7ef7ffc7|70a8b250fda10b3e29443ee4815aa0b13b29367165693ad915893e8a7ef7ffc7', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the 17th century, a small whitewashed chapel was built around the surviving stones of a Neolithic dolmen, which still forms its narthex: the Dolmen-Chapel of São Brissos."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "in the 17th century a chapel was built [S5]; the chapel is small and whitewashed [S5]; it was built around the surviving stones of a dolmen [S5]; the dolmen is Neolithic [S4]; the dolmen forms the chapel''s narthex [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Dolmen-Chapel of São Brissos is a small chapel (a Christian building), i.e. a chapel built in a prehistoric tomb [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen-Chapel_of_S%C3%A3o_Brissos]; The site is in Portugal (parish of Santiago do Escoural, municipality of Montemor-o-Novo) [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen-Chapel_of_S%C3%A3o_Brissos]; The chapel is the conversion of a prehistoric tomb (a dolmen) into a Christian building [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen-Chapel_of_S%C3%A3o_Brissos]; The chapel was built in the 17th century [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen-Chapel_of_S%C3%A3o_Brissos]; The 17th-century chapel is small and whitewashed [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen-Chapel_of_S%C3%A3o_Brissos]; The chapel was built around the surviving stones of the dolmen [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen-Chapel_of_S%C3%A3o_Brissos]; The dolmen is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen-Chapel_of_S%C3%A3o_Brissos]; The dolmen forms the chapel''s narthex [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen-Chapel_of_S%C3%A3o_Brissos]"}]'::jsonb),
    ('27e87200-26a0-4b11-bc12-8b7229bd8828'::uuid, 'card_description', 'A planned ancient city with a regular street grid covering most of a hill — a rare example of systematic urban planning in the early Aegean world.', 'In the early 1970s a Dutch team of archaeologists examined Goritsa, a hill just east of central Volos, and revealed a planned ancient city with a regular street grid across most of it.', 'teaser-card-s027:27e87200-26a0-4b11-bc12-8b7229bd8828:card_description', 'teaser-card-s027 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '6c23ee9407bda588468cee0416d685164c2ae25f38e1f6ac6b1908b793b41fa2|598bb58075ab9a37e5b10710b297d019b27f3cb40fcbcda84c8bd7e8232c087c|598bb58075ab9a37e5b10710b297d019b27f3cb40fcbcda84c8bd7e8232c087c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the early 1970s a Dutch team of archaeologists examined Goritsa, a hill just east of central Volos, and revealed a planned ancient city with a regular street grid across most of it."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "a Dutch team of archaeologists examined Goritsa [S2]; the examination was in the early 1970s [S2]; Goritsa is a hill just east of central Volos [S1]; the work revealed a planned ancient city [S2]; the city had a regular street grid across most of the hill [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Goritsa is a hill (and an archaeological site) in Volos, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Goritsa_(Greece)]; The hill lies just east of central Volos [SUPPORTED: https://en.wikipedia.org/wiki/Goritsa_(Greece)]; Goritsa was examined in the early 1970s [SUPPORTED: https://en.wikipedia.org/wiki/Goritsa_(Greece)]; The examining team was Dutch, a team of archaeologists [SUPPORTED: https://en.wikipedia.org/wiki/Goritsa_(Greece)]; The examination revealed a planned ancient city [SUPPORTED: https://en.wikipedia.org/wiki/Goritsa_(Greece)]; The city had a regular street grid [SUPPORTED: https://en.wikipedia.org/wiki/Goritsa_(Greece)]; The street grid covered most of the hill [SUPPORTED: https://en.wikipedia.org/wiki/Goritsa_(Greece)]"}]'::jsonb),
    ('29589e3f-0ffb-4d6a-9844-ecf84e243cfa'::uuid, 'card_description', 'Occupied from 3300 to 1200 BC, with evidence of the earliest metallurgy in its area. Copper-smelting debris shows people here were among the first to work metal.', 'South of Toledo, on a hill on the left bank of the Tagus, Cerro del Bu''s first phase of settlement would be marked by a large quantity of flint carving remains and few ceramic fragments.', 'teaser-card-s027:29589e3f-0ffb-4d6a-9844-ecf84e243cfa:card_description', 'teaser-card-s027 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '8abd1b64df268c4b26fd04fc6e57c086bb55a647167d2baebce64dfee3451273|d5d6ba7fa24d59ca64e7649f654b4025995bd561d98bc176201db3f512e71990|d5d6ba7fa24d59ca64e7649f654b4025995bd561d98bc176201db3f512e71990', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "South of Toledo, on a hill on the left bank of the Tagus, Cerro del Bu''s first phase of settlement would be marked by a large quantity of flint carving remains and few ceramic fragments."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is south of Toledo [S2]; it is on a hill on the left bank of the Tagus [S2]; the first phase of settlement would (is said to) be marked by a large quantity of flint carving remains [S3]; the first phase would be marked by few ceramic fragments [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cerro del Bu is an archaeological site on a hill (a settled hill) [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_del_Bu]; The hill lies south of Toledo (Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_del_Bu]; The hill is on the left bank of the Tagus [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_del_Bu]; The site has a first phase of settlement [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_del_Bu]; The first phase is marked by a large quantity of flint carving remains [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_del_Bu]; The first phase has few ceramic fragments [SUPPORTED: https://en.wikipedia.org/wiki/Cerro_del_Bu]"}]'::jsonb),
    ('2a1d1dfb-474c-44db-a3ea-81758fadf851'::uuid, 'card_description', 'Inca-era complex of houses, chullpa tombs, qullqa storehouses, and enclosures near Obas in Yarowilca Province. Residential and funerary structures combined suggest an integrated community plan.', 'In the village of Cochamarca, about 8 km from Obas, lies Huichún, a name possibly from the Quechua for femur. Its houses, stone tombs, deposits and enclosures await the curious.', 'teaser-card-s027:2a1d1dfb-474c-44db-a3ea-81758fadf851:card_description', 'teaser-card-s027 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '734c90ec1e64bb72d985d2aa044139d8008f58bd8fa1b39ffd72b80cdc992d22|feaca8cf53ea2a9fe6ad20f6a2f4f4dc702278d2c723942fc4a63597dbca3e9b|feaca8cf53ea2a9fe6ad20f6a2f4f4dc702278d2c723942fc4a63597dbca3e9b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the village of Cochamarca, about 8 km from Obas, lies Huichún, a name possibly from the Quechua for femur. Its houses, stone tombs, deposits and enclosures await the curious."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is in the village of Cochamarca [S3]; it is about 8 km from Obas [S3]; the name possibly derives from the Quechua for femur [S1]; the site has houses [S2]; the site has stone tombs [S2]; the site has deposits [S2]; the site has enclosures [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Huichún is an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Huich%C3%BAn]; Huichún is in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Huich%C3%BAn]; Huichún lies in the village of Cochamarca [SUPPORTED: https://en.wikipedia.org/wiki/Huich%C3%BAn]; Huichún is about 8 km from Obas [SUPPORTED: https://en.wikipedia.org/wiki/Huich%C3%BAn]; The name Huichún is possibly from Quechua [SUPPORTED: https://en.wikipedia.org/wiki/Huich%C3%BAn]; The Quechua word meant is the word for femur [SUPPORTED: https://en.wikipedia.org/wiki/Huich%C3%BAn]; The site has houses [SUPPORTED: https://en.wikipedia.org/wiki/Huich%C3%BAn]; The site has stone tombs [SUPPORTED: https://en.wikipedia.org/wiki/Huich%C3%BAn]; The site has deposits [SUPPORTED: https://en.wikipedia.org/wiki/Huich%C3%BAn]; The site has enclosures [SUPPORTED: https://en.wikipedia.org/wiki/Huich%C3%BAn]"}]'::jsonb),
    ('2bc26dce-7797-40a5-8a39-589e5dee1453'::uuid, 'card_description', 'Cacaxtla and Xochitecatl prospered 650–900 CE, probably controlling important trade routes through the region with an enclave population of no more than 10,000 people.', 'Rediscovered by maintenance workers in September 1975, Cacaxtla holds a sprawling palace with vibrantly colored murals in Maya style. Its most famous painting is the Battle Mural.', 'teaser-card-s027:2bc26dce-7797-40a5-8a39-589e5dee1453:card_description', 'teaser-card-s027 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '91a532ade498827af4cce6fb55e0f970de14ddf0486261b1552eca8be3373fdd|3cf77ca391ee10c9e48fefe97a9e77837aa90e13cd226a2e4d854d77dd963466|3cf77ca391ee10c9e48fefe97a9e77837aa90e13cd226a2e4d854d77dd963466', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Rediscovered by maintenance workers in September 1975, Cacaxtla holds a sprawling palace with vibrantly colored murals in Maya style. Its most famous painting is the Battle Mural."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site was rediscovered by maintenance workers [S5]; the rediscovery was in September 1975 [S5]; the site holds a sprawling palace [S2]; the palace has vibrantly colored murals [S2]; the murals are painted in Maya style [S2]; the most famous of its preserved paintings is the Battle Mural [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cacaxtla is an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Cacaxtla]; Cacaxtla is in Mexico (near the southern border of Tlaxcala) [SUPPORTED: https://en.wikipedia.org/wiki/Cacaxtla]; Cacaxtla was rediscovered in September 1975 [SUPPORTED: https://en.wikipedia.org/wiki/Cacaxtla]; The rediscoverers were maintenance workers [SUPPORTED: https://en.wikipedia.org/wiki/Cacaxtla]; Cacaxtla holds a sprawling palace [SUPPORTED: https://en.wikipedia.org/wiki/Cacaxtla]; The palace has vibrantly colored murals [SUPPORTED: https://en.wikipedia.org/wiki/Cacaxtla]; The murals are painted in Maya style [SUPPORTED: https://en.wikipedia.org/wiki/Cacaxtla]; Its most famous painting is the Battle Mural [SUPPORTED: https://en.wikipedia.org/wiki/Cacaxtla]"}]'::jsonb),
    ('2c36db5a-566a-4bda-ad03-f14936f83eb8'::uuid, 'card_description', 'Over 1,500 petroglyphs on 500 basalt boulders, 500 to 5,000 years old. Three distinct cultures — Hohokam, Patayan, and Archaic — carved on the same rocks.', 'On 500 basalt boulders in Phoenix, Arizona, over 1500 Hohokam, Patayan and Archaic petroglyphs wait at the Deer Valley Petroglyph Preserve, images between 500 and 5,000 years old.', 'teaser-card-s027:2c36db5a-566a-4bda-ad03-f14936f83eb8:card_description', 'teaser-card-s027 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'd6a6cf1db4e9da9731123780a01ad19e37c2d95c1ec21bf31772fab5feb47606|79b9b3906a8a29ec23c9cf07c9c0a9da4bbd6ce2fed2c04e21026b2ab960fede|79b9b3906a8a29ec23c9cf07c9c0a9da4bbd6ce2fed2c04e21026b2ab960fede', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On 500 basalt boulders in Phoenix, Arizona, over 1500 Hohokam, Patayan and Archaic petroglyphs wait at the Deer Valley Petroglyph Preserve, images between 500 and 5,000 years old."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the petroglyphs are on 500 basalt boulders [S1]; the site is in Phoenix, Arizona [S1]; there are over 1500 petroglyphs [S1]; the petroglyphs are Hohokam, Patayan and Archaic [S1]; the petroglyphs are at the Deer Valley Petroglyph Preserve [S1]; the petroglyphs are between 500 and 5,000 years old [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Deer Valley Petroglyph Preserve is a nature preserve of petroglyphs (rock art) [SUPPORTED: https://en.wikipedia.org/wiki/Deer_Valley_Petroglyph_Preserve];