    ('2d98b59c-598f-4e05-b7ec-7233cd4e88ca'::uuid, 'card_description', 'An Iron Age castro and Islamic redoubt, part of a larger park including megalithic and Chalcolithic monuments. Bronze and Iron Age necropolises surround the site.', 'It once controlled one of the principal routes into the Algarve: the Castle of Cola, an Iron Age residence later reinforced as an Islamic outpost, behind walls 2.4 metres thick.', 'teaser-card-s027:2d98b59c-598f-4e05-b7ec-7233cd4e88ca:card_description', 'teaser-card-s027 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '76a116d7e9cc13ba95b2c39f1c6029700a794e54cce10b740d75f8609ab135dc|891a079b9ddb662af9eb9f22ef58819128f4d9342f8c0ae73a325bcbcbf8e4b2|891a079b9ddb662af9eb9f22ef58819128f4d9342f8c0ae73a325bcbcbf8e4b2', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "It once controlled one of the principal routes into the Algarve: the Castle of Cola, an Iron Age residence later reinforced as an Islamic outpost, behind walls 2.4 metres thick."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the fortification once controlled one of the principal routes into the Algarve [S4]; the Castle of Cola was an Iron Age residence [S1]; it was later reinforced as an Islamic outpost [S1, S3]; its walls are 2.4 metres thick [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Castle of Cola is a fortified castro in Portugal, an Iron Age residence and Islamic redoubt [SUPPORTED: https://en.wikipedia.org/wiki/Castle_of_Cola]; It was an Iron Age residence [SUPPORTED: https://en.wikipedia.org/wiki/Castle_of_Cola]; It was later reinforced as an Islamic outpost [SUPPORTED: https://en.wikipedia.org/wiki/Castle_of_Cola]; It once controlled one of the principal routes into the Algarve [SUPPORTED: https://en.wikipedia.org/wiki/Castle_of_Cola]; Its walls are 2.4 metres thick [SUPPORTED: https://en.wikipedia.org/wiki/Castle_of_Cola]"}]'::jsonb),
    ('2e547c1d-6f33-4342-b285-69b46d4a0b6e'::uuid, 'card_description', 'Founded 480 BC on the Gulf of Saint Euphemia, Terina minted silver coins celebrated across the Mediterranean for their artistry. Hannibal razed the city during the Second Punic War.', NULL, 'teaser-card-s027:2e547c1d-6f33-4342-b285-69b46d4a0b6e:card_description', 'teaser-card-s027 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||8abf4fb0c8dd1214f9ae330b67ad6569812361f6d88dc8547d977e086de7babc', '[{"source": "lane WB run wb-ws-2026-09-27-02: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The web check could not prove: The site matches the description by Strabo; The web check could not prove: Strabo wrote his description around 20 AD; The web check could not prove: Terina was an ancient city; The web check could not prove: The city stood on the Piano di Tirena hill; The web check could not prove: The site is in Calabria, Italy"}]'::jsonb),
    ('2f50d5d0-bcb3-4400-9cfc-bc0126ca2624'::uuid, 'card_description', 'Pons Aelius was a fort and Roman settlement at the original eastern end of Hadrian''s Wall, at the site now occupied by The Castle, Newcastle.', 'Beneath the medieval Castle Keep that gave Newcastle its name lies much of Pons Aelius, a Roman fort whose name means Aelian Bridge, at the original eastern end of Hadrian''s Wall.', 'teaser-card-s027:2f50d5d0-bcb3-4400-9cfc-bc0126ca2624:card_description', 'teaser-card-s027 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '9765f819b248c3c076530abf2f119d6a80fc01e176a9d2dc0e59a8cc360bf885|4a3ae5046b959cc50ab81d3e021429a17390fe93c530a6c9ea2a916e34178242|4a3ae5046b959cc50ab81d3e021429a17390fe93c530a6c9ea2a916e34178242', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Beneath the medieval Castle Keep that gave Newcastle its name lies much of Pons Aelius, a Roman fort whose name means Aelian Bridge, at the original eastern end of Hadrian''s Wall."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "much of the fort lies buried beneath the medieval Castle Keep [S5]; the Castle Keep gave Newcastle its name [S5]; Pons Aelius was a Roman fort [S1, S2]; the name Pons Aelius means Aelian Bridge [S3]; the fort was at the original eastern end of Hadrian''s Wall [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Pons Aelius is a Roman fort (with a small Roman settlement) on Hadrian''s Wall, at Newcastle upon Tyne in England [SUPPORTED: https://en.wikipedia.org/wiki/Pons_Aelius]; Much of the fort lies buried beneath the medieval Castle Keep of Newcastle [SUPPORTED: https://en.wikipedia.org/wiki/Pons_Aelius]; The medieval Castle Keep gave Newcastle its name [SUPPORTED: https://en.wikipedia.org/wiki/Pons_Aelius]; The name Pons Aelius means Aelian Bridge [SUPPORTED: https://en.wikipedia.org/wiki/Pons_Aelius]; The fort stood at the original eastern end of Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Pons_Aelius]"}]'::jsonb),
    ('310cc15d-fd30-4fe7-b7a6-3f138f44a1e9'::uuid, 'card_description', 'Woodhouse hill fort is an Iron Age hillfort between Frodsham and Helsby in Cheshire.', 'Steep cliffs defend its west, a rampart originally 4m high its north and east: Woodhouse Hill Fort, an Iron Age hillfort where small rounded stones believed to be slingstones were found.', 'teaser-card-s027:310cc15d-fd30-4fe7-b7a6-3f138f44a1e9:card_description', 'teaser-card-s027 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'af56f9445f1708e78480cc505eb46833ce4be400c363c47b43b72452431dbfb0|b737f16af9f1fa60f12d19990413d4aba1576aa65e91b7566384959a87d932e0|b737f16af9f1fa60f12d19990413d4aba1576aa65e91b7566384959a87d932e0', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Steep cliffs defend its west, a rampart originally 4m high its north and east: Woodhouse Hill Fort, an Iron Age hillfort where small rounded stones believed to be slingstones were found."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "steep cliffs defend the western side [S3]; a rampart defends the north and east [S4]; the rampart was originally 4m high [S5]; Woodhouse Hill Fort is an Iron Age hillfort [S1]; small rounded stones were found on the site [S6]; the stones are believed to be slingstones [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Woodhouse Hill Fort is an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Woodhouse_hill_fort]; Steep cliffs defend its west side [SUPPORTED: https://en.wikipedia.org/wiki/Woodhouse_hill_fort]; A rampart defends its north and east sides [SUPPORTED: https://en.wikipedia.org/wiki/Woodhouse_hill_fort]; The rampart was originally 4m high [SUPPORTED: https://en.wikipedia.org/wiki/Woodhouse_hill_fort]; Small rounded stones were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Woodhouse_hill_fort]; The small rounded stones are believed to be slingstones [SUPPORTED: https://en.wikipedia.org/wiki/Woodhouse_hill_fort]"}]'::jsonb),
    ('31c2fc86-3acf-4684-99dc-9f1b35e0f3b4'::uuid, 'card_description', 'Mayan shrine to the goddess Ixchel, in use from 2000 BC until the Spanish conquest in 1539 AD. One of the longest continuously active sacred sites in Mesoamerica — over three millennia of offerings.', 'Outside Corozal, the Maya ruin of Santa Rita, probably the city known as Chetumal, once controlled trade routes between the coast and the mouths of the Río Hondo and Río Nuevo.', 'teaser-card-s027:31c2fc86-3acf-4684-99dc-9f1b35e0f3b4:card_description', 'teaser-card-s027 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '856d6b0e7f07e3bf9992b3db01553fb3b61aa0b2a597897070ba4f1cafb5b63d|720bfb97702413d0fc4d1d2b8acf1e9049419b3b91a1fa8f6174dff153b7d54d|720bfb97702413d0fc4d1d2b8acf1e9049419b3b91a1fa8f6174dff153b7d54d', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Outside Corozal, the Maya ruin of Santa Rita, probably the city known as Chetumal, once controlled trade routes between the coast and the mouths of the Río Hondo and Río Nuevo."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Santa Rita lies on the outskirts of Corozal [S1]; Santa Rita is a Maya ruin [S1]; it was probably the city known as Chetumal [S2]; it once controlled trade routes between the coast and the river mouths [S4]; the rivers are the Rio Hondo and Rio Nuevo [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Santa Rita is a Maya ruin (archaeological site) [SUPPORTED: https://en.wikipedia.org/wiki/Santa_Rita,_Corozal]; Santa Rita lies outside Corozal (Belize) [SUPPORTED: https://en.wikipedia.org/wiki/Santa_Rita,_Corozal]; Santa Rita was probably the Maya city known as Chetumal [SUPPORTED: https://en.wikipedia.org/wiki/Santa_Rita,_Corozal]; The city once controlled trade routes between the coast and the mouths of two major rivers [SUPPORTED: https://en.wikipedia.org/wiki/Santa_Rita,_Corozal]; The two rivers are the Río Hondo and the Río Nuevo [SUPPORTED: https://en.wikipedia.org/wiki/Santa_Rita,_Corozal]"}]'::jsonb),
    ('32e69e53-2a3c-4e9b-9622-5606d0ddefbc'::uuid, 'card_description', 'A Bronze Age through Iron Age fort on an isolated cone-shaped mountain. Massive ramparts with multiple rings of defense protected the flattened summit.', 'Ringed by a stone wall and ditch, the flattened summit of Ipf Mountain was an early Iron Age princely seat, a regional centre of power with trade connections reaching Greece and Italy.', 'teaser-card-s027:32e69e53-2a3c-4e9b-9622-5606d0ddefbc:card_description', 'teaser-card-s027 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'afe35c8f960637403723dd1ebffd0285fe50874f038909c6d88c57c015f45edd|1ae8be4b1149b038c6cd1905e753af735be30bc14245719c07ed63064db37a07|1ae8be4b1149b038c6cd1905e753af735be30bc14245719c07ed63064db37a07', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Ringed by a stone wall and ditch, the flattened summit of Ipf Mountain was an early Iron Age princely seat, a regional centre of power with trade connections reaching Greece and Italy."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the summit is ringed by a stone wall and ditch [S2]; the summit is flattened [S2]; the Ipf was a princely seat in the early Iron Age [S7]; it was a regional centre of power [S7]; it had trade connections reaching Greece and Italy [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Ipf Mountain is a hill fort (prehistoric fortified hilltop settlement) near Bopfingen, Germany [SUPPORTED: https://en.wikipedia.org/wiki/Ipf_(mountain)]; The flattened summit is ringed by a stone wall and a ditch [SUPPORTED: https://en.wikipedia.org/wiki/Ipf_(mountain)]; In the early Iron Age the Ipf was a princely seat [SUPPORTED: https://en.wikipedia.org/wiki/Ipf_(mountain)]; It was a regional centre of power [SUPPORTED: https://en.wikipedia.org/wiki/Ipf_(mountain)]; It had trade connections reaching Greece and Italy [SUPPORTED: https://en.wikipedia.org/wiki/Ipf_(mountain)]"}]'::jsonb),
    ('331d86ab-697d-411b-b61b-6af1875c7e1c'::uuid, 'card_description', 'The La Torre-La Janera megalithic site is located in the municipalities of Ayamonte and Villablanca in the province of Huelva.', 'In 2018 a farmer in Huelva set out to plant avocados. The survey that followed has so far revealed 526 standing stones at La Torre-La Janera Megalithic Site, upright or lying on the surface.', 'teaser-card-s027:331d86ab-697d-411b-b61b-6af1875c7e1c:card_description', 'teaser-card-s027 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', 'c1aca571b74cb2d694b49c46e5a792ae705624586df23e7be4d909fe2f8a9123|76f960892d3daf6fcab9445de6b46eb417de650ab16c915ae073f12a18e74dfb|76f960892d3daf6fcab9445de6b46eb417de650ab16c915ae073f12a18e74dfb', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In 2018 a farmer in Huelva set out to plant avocados. The survey that followed has so far revealed 526 standing stones at La Torre-La Janera Megalithic Site, upright or lying on the surface."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "in 2018 a farmer intended to plant (cultivate) avocados [S2]; the farmer was in Huelva [S1, S2]; a survey followed [S2, S4]; the survey has so far revealed 526 standing stones [S4]; the stones are upright or lying on the surface [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "La Torre-La Janera is a megalithic site (standing stones) in the province of Huelva, Spain [SUPPORTED: https://en.wikipedia.org/wiki/La_Torre-La_Janera_megalithic_site]; The site came to light in 2018 [SUPPORTED: https://en.wikipedia.org/wiki/La_Torre-La_Janera_megalithic_site]; A farmer set out to prepare the land for avocado cultivation [SUPPORTED: https://en.wikipedia.org/wiki/La_Torre-La_Janera_megalithic_site]; A survey followed the farmer''s plan (demanded by the local council) [SUPPORTED: https://en.wikipedia.org/wiki/La_Torre-La_Janera_megalithic_site]; The survey has so far revealed 526 standing stones [SUPPORTED: https://en.wikipedia.org/wiki/La_Torre-La_Janera_megalithic_site]; The stones are either upright or lying on the surface [SUPPORTED: https://en.wikipedia.org/wiki/La_Torre-La_Janera_megalithic_site]"}]'::jsonb),
    ('333616b7-4363-4251-9d94-397160f5d560'::uuid, 'card_description', 'A Roman town with extensive remains including an aqueduct, thermal baths, and a forum. Its location on the road between Zaragoza and Pamplona made it a hub of trade and transport.', 'Los Bañales holds a Roman city whose name remains unconfirmed, likely Tarraca. An aqueduct brought it water from a nearby reservoir; monumental baths rose at the end of the 1st century CE.', 'teaser-card-s027:333616b7-4363-4251-9d94-397160f5d560:card_description', 'teaser-card-s027 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '715b2a12d9d587054c93f4896d46b97044e5dbf44fb5ade744eb11cc3f04d191|4c60f60a2a82089d027cbabeda0483df6a01f560d02d67ef6242a6405ad11b43|4c60f60a2a82089d027cbabeda0483df6a01f560d02d67ef6242a6405ad11b43', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Los Bañales holds a Roman city whose name remains unconfirmed, likely Tarraca. An aqueduct brought it water from a nearby reservoir; monumental baths rose at the end of the 1st century CE."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Los Bañales holds a Roman city [S1, S2]; the city''s name remains unconfirmed [S2]; the name was likely Tarraca [S2]; an aqueduct brought water to the city [S4]; the water came from a nearby reservoir [S4]; monumental baths were built at the end of the 1st century CE [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Los Bañales is a Roman archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Los_Ba%C3%B1ales]; The site holds a Roman city [SUPPORTED: https://en.wikipedia.org/wiki/Los_Ba%C3%B1ales]; The city''s name remains unconfirmed [SUPPORTED: https://en.wikipedia.org/wiki/Los_Ba%C3%B1ales]; The city was likely Tarraca [SUPPORTED: https://en.wikipedia.org/wiki/Los_Ba%C3%B1ales]; An aqueduct brought water to the city [SUPPORTED: https://en.wikipedia.org/wiki/Los_Ba%C3%B1ales]; The water came from a nearby reservoir [SUPPORTED: https://en.wikipedia.org/wiki/Los_Ba%C3%B1ales]; The city had monumental baths (thermal baths) [SUPPORTED: https://en.wikipedia.org/wiki/Los_Ba%C3%B1ales]; The monumental baths were built at the end of the 1st century CE [SUPPORTED: https://en.wikipedia.org/wiki/Los_Ba%C3%B1ales]"}]'::jsonb),
    ('334be182-1b41-46d3-9fa1-d9ee8204db80'::uuid, 'card_description', 'A Neolithic timber circle from 4300-2500 BC, detected from the air in 1929. The wooden posts rotted millennia ago, but their dark soil marks show up as cropmarks.', 'Flying at around 2,000 feet in 1929, Gilbert Insall noticed cropmarks near Arminghall: rings around a horseshoe of eight pits, postholes for timbers that would have been almost 1 m across.', 'teaser-card-s027:334be182-1b41-46d3-9fa1-d9ee8204db80:card_description', 'teaser-card-s027 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '5ac30ac3e75cc250421b7fc713972ed94d6f90f2a65ba0231b9f23bb0c312673|64c97e64943d45a47716a5dba6a3ceeb65786e9bcc74eea667a89692efa2789c|64c97e64943d45a47716a5dba6a3ceeb65786e9bcc74eea667a89692efa2789c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Flying at around 2,000 feet in 1929, Gilbert Insall noticed cropmarks near Arminghall: rings around a horseshoe of eight pits, postholes for timbers that would have been almost 1 m across."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Gilbert Insall noticed cropmarks [S1, S2]; he was flying at around 2,000 feet when he noticed them [S2]; the discovery was in 1929 [S1]; the cropmarks were near Arminghall [S1]; the cropmarks showed rings around a horseshoe [S2]; the horseshoe consisted of eight pits [S2, S6]; the pits were postholes for timbers [S6]; the timbers would have been almost 1 m across [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Arminghall is a prehistoric timber circle and henge monument site [SUPPORTED: https://en.wikipedia.org/wiki/Arminghall]; The site lies near Arminghall (north-west of the village) [SUPPORTED: https://en.wikipedia.org/wiki/Arminghall]; The discovery was in 1929 [SUPPORTED: https://en.wikipedia.org/wiki/Arminghall]; Gilbert Insall made the discovery while taking aerial photographs [SUPPORTED: https://en.wikipedia.org/wiki/Arminghall]; He was flying at around 2,000 feet [SUPPORTED: https://en.wikipedia.org/wiki/Arminghall]; He noticed cropmarks (of a circular enclosure) [SUPPORTED: https://en.wikipedia.org/wiki/Arminghall]; The cropmarks showed rings (two concentric rings) [SUPPORTED: https://en.wikipedia.org/wiki/Arminghall]; Inside the rings was a horseshoe of eight pits [SUPPORTED: https://en.wikipedia.org/wiki/Arminghall]; The pits were postholes for timbers [SUPPORTED: https://en.wikipedia.org/wiki/Arminghall]; The timbers would have been almost 1 m across [SUPPORTED: https://en.wikipedia.org/wiki/Arminghall]"}]'::jsonb),
    ('355d25f2-d08d-44d5-8462-0238791d5c92'::uuid, 'card_description', 'A portal tomb whose enormous granite capstone has slipped from its original position. Known locally as Pat Kearney''s Big Stone, it once stood balanced on upright slabs.', 'In a farmer''s field, the huge granite capstone of Goward Dolmen, locally called Pat Kearney''s Big Stone, has slipped askew. Digs in the 1830''s found a cremation urn and a flint arrowhead.', 'teaser-card-s027:355d25f2-d08d-44d5-8462-0238791d5c92:card_description', 'teaser-card-s027 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'd165fd558a07e6cc89884d3463f6a1494596a85343a37996f48b2a9d0ef60a01|e3494ff8608b3ec25420f6281aed9b5ddabcb6d52b16e96bce1a5556c4a78bfe|e3494ff8608b3ec25420f6281aed9b5ddabcb6d52b16e96bce1a5556c4a78bfe', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In a farmer''s field, the huge granite capstone of Goward Dolmen, locally called Pat Kearney''s Big Stone, has slipped askew. Digs in the 1830''s found a cremation urn and a flint arrowhead."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the dolmen stands in a farmer''s field [S2]; the capstone is huge and granite [S4]; the site is locally called Pat Kearney''s Big Stone [S3]; the capstone has slipped out of its original horizontal position [S4]; excavations in the 1830''s found a cremation urn [S6]; excavations in the 1830''s found a flint arrowhead [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Goward Dolmen is a dolmen (megalithic tomb) in County Down, Northern Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Goward_Dolmen]; The monument is a portal tomb, i.e. a burial monument [SUPPORTED: https://www.communities-ni.gov.uk/heritage-sites/goward-dolmen]; It stands in a farmer''s field [SUPPORTED: https://en.wikipedia.org/wiki/Goward_Dolmen]; Its capstone is huge and made of granite [SUPPORTED: https://www.communities-ni.gov.uk/heritage-sites/goward-dolmen]; The capstone has slipped askew (out of its original horizontal position) [SUPPORTED: https://en.wikipedia.org/wiki/Goward_Dolmen]; The dolmen is called locally Pat Kearney''s Big Stone [SUPPORTED: https://en.wikipedia.org/wiki/Goward_Dolmen]; A cremation urn and a flint arrowhead were found here [SUPPORTED: https://www.visitmournegullionstrangford.com/things-to-do/goward-dolmen-p712191]; The urn and arrowhead were found by digs (excavations) in the 1830s (note: the Department for Communities register says only ''an early report'' of the find and that there has been no archaeological excavation; Wikipedia and the Mourne Gullion Strangford tourism page both say excavations in the 1830s / 1834) [SUPPORTED: https://en.wikipedia.org/wiki/Goward_Dolmen]"}]'::jsonb),
    ('3569c20c-c279-4f19-ae36-9f52ddf16c6c'::uuid, 'card_description', 'Naqsh-e Rajab is the site of four limestone rockface inscriptions and rock-cut bas-reliefs that date to the early Sasanian Empire.', 'North of Persepolis, Naqsh-e Rajab bears early Sasanian reliefs in limestone: Shapur on horseback receiving a diadem from Ahura Mazda, the high priest Kerdir with a 31-line inscription.', 'teaser-card-s027:3569c20c-c279-4f19-ae36-9f52ddf16c6c:card_description', 'teaser-card-s027 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '2878029d6fdac49c75eab63810f02dd207269ce730a40baa6678f767697b9a76|08570d3dc4a5dd43fee1fd9b1ded16147fc3c2fa8adc6a916455ea79b96d02ff|08570d3dc4a5dd43fee1fd9b1ded16147fc3c2fa8adc6a916455ea79b96d02ff', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "North of Persepolis, Naqsh-e Rajab bears early Sasanian reliefs in limestone: Shapur on horseback receiving a diadem from Ahura Mazda, the high priest Kerdir with a 31-line inscription."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies north of Persepolis [S1]; it bears early Sasanian reliefs [S2]; the reliefs are in limestone [S2]; one relief shows Shapur on horseback receiving a diadem from Ahura Mazda [S4]; one relief shows the high priest Kerdir [S7]; the Kerdir relief has a 31-line inscription [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Naqsh-e Rajab is an archaeological site of rock reliefs, north of Persepolis (Fars province, Iran) [SUPPORTED: https://en.wikipedia.org/wiki/Naqsh-e_Rajab]; The reliefs are early Sasanian and cut in limestone [SUPPORTED: https://en.wikipedia.org/wiki/Naqsh-e_Rajab]; One relief shows Shapur on horseback receiving a diadem [SUPPORTED: https://en.wikipedia.org/wiki/Naqsh-e_Rajab]; The diadem (ring of power) is given to Shapur by Ahura Mazda [SUPPORTED: https://en.wikipedia.org/wiki/Naqsh-e_Rajab]; Another relief shows the high priest Kerdir [SUPPORTED: https://en.wikipedia.org/wiki/Naqsh-e_Rajab]; Kerdir''s relief carries a 31-line inscription [SUPPORTED: https://sites.uci.edu/sasanika/kartir-inscription-naqs-e-rajab-knrb/]"}]'::jsonb),
    ('360a4afb-9c39-427b-bed1-9b0201a59ae5'::uuid, 'card_description', 'A 135-kilometre national trail following the Roman frontier wall from coast to coast. Part of the "Frontiers of the Roman Empire" World Heritage Site.', 'For 84 miles from coast to coast, Hadrian''s Wall Path mostly keeps close to the wall the Romans built on their empire''s northern border, wildest between Chollerford and Walton.', 'teaser-card-s027:360a4afb-9c39-427b-bed1-9b0201a59ae5:card_description', 'teaser-card-s027 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'fee8f82d87e692d0e8255efda2efb9f8279057de3ccb4b0334b7df28ad290e69|1df02f8ca4f6fc383acf91cc62da9f4477595405d5e11919e39aa8d17fff5d44|1df02f8ca4f6fc383acf91cc62da9f4477595405d5e11919e39aa8d17fff5d44', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "For 84 miles from coast to coast, Hadrian''s Wall Path mostly keeps close to the wall the Romans built on their empire''s northern border, wildest between Chollerford and Walton."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the path runs for 84 miles [S2]; it runs from coast to coast [S2]; for most of its length it keeps close to Hadrian''s Wall [S3]; the wall was built by the Romans on their empire''s northern border [S3]; the section between Chollerford and Walton is the wildest part of the path [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Hadrian''s Wall Path is a long-distance footpath (National Trail) in the north of England [SUPPORTED: https://en.wikipedia.org/wiki/Hadrian%27s_Wall_Path]; The path is 84 miles long [SUPPORTED: https://www.nationaltrail.co.uk/en_GB/trails/hadrians-wall-path/trail-information/]; It runs coast to coast, from the east coast (Wallsend) to the west coast (Bowness-on-Solway) [SUPPORTED: https://en.wikipedia.org/wiki/Hadrian%27s_Wall_Path]; For most of its length the path keeps close to Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Hadrian%27s_Wall_Path]; The wall was built by the Romans on the northern border of their empire [SUPPORTED: https://en.wikipedia.org/wiki/Hadrian%27s_Wall_Path]; The wildest part of the path is between Chollerford and Walton [SUPPORTED: https://en.wikipedia.org/wiki/Hadrian%27s_Wall_Path]"}]'::jsonb),
    ('360da20f-8f95-4ba9-83fc-49d4b193b679'::uuid, 'card_description', 'Limestone caves with evidence of habitation from 11,000 BC to the 3rd century AD. The larger cave has nine chambers connected by narrow passages, with sinkholes letting in daylight.', NULL, 'teaser-card-s027:360da20f-8f95-4ba9-83fc-49d4b193b679:card_description', 'teaser-card-s027 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||1437d42b2a17af3a03d51f189744da2005fc474b87d67940d70b14ec44e27a83', '[{"source": "lane WB run wb-ws-2026-09-27-02: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The web check contradicts: The larger cave is lit by three large sinkholes (contradicted: the original excavation report, Aung Thaw 1971, Asian Perspectives 14, says sunlight enters through sinkholes or apertures in the roofs of four caverns; this caving guide likewise counts four holes in the ceiling; only Wikipedia and a copy of it say three) (https://www.showcaves.com/english/mm/showcaves/Padalin.html: \"A 350 m long passage with nine chambers is illuminated by four holes in the ceiling.\"); The web check could not prove: Padah-Lin Caves are limestone caves; The web check could not prove: The caves are in Myanmar"}]'::jsonb),
    ('3807e5f9-2923-473d-930a-cc11b2b1138d'::uuid, 'card_description', 'A prehistoric monument of 223 standing stones, menhirs, and burial cists in the Syunik highlands. Often called a local "Stonehenge" for its scale and mystery.', 'On a mountain plateau 1,770 metres up, Carahunge Prehistoric Monument counts 223 basalt stones, eroded by time and covered with moss and lichen of many colours, weighing up to 10 tons.', 'teaser-card-s027:3807e5f9-2923-473d-930a-cc11b2b1138d:card_description', 'teaser-card-s027 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '5a7121fa21c950af5263d8f1bfdaf52b4b24f9850d0ca659338b584d8e2e74d8|c4f97d13281c2810c04580c239df0d7514fe47bbd48f9ebd5a3e416466f782e6|c4f97d13281c2810c04580c239df0d7514fe47bbd48f9ebd5a3e416466f782e6', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a mountain plateau 1,770 metres up, Carahunge Prehistoric Monument counts 223 basalt stones, eroded by time and covered with moss and lichen of many colours, weighing up to 10 tons."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is on a mountain plateau [S2]; the altitude is 1,770 metres [S2]; 223 stones have been counted [S5]; the stones are basalt [S6]; the stones are eroded by time [S6]; the stones are covered with moss and lichen of many colours [S6]; the stones weigh up to 10 tons [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Carahunge is a prehistoric stone monument (archaeological site) near Sisian, Armenia [SUPPORTED: https://en.wikipedia.org/wiki/Carahunge]; It lies on a mountain plateau at 1,770 metres altitude [SUPPORTED: https://en.wikipedia.org/wiki/Carahunge]; The site counts 223 stones [SUPPORTED: https://en.wikipedia.org/wiki/Carahunge]; The stones are basalt [SUPPORTED: https://en.wikipedia.org/wiki/Carahunge]; The stones are eroded by time [SUPPORTED: https://en.wikipedia.org/wiki/Carahunge]; The stones are covered with moss and lichen of many colours [SUPPORTED: https://en.wikipedia.org/wiki/Carahunge]; The stones weigh up to 10 tons [SUPPORTED: https://en.wikipedia.org/wiki/Carahunge]"}]'::jsonb),
    ('38a17d5e-fd25-457f-9286-dce01bc61696'::uuid, 'card_description', 'Yuknoom the Great, the ruler of Calakmul, supervised the accession of six-year-old Muwaan Jol, king of Moral Reforma, in 662 CE.', 'At the Maya site of Moral-Reforma, a six-year-old king, Muwaan Jol, took the throne in 662 CE under the ruler of Calakmul. In 690 CE the same king was installed again, now under Palenque.', 'teaser-card-s027:38a17d5e-fd25-457f-9286-dce01bc61696:card_description', 'teaser-card-s027 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '792cc27111dc946a8c58cd7669b16f95110ad45927a7ad3e369d45de8220e356|8649464e77d4d1da29f09f9de290a1e00ad49786e69a2e3bbad95f21bec42a6a|8649464e77d4d1da29f09f9de290a1e00ad49786e69a2e3bbad95f21bec42a6a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At the Maya site of Moral-Reforma, a six-year-old king, Muwaan Jol, took the throne in 662 CE under the ruler of Calakmul. In 690 CE the same king was installed again, now under Palenque."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Moral-Reforma is a Maya site [S1]; the king Muwaan Jol was six years old at his accession [S2]; he took the throne in 662 CE [S2]; the ruler of Calakmul oversaw that accession (he took the throne under him) [S2]; in 690 CE the same king was installed [S3]; this was a second installation of the same king (installed again) [S2, S3]; the 690 installation was under Palenque (under the patronage of K''inich Kan Balam II of Palenque) [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Moral-Reforma is a Maya archaeological site, a Maya city in the municipality of Balancán, Tabasco, Mexico [SUPPORTED: https://lugares.inah.gob.mx/en/node/4451]; Muwaan Jol was a king of Moral-Reforma [SUPPORTED: https://en.wikipedia.org/wiki/Moral_Reforma]; The king Muwaan Jol was six years old at his 662 CE accession [SUPPORTED: https://en.wikipedia.org/wiki/Moral_Reforma]; Muwaan Jol took the throne (accession ceremony) in 662 CE (the second source counts 662 CE as a second accession, after a first one on 7 May 661 CE) [SUPPORTED: https://www.themayanruinswebsite.com/moral-reforma.html]; The 662 CE accession took place under the ruler of Calakmul, Yuknoom Chen II the Great [SUPPORTED: https://www.themayanruinswebsite.com/moral-reforma.html]; In 690 CE the same king, Muwaan Jol, was installed again [SUPPORTED: https://www.themayanruinswebsite.com/moral-reforma.html]; The 690 CE installation was under the patronage of K''inich Kan Balam II of Palenque [SUPPORTED: https://en.wikipedia.org/wiki/Moral_Reforma]"}]'::jsonb),
    ('3b1d4d7e-d27d-4910-90c2-2ac662cb304f'::uuid, 'card_description', 'A Neolithic cave tomb and a Chalcolithic beehive tomb near the beach. The site represents a rare combination of two distinct prehistoric burial traditions in one place.', 'The Praia das Maçãs Prehistoric Monument joins an artificial Neolithic cave with a later domed tomb, its chamber approximately 5.5 m across. Arrowheads and cylindrical idols were found.', 'teaser-card-s027:3b1d4d7e-d27d-4910-90c2-2ac662cb304f:card_description', 'teaser-card-s027 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '7fa64642d1d6409979cbe06a26526fe9e5c02ba0905d802fd82fd52af5863110|faa1cbb7c6182171d9e8877a4317de8a5ab636f599d21e7d2b64f8aeb961a0dc|faa1cbb7c6182171d9e8877a4317de8a5ab636f599d21e7d2b64f8aeb961a0dc', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Praia das Maçãs Prehistoric Monument joins an artificial Neolithic cave with a later domed tomb, its chamber approximately 5.5 m across. Arrowheads and cylindrical idols were found."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the monument consists of an artificial Neolithic cave [S1]; and a later domed tomb [S1, S4]; the tomb''s chamber is approximately 5.5 m across [S4]; arrowheads were found at the site [S7]; cylindrical idols were found at the site [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The monument includes an artificial Neolithic cave [SUPPORTED: https://en.wikipedia.org/wiki/Praia_das_Ma%C3%A7%C3%A3s_Prehistoric_Monument]; The monument includes a domed tomb [SUPPORTED: https://en.wikipedia.org/wiki/Praia_das_Ma%C3%A7%C3%A3s_Prehistoric_Monument]; The domed tomb is later than the cave [SUPPORTED: https://en.wikipedia.org/wiki/Praia_das_Ma%C3%A7%C3%A3s_Prehistoric_Monument]; The chamber is approximately 5.5 m across [SUPPORTED: https://en.wikipedia.org/wiki/Praia_das_Ma%C3%A7%C3%A3s_Prehistoric_Monument]; Arrowheads were found [SUPPORTED: https://en.wikipedia.org/wiki/Praia_das_Ma%C3%A7%C3%A3s_Prehistoric_Monument]; Cylindrical idols were found [SUPPORTED: https://en.wikipedia.org/wiki/Praia_das_Ma%C3%A7%C3%A3s_Prehistoric_Monument]"}]'::jsonb),
    ('3b2ac589-fc14-4d95-a457-9b2912e40b0b'::uuid, 'card_description', 'Around 4000 BC, the Cucuteni-Trypillian culture built a mega-settlement here covering 260-300 hectares with over 1,200 structures. At that time, up to 17,000 people lived within its bounds.', 'Nebelivka Archaeological Site is a Cucuteni-Trypillian mega-settlement of 4000 B.C. Excavators uncovered a two-storey mud and wood structure, 60 by 20 metres, with a galleried courtyard.', 'teaser-card-s027:3b2ac589-fc14-4d95-a457-9b2912e40b0b:card_description', 'teaser-card-s027 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '9b453115664c82018b6cd7e42ffb60e59fd13baff3aed27e0e008f8ac1ad2932|9d84ee15867ee14d456da7cd1309eb4d5d41549b4ce99ece92de1110a14ea301|9d84ee15867ee14d456da7cd1309eb4d5d41549b4ce99ece92de1110a14ea301', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Nebelivka Archaeological Site is a Cucuteni-Trypillian mega-settlement of 4000 B.C. Excavators uncovered a two-storey mud and wood structure, 60 by 20 metres, with a galleried courtyard."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Nebelivka is a Cucuteni-Trypillian mega-settlement [S1]; it dates to 4000 B.C. [S1]; a two-storey structure was excavated [S4]; the structure is of mud and wood [S4]; it measures 60 by 20 metres [S4]; it has a galleried courtyard [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Nebelivka is a mega-settlement [SUPPORTED: https://en.wikipedia.org/wiki/Nebelivka_(archaeological_site)]; It belongs to the Cucuteni-Trypillian culture [SUPPORTED: https://en.wikipedia.org/wiki/Nebelivka_(archaeological_site)]; It dates to 4000 B.C. [SUPPORTED: https://en.wikipedia.org/wiki/Nebelivka_(archaeological_site)]; A two-storey structure was excavated [SUPPORTED: https://en.wikipedia.org/wiki/Nebelivka_(archaeological_site)]; The structure is of mud and wood [SUPPORTED: https://en.wikipedia.org/wiki/Nebelivka_(archaeological_site)]; The structure measures 60 by 20 metres [SUPPORTED: https://en.wikipedia.org/wiki/Nebelivka_(archaeological_site)]; The structure has a galleried courtyard [SUPPORTED: https://en.wikipedia.org/wiki/Nebelivka_(archaeological_site)]"}]'::jsonb),
    ('3bee62b6-a82c-4191-86a1-24aad78dab71'::uuid, 'card_description', 'La Centinela lies about 200 km south of Lima in the Chincha Valley and about 1 km away from the Pacific Ocean and is surrounded by irrigated agricultural land.', 'About 1 km from the Pacific, in the Chincha Valley, La Centinela rises in 11 adobe pyramid structures. Inside its principal Inca building waits a black and red on white geometric painting.', 'teaser-card-s027:3bee62b6-a82c-4191-86a1-24aad78dab71:card_description', 'teaser-card-s027 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '2f40a9de7e3e3d377f42fd4be5e30f40ae135d2c626ccd4e62f61c6fcbc833e3|91dde489fa9a69d51fb6096722b330dc2f77ac910bc0e97e7c835ce6c14e89d7|91dde489fa9a69d51fb6096722b330dc2f77ac910bc0e97e7c835ce6c14e89d7', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "About 1 km from the Pacific, in the Chincha Valley, La Centinela rises in 11 adobe pyramid structures. Inside its principal Inca building waits a black and red on white geometric painting."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "La Centinela lies about 1 km from the Pacific [S2]; it lies in the Chincha Valley [S2]; there are 11 pyramid structures [S4]; the pyramid structures are of adobe [S4]; the site has a principal Inca building [S6]; a black and red on white geometric painting is found inside that building [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "La Centinela is an archaeological site (ruins of the Chincha capital that was also an Inca administrative center) in Peru [SUPPORTED: https://en.wikipedia.org/wiki/La_Centinela]; La Centinela lies in the Chincha Valley [SUPPORTED: https://www.encyclopedia.com/humanities/encyclopedias-almanacs-transcripts-and-maps/la-centinela]; La Centinela is about 1 km from the Pacific Ocean [SUPPORTED: https://doczz.net/doc/4484724/and-sweet-potato-in-peru---international-potato-center]; La Centinela has 11 pyramid structures (11 major, clearly defined pyramid structures plus minor buildings; the Peruvian tourism inventory counts 14 pyramidal units for the whole complex including the Tambo de Mora group, a different count) [SUPPORTED: https://doczz.net/doc/4484724/and-sweet-potato-in-peru---international-potato-center]; The pyramid structures are built of adobe [SUPPORTED: https://doczz.net/doc/4484724/and-sweet-potato-in-peru---international-potato-center]; La Centinela has a principal Inca building (the Inca built a compound of their own among the local Chincha compounds) [SUPPORTED: https://www.encyclopedia.com/humanities/encyclopedias-almanacs-transcripts-and-maps/la-centinela]; A black and red on white geometric painting is found in the principal Inca building (Wallace 1998 describes the Inca compound mural as black and red on white walls, plus a now-eroded green that Uhle described) [SUPPORTED: https://en.wikipedia.org/wiki/La_Centinela]"}]'::jsonb),
    ('3c1e886f-d77b-4d46-899b-2aaf26861a4d'::uuid, 'card_description', 'A burial ground of the Chernyakhov culture with 315 burials — 253 cremations and 62 inhumations. It is the most studied Chernyakhov site in Right-bank territory, excavated from 1973 to 2000.', 'From 1973 to 2000 Ihor Gereta investigated the Burial Ground of Cherneliv-Ruskyi, finding Chernyakhov, Kievan Rus'' and Pomeranian burials and one unidentified, probably from the Bronze Age.', 'teaser-card-s027:3c1e886f-d77b-4d46-899b-2aaf26861a4d:card_description', 'teaser-card-s027 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '6a6bda362b62f8cdd19e257eecb5aacbb3de633326a89338aeda3da29de1a2b0|ff262924b8d813e73ec4e82be160f8f3fea15d3d43e281b7b1d9d51f657a93a4|ff262924b8d813e73ec4e82be160f8f3fea15d3d43e281b7b1d9d51f657a93a4', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "From 1973 to 2000 Ihor Gereta investigated the Burial Ground of Cherneliv-Ruskyi, finding Chernyakhov, Kievan Rus'' and Pomeranian burials and one unidentified, probably from the Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site was investigated from 1973 to 2000 [S3]; by Ihor Gereta [S3]; Chernyakhov burials were found [S4]; Kievan Rus'' burials were found [S4]; Pomeranian burials were found [S4]; one burial is unidentified [S4]; that burial probably dates from the Bronze Age [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Burial Ground of Cherneliv-Ruskyi is a burial ground (Chernyakhov culture burial site) in Cherneliv-Ruskyi, Ukraine [SUPPORTED: https://en.wikipedia.org/wiki/Burial_ground_of_Cherneliv-Ruskyi]; It was investigated from 1973 to 2000 [SUPPORTED: https://en.wikipedia.org/wiki/Burial_ground_of_Cherneliv-Ruskyi]; The investigator was Ihor Gereta [SUPPORTED: https://en.wikipedia.org/wiki/Burial_ground_of_Cherneliv-Ruskyi]; Chernyakhov burials were found [SUPPORTED: https://en.wikipedia.org/wiki/Burial_ground_of_Cherneliv-Ruskyi]; Kievan Rus'' burials were found [SUPPORTED: https://en.wikipedia.org/wiki/Burial_ground_of_Cherneliv-Ruskyi]; Pomeranian burials were found [SUPPORTED: https://en.wikipedia.org/wiki/Burial_ground_of_Cherneliv-Ruskyi]; One burial is unidentified [SUPPORTED: https://en.wikipedia.org/wiki/Burial_ground_of_Cherneliv-Ruskyi]; The unidentified burial is probably from the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Burial_ground_of_Cherneliv-Ruskyi]"}]'::jsonb),
    ('3c412ef3-5dd8-4079-b1b9-d38b7f711edd'::uuid, 'card_description', 'A triumphal arch commissioned by Septimius Severus, born in nearby Leptis Magna. Found in ruins, it was pieced back together by archaeologists.', 'In the ruins of Leptis Magna, eight Corinthian columns frame the Arch of Septimius Severus. It fell into ruin in the fifth century and was rebuilt after its rediscovery in 1928.', 'teaser-card-s027:3c412ef3-5dd8-4079-b1b9-d38b7f711edd:card_description', 'teaser-card-s027 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'f5a9d1f8be56852fb302963e4619bc483688c77e3d5f8c3987359588e9ab95b9|d62afef5a3cd6f5a6f3b7f0f9ed0906782089897be9a1f09840464c90a7a634e|d62afef5a3cd6f5a6f3b7f0f9ed0906782089897be9a1f09840464c90a7a634e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the ruins of Leptis Magna, eight Corinthian columns frame the Arch of Septimius Severus. It fell into ruin in the fifth century and was rebuilt after its rediscovery in 1928."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the arch stands in the ruins of Leptis Magna [S1]; eight Corinthian columns frame the arch [S5]; the arch fell into ruin in the fifth century [S3]; it was rebuilt after its rediscovery [S3]; the rediscovery was in 1928 [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Arch of Septimius Severus is a triumphal arch at Leptis Magna, in Libya [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Septimius_Severus_(Leptis_Magna)]; Leptis Magna, where the arch stands, is a ruined city [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Septimius_Severus_(Leptis_Magna)]; The arch is framed by eight columns [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Septimius_Severus_(Leptis_Magna)]; The eight columns are Corinthian [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Septimius_Severus_(Leptis_Magna)]; The arch fell into ruin in the fifth century [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Septimius_Severus_(Leptis_Magna)]; The arch was rediscovered in 1928 [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Septimius_Severus_(Leptis_Magna)]; The arch was rebuilt after its rediscovery [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Septimius_Severus_(Leptis_Magna)]"}]'::jsonb),
    ('3c579791-33d8-46bd-90da-1551035cc419'::uuid, 'card_description', 'Auxiliary fort on Hadrian Wall called Brocolitia -- a Celtic place-name likely meaning "badger holes." Outside the fort walls stood a well-preserved temple to the god Mithras.', 'In low-lying marshy ground beyond its Roman fort on Hadrian''s Wall, Carrawburgh keeps the remains of three sanctuaries, one an early 3rd century temple of the mystery cult of Mithras.', 'teaser-card-s027:3c579791-33d8-46bd-90da-1551035cc419:card_description', 'teaser-card-s027 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '1575be4b17beee038df3d288d6662d2035b443d52a63c6ab05c11705e547c381|9dd471ac39c1c1861c304a4f3d6c912281813309d8a168c78ff382842c79d74b|9dd471ac39c1c1861c304a4f3d6c912281813309d8a168c78ff382842c79d74b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In low-lying marshy ground beyond its Roman fort on Hadrian''s Wall, Carrawburgh keeps the remains of three sanctuaries, one an early 3rd century temple of the mystery cult of Mithras."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Carrawburgh has a Roman fort on Hadrian''s Wall [S2]; the remains of three sanctuaries are there [S7]; they lie in low-lying marshy ground beyond the fort [S7]; one of the sanctuaries is a temple of the mystery cult of Mithras [S8]; that temple dates to the early 3rd century [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Carrawburgh is the site of a Roman fort on Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Carrawburgh]; Sanctuary remains lie in low-lying marshy ground [SUPPORTED: https://en.wikipedia.org/wiki/Carrawburgh]; The marshy ground with the sanctuaries lies beyond the fort [SUPPORTED: https://en.wikipedia.org/wiki/Carrawburgh]; The remains of three Roman sanctuaries have been found at Carrawburgh [SUPPORTED: https://en.wikipedia.org/wiki/Carrawburgh]; One of the sanctuaries is a temple of the mystery cult of Mithras [SUPPORTED: https://en.wikipedia.org/wiki/Carrawburgh]; The Mithras temple dates to the early 3rd century [SUPPORTED: https://en.wikipedia.org/wiki/Carrawburgh]"}]'::jsonb),
    ('3d296ec1-adcb-43da-ae08-ffcdb378d4be'::uuid, 'card_description', 'Three standing stones up to 6.9 meters tall, grooved by millennia of rainfall. Originally more existed — a fourth was re-erected in 1903 to improve the skyline.', 'Grooved by millennia of rainfall, the three Devil''s Arrows stand in an almost straight line outside Boroughbridge. The tallest reaches 22.5 feet; the stones came from Brimham Rocks.', 'teaser-card-s027:3d296ec1-adcb-43da-ae08-ffcdb378d4be:card_description', 'teaser-card-s027 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '14a2bd9be04f9482a516c5b58e12c215a36c75c7ce9ee1a5eed0a3a48d6894b1|6d1a4f8e35b05968620461340252c398dec61d4f2db0168ba1057876fad7dd7f|6d1a4f8e35b05968620461340252c398dec61d4f2db0168ba1057876fad7dd7f', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Grooved by millennia of rainfall, the three Devil''s Arrows stand in an almost straight line outside Boroughbridge. The tallest reaches 22.5 feet; the stones came from Brimham Rocks."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the stones are grooved by millennia of rainfall [S3]; there are three Devil''s Arrows [S1]; they stand in an almost straight line [S2]; they stand outside Boroughbridge [S1]; the tallest stone is 22.5 feet high [S3]; the stones came from Brimham Rocks [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Devil''s Arrows are standing stones [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Arrows]; There are three Devil''s Arrows stones [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Arrows]; The stones stand outside Boroughbridge [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Arrows]; The three stones stand in an almost straight line [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Arrows]; The stones are grooved by rainfall [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Arrows]; The grooving took millennia [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Arrows]; The tallest stone is 22.5 feet high [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Arrows]; The stones came from Brimham Rocks [SUPPORTED: https://www.york.ac.uk/news-and-events/news/2026/research/neolithic-devils-arrow-stones-travelled-miles/]"}]'::jsonb),
    ('3dd6b568-007f-4a95-877b-12324e031893'::uuid, 'card_description', 'A site along the Qhapaq Nan, the Inca road system that stretched over 30,000 km across the Andes. Way stations like this kept the empire''s relay messengers running.', 'Along a section of the Qhapaq Ñan, the Inca road system, lies Maray Qalla in Peru''s Ancash Region. In Quechua, maray can mean grindstone and qalla carved stone or cobblestone.', 'teaser-card-s027:3dd6b568-007f-4a95-877b-12324e031893:card_description', 'teaser-card-s027 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '87920d92be7fcaeea7cce4e65c07a391e546c0e6b9f86a95690cf32dd132261c|5a224c5dd4859f40abf2d7840a40d7d027f23969084aaff193bb9f61c6fde3cd|5a224c5dd4859f40abf2d7840a40d7d027f23969084aaff193bb9f61c6fde3cd', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Along a section of the Qhapaq Ñan, the Inca road system, lies Maray Qalla in Peru''s Ancash Region. In Quechua, maray can mean grindstone and qalla carved stone or cobblestone."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Maray Qalla lies along a section of the Qhapaq Ñan [S3]; the Qhapaq Ñan is the Inca road system [S3]; Maray Qalla is in Peru [S1]; it is in the Ancash Region [S2]; the names are Quechua [S1]; maray can mean grindstone [S1]; qalla can mean carved stone or cobblestone [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Maray Qalla is an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Maray_Qalla]; Maray Qalla is in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Maray_Qalla]; Maray Qalla is in Peru''s Ancash Region [SUPPORTED: https://en.wikipedia.org/wiki/Maray_Qalla]; Maray Qalla lies along a section of the Qhapaq Ñan [SUPPORTED: https://en.wikipedia.org/wiki/Maray_Qalla]; The Qhapaq Ñan is the Inca road system [SUPPORTED: https://en.wikipedia.org/wiki/Maray_Qalla]; In Quechua, maray can mean grindstone [SUPPORTED: https://en.wikipedia.org/wiki/Maray_Qalla]; In Quechua, qalla can mean carved stone [SUPPORTED: https://en.wikipedia.org/wiki/Maray_Qalla]; In Quechua, qalla can mean cobblestone [SUPPORTED: https://en.wikipedia.org/wiki/Maray_Qalla]"}]'::jsonb),
    ('3debd642-ff96-4840-bff2-9d8faced25cd'::uuid, 'card_description', NULL, 'On Dorset''s chalk uplands, the large multivallate hillfort of Eggardon Hill encloses approximately 21ha. Older Bronze Age earthworks cross its interior, and two bowl barrows lie within.', 'teaser-card-s027:3debd642-ff96-4840-bff2-9d8faced25cd:card_description', 'teaser-card-s027 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '2067a0b3f24353be06b1ec001134085b70ef9c75603c37139852f8c894fe4f75|e638d0c2f188fd8f165f8a2f33a90dd5520047fda1ba92f2086564ff18d65066|e638d0c2f188fd8f165f8a2f33a90dd5520047fda1ba92f2086564ff18d65066', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Dorset''s chalk uplands, the large multivallate hillfort of Eggardon Hill encloses approximately 21ha. Older Bronze Age earthworks cross its interior, and two bowl barrows lie within."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Eggardon Hill lies on Dorset''s chalk uplands [S1, S2]; it is a large multivallate hillfort [S6]; it encloses approximately 21 hectares [S7]; earthworks crossing its interior are older than the hillfort [S3, S6]; those earthworks are Bronze Age [S4]; two bowl barrows lie within the hillfort [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Eggardon Hill is a hillfort in Dorset [SUPPORTED: https://en.wikipedia.org/wiki/Eggardon_Hill]; It lies on Dorset''s chalk uplands [SUPPORTED: https://en.wikipedia.org/wiki/Eggardon_Hill]; The hillfort is large and multivallate [SUPPORTED: https://en.wikipedia.org/wiki/Eggardon_Hill]; The earthworks enclose approximately 21ha [SUPPORTED: https://en.wikipedia.org/wiki/Eggardon_Hill]; Older Bronze Age earthworks cross the interior of the hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Eggardon_Hill]; Two bowl barrows lie within the hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Eggardon_Hill]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s027', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s027'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s027'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK: nothing may have changed
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s027'
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
-- `_teaser_card_plan` is a CREATE TEMP TABLE, so it lives in this session's `pg_temp_N` schema and
-- `nspname = 'public'` could never match it - the old form of this read was 0 whatever happened.
-- `to_regclass('pg_temp....')` resolves the current session's temp schema and is NULL when the
-- table is gone, so this reads 1 exactly when a leftover exists.
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
